package com.loadoutlab.engine;

import static org.junit.Assert.*;

import org.junit.Test;

import java.util.Arrays;
import java.util.concurrent.CancellationException;

public class ProbabilityFoundationTest {
    private static final double EPS = 1e-10;

    @Test
    public void damageTransformMergesCollisionsAndPreservesMass() {
        DamagePmf source = new DamagePmf(.1, .2, .3, .4);
        assertArrayEquals(new double[] {.3, .7}, source.map(d -> d / 2).probabilities(), EPS);
        assertArrayEquals(new double[] {.1, .2, .3, .4}, source.probabilities(), 0);
        assertThrows(IllegalArgumentException.class, () -> source.map(d -> -1));
        assertThrows(IllegalArgumentException.class, () -> source.map(d -> 10001));
    }

    @Test
    public void rollFormulaMatchesExhaustiveOrderedPairs() {
        for (int a = 0; a <= 25; a++)
            for (int d = 0; d <= 25; d++) {
                int wins = 0;
                for (int x = 0; x <= a; x++) for (int y = 0; y <= d; y++) if (x > y) wins++;
                assertEquals(
                        wins / (double) ((a + 1) * (d + 1)),
                        RollContest.successProbability(a, d),
                        EPS);
            }
    }

    @Test
    public void rollMaximaDoNotOverflow() {
        assertEquals(
                0.5 - 1.0 / 4294967296.0,
                RollContest.successProbability(Integer.MAX_VALUE, Integer.MAX_VALUE),
                EPS);
        assertEquals(
                1 - 1.0 / 2147483648.0, RollContest.successProbability(Integer.MAX_VALUE, 0), EPS);
        assertEquals(0, RollContest.successProbability(0, Integer.MAX_VALUE), 0);
        assertThrows(IllegalArgumentException.class, () -> RollContest.successProbability(-1, 0));
    }

    @Test
    public void singleHitDistinguishesMissesAndSuccessfulZero() {
        assertArrayEquals(
                new double[] {0.5, 0.25, 0.25},
                DamagePmf.singleHit(0.5, 1, 2).probabilities(),
                EPS);
        assertArrayEquals(
                new double[] {0.5, 0.25, 0.25},
                DamagePmf.singleHit(0.75, 0, 2).probabilities(),
                EPS);
        assertArrayEquals(new double[] {1}, DamagePmf.singleHit(0, 1, 20).probabilities(), EPS);
        assertArrayEquals(new double[] {1}, DamagePmf.singleHit(1, 0, 0).probabilities(), EPS);
    }

    @Test
    public void probabilitiesAreValidatedAndImmutable() {
        double[] source = {0.5, 0.5, 0};
        DamagePmf p = new DamagePmf(source);
        source[0] = 0;
        p.probabilities()[0] = 0;
        assertEquals(0.5, p.probabilityAt(0), 0);
        assertEquals(1, p.maximum());
        assertEquals(0, p.probabilityAt(-1), 0);
        assertEquals(0, p.probabilityAt(100), 0);
        for (double bad : new double[] {Double.NaN, Double.POSITIVE_INFINITY, -0.1, 1.1}) {
            assertThrows(IllegalArgumentException.class, () -> new DamagePmf(bad));
        }
        assertThrows(IllegalArgumentException.class, () -> new DamagePmf(0.2, 0.2));
        assertThrows(IllegalArgumentException.class, () -> new DamagePmf());
        assertThrows(IllegalArgumentException.class, () -> DamagePmf.singleHit(1, 2, 1));
    }

    @Test
    public void independentSumMatchesEnumeratedDice() {
        DamagePmf die = DamagePmf.singleHit(1, 0, 5);
        double[] expected = new double[11];
        for (int a = 0; a <= 5; a++) for (int b = 0; b <= 5; b++) expected[a + b] += 1.0 / 36;
        DamagePmf sum = die.independentSum(die);
        assertArrayEquals(expected, sum.probabilities(), EPS);
        assertEquals(5, sum.mean(), EPS);
        assertEquals(10, sum.maximum());
        assertEquals(2, sum.dps(2.5), EPS);
        assertThrows(IllegalArgumentException.class, () -> sum.dps(0));
        assertThrows(IllegalArgumentException.class, () -> sum.dps(Double.NaN));
    }

    @Test
    public void mixtureIsNotIndependentAddition() {
        DamagePmf zero = new DamagePmf(1);
        DamagePmf two = new DamagePmf(0, 0, 1);
        assertArrayEquals(
                new double[] {0.25, 0, 0.75}, zero.mixture(0.25, two).probabilities(), EPS);
        assertArrayEquals(two.probabilities(), zero.independentSum(two).probabilities(), EPS);
        assertThrows(IllegalArgumentException.class, () -> zero.mixture(2, two));
    }

    @Test
    public void deterministicDamageIncludesOverkillAndExplicitFirstHitDelay() {
        DamagePmf hit = DamagePmf.singleHit(1, 3, 3);
        StationaryKill.Moments moments = StationaryKill.moments(hit, 7);
        assertEquals(3, moments.expectedAttacks(), EPS);
        assertEquals(0, moments.attackVariance(), EPS);
        assertEquals(4, moments.expectedSeconds(2, 0), EPS);
        assertEquals(6, moments.expectedSeconds(2, 2), EPS);
        assertArrayEquals(new double[] {0, 0, 1, 0}, StationaryKill.horizon(hit, 7, 3), EPS);
    }

    @Test
    public void bernoulliKillMatchesNegativeBinomialMomentsAndPreservesTail() {
        DamagePmf hit = new DamagePmf(0.5, 0.5);
        for (int hp = 1; hp <= 10; hp++) {
            StationaryKill.Moments moments = StationaryKill.moments(hit, hp);
            assertEquals(2.0 * hp, moments.expectedAttacks(), EPS);
            assertEquals(2.0 * hp, moments.attackVariance(), EPS);
        }
        assertArrayEquals(
                new double[] {0.5, 0.25, 0.125, 0.125}, StationaryKill.horizon(hit, 1, 3), EPS);
        assertArrayEquals(new double[] {1}, StationaryKill.horizon(hit, 1, 0), EPS);
    }

    @Test
    public void horizonMatchesBruteForceAttackSequences() {
        DamagePmf hit = new DamagePmf(0.25, 0.25, 0.5);
        double[] expected = new double[5];
        enumerate(hit, 4, 0, 4, 1, expected);
        double[] actual = StationaryKill.horizon(hit, 4, 4);
        assertArrayEquals(expected, actual, EPS);
        assertEquals(1, Arrays.stream(actual).sum(), EPS);
        StationaryKill.Moments simple = StationaryKill.moments(new DamagePmf(0, 0.5, 0.5), 2);
        assertEquals(1.5, simple.expectedAttacks(), EPS);
        assertEquals(0.25, simple.attackVariance(), EPS);
    }

    private static void enumerate(
            DamagePmf p, int hp, int turn, int limit, double weight, double[] bins) {
        if (hp <= 0) {
            bins[turn - 1] += weight;
            return;
        }
        if (turn == limit) {
            bins[limit] += weight;
            return;
        }
        for (int damage = 0; damage <= p.maximum(); damage++) {
            enumerate(p, hp - damage, turn + 1, limit, weight * p.probabilityAt(damage), bins);
        }
    }

    @Test
    public void impossibleAndVeryRareDamageRemainDistinct() {
        StationaryKill.Moments impossible = StationaryKill.moments(new DamagePmf(1), 1);
        assertEquals(Double.POSITIVE_INFINITY, impossible.expectedAttacks(), 0);
        assertTrue(Double.isNaN(impossible.attackVariance()));
        assertArrayEquals(
                new double[] {0, 0, 1}, StationaryKill.horizon(new DamagePmf(1), 5, 2), EPS);
        assertEquals(
                1e15,
                StationaryKill.moments(new DamagePmf(1 - 1e-15, 1e-15), 1).expectedAttacks(),
                1);
    }

    @Test
    public void costlyRequestsFailBeforeAllocationAndCancellationIsPreserved() {
        DamagePmf hit = DamagePmf.singleHit(1, 0, 10_000);
        assertThrows(IllegalArgumentException.class, () -> hit.independentSum(hit));
        assertThrows(IllegalArgumentException.class, () -> StationaryKill.moments(hit, 100_000));
        assertThrows(
                IllegalArgumentException.class,
                () -> StationaryKill.horizon(hit, 100, Integer.MAX_VALUE));
        assertThrows(IllegalArgumentException.class, () -> StationaryKill.moments(hit, 0));
        Thread.currentThread().interrupt();
        try {
            assertThrows(CancellationException.class, () -> StationaryKill.moments(hit, 1));
            assertTrue(Thread.currentThread().isInterrupted());
        } finally {
            Thread.interrupted();
        }
    }
}

package com.dpscalc.scenario;

import net.runelite.api.*;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.config.ConfigManager;

import java.util.*;

import javax.inject.Inject;
import javax.inject.Singleton;

/** Updated only on the client thread; readers receive immutable snapshots. */
@Singleton
public final class BankCapture {
    @Inject private Client client;
    @Inject private ConfigManager config;
    private volatile OwnedEquipment snapshot = OwnedEquipment.empty(0);
    private Item[] bankItems;
    private boolean pending, bankChanged;
    private String profile;

    public OwnedEquipment snapshot() {
        return snapshot;
    }

    public synchronized void playerChanged() {
        pending = true;
    }

    public synchronized void clear() {
        bankItems = null;
        pending = false;
        bankChanged = false;
        profile = null;
        snapshot = OwnedEquipment.empty(snapshot.revision + 1);
    }

    private void checkProfile() {
        String next = config.getRSProfileKey();
        if (!Objects.equals(profile, next)) {
            clear();
            profile = next;
        }
    }

    public synchronized void changed(ItemContainerChanged event) {
        checkProfile();
        int id = event.getContainerId();
        if (id == InventoryID.BANK.getId()) {
            bankItems = event.getItemContainer().getItems().clone();
            bankChanged = true;
            pending = true;
        }
        if (id == InventoryID.INVENTORY.getId() || id == InventoryID.EQUIPMENT.getId())
            pending = true;
    }

    public synchronized void tick() {
        checkProfile();
        if (!pending || profile == null) return;
        pending = false;
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY),
                gear = client.getItemContainer(InventoryID.EQUIPMENT);
        if (inv == null || gear == null) {
            pending = true;
            return;
        }
        Map<String, Integer> levels = new TreeMap<>();
        for (Skill skill : Skill.values())
            if (skill != Skill.OVERALL)
                levels.put(skill.name().toLowerCase(Locale.ROOT), client.getRealSkillLevel(skill));
        if (client.getLocalPlayer() != null)
            levels.put("combat", client.getLocalPlayer().getCombatLevel());
        Map<Integer, Integer> bank = bankChanged ? normalize(bankItems) : snapshot.bank,
                inventory = normalize(inv.getItems()),
                equipped = normalize(gear.getItems());
        if (bankChanged
                || !bank.equals(snapshot.bank)
                || !inventory.equals(snapshot.inventory)
                || !equipped.equals(snapshot.equipped)
                || !levels.equals(snapshot.levels)) {
            Map<Integer, String> names = new TreeMap<>();
            for (Map<Integer, Integer> container : Arrays.asList(bank, inventory, equipped))
                for (int id : container.keySet()) {
                    ItemComposition definition = client.getItemDefinition(id);
                    if (definition != null && definition.getName() != null)
                        names.put(id, definition.getName());
                }
            snapshot =
                    new OwnedEquipment(
                            profile,
                            snapshot.revision + 1,
                            bankChanged ? System.currentTimeMillis() : snapshot.bankScannedAt,
                            bank,
                            inventory,
                            equipped,
                            levels,
                            names);
        }
        bankChanged = false;
    }

    private Map<Integer, Integer> normalize(Item[] items) {
        Map<Integer, Integer> result = new TreeMap<>();
        if (items == null) return result;
        for (Item item : items) {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) continue;
            ItemComposition definition = client.getItemDefinition(item.getId());
            addItem(
                    result,
                    item.getId(),
                    item.getQuantity(),
                    definition.getPlaceholderTemplateId() != -1,
                    definition.getNote() != -1,
                    definition.getLinkedNoteId());
        }
        return result;
    }

    static void addItem(
            Map<Integer, Integer> result,
            int original,
            int quantity,
            boolean placeholder,
            boolean noted,
            int linked) {
        if (original <= 0 || quantity <= 0 || placeholder) return;
        int id = noted ? linked : original;
        if (id > 0)
            result.merge(id, quantity, (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
    }
}

package com.dpscalc.scenario;

import net.runelite.client.game.ItemManager;

import java.awt.*;
import java.util.function.*;

import javax.swing.*;

/** Keeps the preview and error together, and permits retrying a failed create. */
final class BankLayoutPanel extends JPanel {
    private final JTextField name;
    private final JButton create;
    private final JTextArea status =
            CalculatorWorkspace.note("Choose a new name. Existing bank tabs will be kept.");
    private boolean busy, complete;

    BankLayoutPanel(
            Scenario.Loadout draft,
            BankLayoutPlan plan,
            Supplier<ItemManager> items,
            BiConsumer<String, Consumer<BankLayoutService.Result>> writer) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(CalculatorWorkspace.BG);
        add(CalculatorWorkspace.label("New bank tab name", CalculatorWorkspace.GOLD));
        name = new JTextField(BankLayoutPlan.suggestedName(draft.name), 30);
        name.getAccessibleContext().setAccessibleName("New bank tab name");
        add(name);
        JPanel cells = new JPanel(new GridLayout(0, 8, 3, 3));
        cells.setBackground(CalculatorWorkspace.BG);
        int last = plan.positions.keySet().stream().mapToInt(Integer::intValue).max().orElse(0);
        for (int pos = 0; pos < ((last / 8) + 1) * 8; pos++) {
            Integer id = plan.positions.get(pos);
            JLabel cell = new JLabel("", SwingConstants.CENTER);
            cell.setForeground(CalculatorWorkspace.TEXT);
            cell.setPreferredSize(new Dimension(38, 35));
            cell.setBorder(BorderFactory.createLineBorder(CalculatorWorkspace.EDGE));
            if (id != null) {
                cell.setToolTipText("Item " + id);
                ItemManager manager = items.get();
                if (manager != null) {
                    net.runelite.client.util.AsyncBufferedImage image = manager.getImage(id);
                    cell.setIcon(new ImageIcon(image));
                    image.onLoaded(cell::repaint);
                } else cell.setText(id.toString());
            }
            cells.add(cell);
        }
        add(cells);
        JTextArea note =
                CalculatorWorkspace.note(
                        "Snapshot of "
                                + draft.name
                                + ". Equipment left · inventory right · pouch below equipment ·"
                                + " optional switches at the bottom. Quantities and withdrawals"
                                + " remain manual.");
        note.setColumns(38);
        note.setRows(4);
        add(note);
        create =
                CalculatorWorkspace.action(
                        "Create bank tab",
                        () -> {
                            if (busy || complete) return;
                            try {
                                String tag = BankLayoutPlan.tagName(name.getText());
                                busy = true;
                                name.setEnabled(false);
                                createState();
                                status.setText("Creating bank tab…");
                                writer.accept(
                                        tag,
                                        result -> {
                                            busy = false;
                                            complete = result.success;
                                            name.setEnabled(!complete);
                                            status.setText(result.message);
                                            createState();
                                        });
                            } catch (RuntimeException error) {
                                busy = false;
                                name.setEnabled(true);
                                status.setText(error.getMessage());
                                createState();
                            }
                        });
        add(create);
        status.setRows(4);
        status.getAccessibleContext().setAccessibleName("Bank layout creation status");
        add(status);
        CalculatorWorkspace.theme(this);
    }

    private void createState() {
        create.setEnabled(!busy && !complete);
        create.setText(complete ? "Bank tab created" : busy ? "Creating…" : "Create bank tab");
        revalidate();
        repaint();
    }
}

package com.dpscalc.scenario;

import java.util.*;

/** A bank layout is an arrangement of item IDs, not withdrawal quantities. */
public final class BankLayoutPlan {
    public final Map<Integer, Integer> positions;

    private BankLayoutPlan(Map<Integer, Integer> positions) {
        this.positions = Collections.unmodifiableMap(positions);
    }

    public static String suggestedName(String loadout) {
        String name =
                ("DPS " + loadout)
                        .replaceAll("[^a-zA-Z0-9 _()'\\-]", " ")
                        .replaceAll("\\s+", " ")
                        .trim();
        return name.substring(0, Math.min(60, name.length())).trim();
    }

    public static BankLayoutPlan from(Scenario.Loadout loadout) {
        Scenario.validate(loadout);
        Map<Integer, Integer> positions = new TreeMap<>();
        int[] slots = {0, 1, 2, 13, 3, 4, 5, 7, 9, 10, 12},
                cells = {1, 8, 9, 10, 16, 17, 18, 25, 32, 33, 34};
        for (int i = 0; i < slots.length; i++) {
            int id = loadout.player.getEquippedItemIds()[slots[i]];
            if (id > 0) positions.put(cells[i], id);
        }
        for (int i = 0; i < 28; i++) {
            CarryPlan.Entry entry = loadout.carry.slots[i];
            if (entry != null && entry.id > 0) positions.put((i / 4) * 8 + 4 + i % 4, entry.id);
        }
        for (int i = 0; i < 4; i++) {
            CarryPlan.Entry entry = loadout.carry.runes[i];
            if (entry != null && entry.id > 0) positions.put(40 + i, entry.id);
        }
        int cell = 64;
        for (CarryPlan.Entry entry : loadout.carry.switches)
            if (entry != null && entry.id > 0 && !positions.containsValue(entry.id))
                positions.put(cell++, entry.id);
        if (positions.isEmpty())
            throw new IllegalArgumentException(
                    "Add equipment or supplies before creating a bank layout");
        return new BankLayoutPlan(positions);
    }

    public static String tagName(String raw) {
        String name = raw.trim().toLowerCase(Locale.ROOT);
        if (!name.matches("[a-z0-9 _()'\\-]{1,60}"))
            throw new IllegalArgumentException(
                    "Use 1–60 letters, numbers, spaces, apostrophes, parentheses or hyphens for the"
                            + " bank tab name");
        return name;
    }
}

package com.dpscalc.scenario;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.*;
import net.runelite.client.plugins.banktags.tabs.*;
import net.runelite.client.util.Text;

import java.util.*;
import java.util.function.Consumer;
import java.util.stream.Collectors;

import javax.inject.*;
import javax.swing.SwingUtilities;

/**
 * Writes only new, explicitly requested tags on the client thread. Existing tags are never
 * replaced.
 */
@Singleton
public final class BankLayoutService {
    private static final org.slf4j.Logger log =
            org.slf4j.LoggerFactory.getLogger(BankLayoutService.class);
    private final Client client;
    private final ClientThread thread;
    private final ConfigManager config;
    private final PluginManager plugins;

    @Inject
    public BankLayoutService(
            Client client, ClientThread thread, ConfigManager config, PluginManager plugins) {
        this.client = client;
        this.thread = thread;
        this.config = config;
        this.plugins = plugins;
    }

    public static final class Result {
        public final boolean success;
        public final String message;

        public Result(boolean success, String message) {
            this.success = success;
            this.message = message;
        }
    }

    public void create(
            String raw,
            BankLayoutPlan plan,
            String profile,
            long configProfile,
            Consumer<Result> done) {
        String name = BankLayoutPlan.tagName(raw);
        thread.invokeLater(
                () -> {
                    Result result;
                    try {
                        BankTagsPlugin bankTags =
                                plugins.getPlugins().stream()
                                        .filter(p -> p instanceof BankTagsPlugin)
                                        .map(p -> (BankTagsPlugin) p)
                                        .findFirst()
                                        .orElse(null);
                        if (bankTags == null
                                || !plugins.isPluginActive(bankTags)
                                || !plugins.isPluginEnabled(bankTags))
                            throw new IllegalStateException(
                                    "Enable RuneLite's Bank Tags plugin first.");
                        // Core plugins have their own child injectors. Reuse the active plugin's
                        // services; constructing these in our scope would create an unloaded bank
                        // UI.
                        TagManager tags = bankTags.getInjector().getInstance(TagManager.class);
                        TabManager tabs = bankTags.getInjector().getInstance(TabManager.class);
                        LayoutManager layouts =
                                bankTags.getInjector().getInstance(LayoutManager.class);
                        net.runelite.api.widgets.Widget bank =
                                client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
                        BankLayoutWriter.requireLoaded(
                                bank != null && !bank.isHidden(),
                                config.getConfig(BankTagsConfig.class).tabs(),
                                Text.fromCSV(
                                        Objects.toString(
                                                config.getConfiguration(
                                                        BankTagsPlugin.CONFIG_GROUP,
                                                        BankTagsPlugin.TAG_TABS_CONFIG),
                                                "")),
                                tabs.getTabs().stream()
                                        .map(TagTab::getTag)
                                        .collect(Collectors.toList()));
                        BankLayoutWriter.create(
                                new BankLayoutWriter.Backend() {
                                    public boolean currentProfile() {
                                        return profile != null
                                                && profile.equals(config.getRSProfileKey())
                                                && configProfile == config.getProfile().getId();
                                    }

                                    public boolean enabled() {
                                        return plugins.isPluginEnabled(bankTags)
                                                && plugins.isPluginActive(bankTags);
                                    }

                                    public boolean exists(String tag) {
                                        return tabs.find(tag) != null
                                                || layouts.loadLayout(tag) != null
                                                || !tags.getItemsForTag(tag).isEmpty();
                                    }

                                    public void tag(int id, String tag) {
                                        tags.addTag(id, tag, false);
                                    }

                                    public void layout(String tag, BankLayoutPlan plan) {
                                        Layout layout = new Layout(tag);
                                        plan.positions.forEach(
                                                (pos, id) -> layout.setItemAtPos(id, pos));
                                        layouts.saveLayout(layout);
                                    }

                                    public void tab(String tag, int icon) {
                                        TagTab tab = new TagTab();
                                        tab.setTag(tag);
                                        tab.setIconItemId(icon);
                                        tabs.add(tab);
                                    }

                                    public void save() {
                                        tabs.save();
                                    }

                                    public void removeNew(String tag) {
                                        tags.removeTag(tag);
                                        layouts.removeLayout(tag);
                                        tabs.remove(tag);
                                        tabs.save();
                                    }
                                },
                                name,
                                plan);
                        try {
                            bankTags.openBankTag(name);
                            result = new Result(true, "Created and opened bank tag: " + name);
                        } catch (RuntimeException error) {
                            log.warn("Created bank layout but could not open its tab", error);
                            result =
                                    new Result(
                                            true,
                                            "Created bank tag: "
                                                    + name
                                                    + ". Reopen your bank to view it.");
                        }
                    } catch (RuntimeException error) {
                        log.debug("Bank layout creation did not complete", error);
                        result =
                                new Result(
                                        false,
                                        Objects.toString(
                                                error.getMessage(),
                                                "Bank layout creation failed. Please try again."));
                    }
                    Result completed = result;
                    SwingUtilities.invokeLater(() -> done.accept(completed));
                });
    }
}

package com.dpscalc.scenario;

import java.util.*;

/** Transaction boundary, tested without a game client. Only new names may be written. */
final class BankLayoutWriter {
    static void requireLoaded(
            boolean bankOpen, boolean tabsEnabled, List<String> saved, List<String> loaded) {
        if (!bankOpen) throw new IllegalStateException("Open your bank, then click Create again.");
        if (!tabsEnabled)
            throw new IllegalStateException(
                    "Enable Use Tag Tabs in RuneLite's Bank Tags settings, then reopen your bank.");
        if (!saved.equals(loaded))
            throw new IllegalStateException(
                    "Bank Tags has not loaded all your saved tabs. Close and reopen your bank, then"
                            + " try again.");
    }

    interface Backend {
        boolean currentProfile();

        boolean enabled();

        boolean exists(String name);

        void tag(int id, String name);

        void layout(String name, BankLayoutPlan plan);

        void tab(String name, int icon);

        void save();

        void removeNew(String name);
    }

    static void create(Backend backend, String name, BankLayoutPlan plan) {
        if (!backend.currentProfile())
            throw new IllegalStateException(
                    "Character or RuneLite profile changed. Reopen the layout preview.");
        if (!backend.enabled())
            throw new IllegalStateException("Enable RuneLite's Bank Tags plugin first.");
        if (backend.exists(name))
            throw new IllegalStateException(
                    "That bank tag already exists. Choose a new name to keep its layout and items"
                            + " safe.");
        try {
            for (int id : new LinkedHashSet<>(plan.positions.values())) backend.tag(id, name);
            backend.layout(name, plan);
            backend.tab(name, plan.positions.values().iterator().next());
            backend.save();
        } catch (RuntimeException error) {
            try {
                backend.removeNew(name);
            } catch (RuntimeException rollback) {
                error.addSuppressed(rollback);
            }
            throw error;
        }
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;
import com.loadoutlab.equipment.*;
import com.loadoutlab.model.*;
import com.loadoutlab.model.MonsterStats;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.IntConsumer;

/** Searches owned, compatible equipment. Large searches deliberately report best-found. */
public final class BankOptimizer {
    public static final int[] SLOTS = {0, 1, 2, 3, 4, 5, 7, 9, 10, 12, 13};
    public static final String[] SLOT_NAMES = {
        "Head", "Cape", "Neck", "Weapon", "Body", "Shield", "Legs", "Hands", "Feet", "Ring", "Ammo"
    };
    private static final String[] CATALOG_SLOTS = {
        "head", "cape", "neck", "weapon", "body", "shield", "legs", "hands", "feet", "ring", "ammo"
    };
    private static final String[] SETS = {
        "Elite void",
        "Void",
        "Dharok",
        "Verac",
        "Guthan",
        "Torag",
        "Karil",
        "Ahrim",
        "Obsidian",
        "Inquisitor",
        "Justiciar",
        "Crystal",
        "Virtus",
        "Blood moon",
        "Blue moon",
        "Eclipse moon"
    };
    // These owned blessings have no additional equip-level requirement. Acquisition
    // requirements for diary rewards are not equip requirements (see NOTICE.md).
    private static final Set<Integer> BLESSINGS_WITHOUT_LEVEL_REQUIREMENTS =
            Set.of(20220, 20223, 20226, 20229, 20232, 20235, 22941, 22943, 22945, 22947);
    private final EquipmentPreparationFacade equipment;
    private final ScenarioCalculator calculator;
    private final List<OptimizerSpell> spellCatalog = OptimizerSpell.load();
    private final Map<Integer, Map<String, Integer>> requirements = new HashMap<>();

    public BankOptimizer(EquipmentPreparationFacade equipment) {
        this.equipment = equipment;
        calculator = new ScenarioCalculator(equipment);
        try (Reader reader =
                new InputStreamReader(
                        getClass()
                                .getResourceAsStream("/com/loadoutlab/equipment-requirements.json"),
                        StandardCharsets.UTF_8)) {
            for (Map.Entry<String, JsonElement> entry :
                    new JsonParser().parse(reader).getAsJsonObject().entrySet()) {
                Map<String, Integer> levels = new HashMap<>();
                entry.getValue()
                        .getAsJsonObject()
                        .entrySet()
                        .forEach(e -> levels.put(e.getKey(), e.getValue().getAsInt()));
                requirements.put(Integer.parseInt(entry.getKey()), levels);
            }
        } catch (IOException ex) {
            throw new IllegalStateException("Equipment requirements unavailable", ex);
        }
    }

    public static String family(Scenario.Loadout loadout) {
        AttackType type = loadout.player.getCombatStyle().getAttackType();
        return type.isMagic() ? "Magic" : type.isRanged() ? "Ranged" : "Melee";
    }

    public static final class Request {
        public final Scenario.Loadout base;
        public final Scenario.Loadout baseline;
        public final MonsterStats target;
        public final OwnedEquipment owned;
        public final Set<Integer> locked;
        public final boolean includeUnverified;
        public final boolean includeKnownLimitations;
        public final String combatType;
        public final Encounter encounter;

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified) {
            this(base, target, owned, locked, includeUnverified, family(base));
        }

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified,
                String combatType) {
            this(base, target, owned, locked, includeUnverified, combatType, base);
        }

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified,
                String combatType,
                Encounter encounter) {
            this(base, target, owned, locked, includeUnverified, combatType, base, encounter);
        }

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified,
                String combatType,
                Scenario.Loadout baseline) {
            this(
                    base,
                    target,
                    owned,
                    locked,
                    includeUnverified,
                    combatType,
                    baseline,
                    new Encounter());
        }

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified,
                String combatType,
                Scenario.Loadout baseline,
                Encounter encounter) {
            this(
                    base,
                    target,
                    owned,
                    locked,
                    includeUnverified,
                    combatType,
                    baseline,
                    encounter,
                    false);
        }

        public Request(
                Scenario.Loadout base,
                MonsterStats target,
                OwnedEquipment owned,
                Set<Integer> locked,
                boolean includeUnverified,
                String combatType,
                Scenario.Loadout baseline,
                Encounter encounter,
                boolean includeKnownLimitations) {
            this.includeKnownLimitations = includeKnownLimitations;
            encounter.validate();
            this.encounter = encounter.copy();
            if (!Set.of("Melee", "Ranged", "Magic").contains(combatType))
                throw new IllegalArgumentException("Choose Melee, Ranged or Magic");
            this.combatType = combatType;
            this.baseline = baseline.copy();
            this.base = base.copy();
            this.target = target == null ? null : target.copy();
            this.owned = owned;
            this.locked = Set.copyOf(locked);
            this.includeUnverified = includeUnverified;
        }
    }

    public static final class Result {
        public final List<Scenario.Loadout> alternatives = new ArrayList<>();
        public final List<ScenarioCalculator.Result> calculations = new ArrayList<>();
        public final List<String> exclusions = new ArrayList<>();
        public int evaluated;
        public boolean exhaustive;
        public Double baselineDps, baselineGroupDps;
    }

    public Result search(Request request, IntConsumer progress) {
        return search(request, progress, 20000, 15000);
    }

    public Result search(Request request, IntConsumer progress, int budget, long milliseconds) {
        if (request.target == null) throw new IllegalArgumentException("Select a target first");
        if (!request.owned.ready(request.owned.profile))
            throw new IllegalArgumentException("Open your bank to scan equipment first");
        if (request.base.manualEquipmentStats)
            throw new IllegalArgumentException(
                    "Use item-based equipment totals before generating gear");
        Scenario.validate(request.base);
        Scenario.validate(request.target);
        List<String> targetLimits = CoverageWarnings.forTarget(request.target);
        if (!request.includeKnownLimitations && !targetLimits.isEmpty())
            throw new IllegalArgumentException(
                    request.target.getName()
                            + " has known formula limitations. Enable 'Include known formula"
                            + " limitations' in Advanced options to generate estimates. "
                            + String.join(" ", targetLimits));
        Search search = new Search(request, progress, budget, milliseconds);
        return search.run();
    }

    private final class Search {
        final Request request;
        final IntConsumer progress;
        final int budget;
        final long deadline;
        final Result result = new Result();
        final Map<Integer, List<Integer>> pools = new LinkedHashMap<>();
        final List<Ranked> best = new ArrayList<>();
        final Map<String, Double> scores = new HashMap<>();
        final Map<Integer, Ranked> weaponBest = new LinkedHashMap<>();
        final Scenario.Loadout trial;
        final String family;
        final List<OptimizerSpell> spells = new ArrayList<>();
        boolean limited;

        Search(Request request, IntConsumer progress, int budget, long milliseconds) {
            this.request = request;
            this.progress = progress;
            this.budget = budget;
            deadline = System.nanoTime() + milliseconds * 1_000_000;
            trial = request.base.copy();
            trial.manualEquipmentStats = false;
            family = request.combatType;
            if (family.equals("Magic")) {
                PlayerState boosted = Scenario.copy(request.base.player);
                PotionSelection.apply(boosted, request.base);
                for (OptimizerSpell spell : spellCatalog)
                    if (spell.eligible(boosted.getBoostedMagic(), request.target))
                        spells.add(spell);
            }
        }

        Result run() {
            buildPools();
            long combinations = 1;
            for (List<Integer> pool : pools.values())
                combinations = Math.min(1_000_000, combinations * pool.size());
            result.exhaustive =
                    combinations * 4 * Math.max(1, spells.size()) <= Math.min(budget, 12000);
            if (result.exhaustive) enumerate(0, newIds());
            else {
                // Evaluate every weapon's seeds before refinement, so an early branch
                // cannot consume the whole search budget before later weapons are seen.
                List<int[]> seeds = new ArrayList<>();
                // Start each weapon with only locked equipment. A high-ranked armour
                // item can make every heuristic seed invalid (for example an unsupported
                // set effect). Valid minimal seeds let refinement reach usable alternatives.
                for (int weapon : pools.get(3)) {
                    int[] minimal = newIds();
                    minimal[3] = weapon;
                    for (int slot : request.locked)
                        if (pools.containsKey(slot)) minimal[slot] = pools.get(slot).get(0);
                    seeds.add(minimal);
                }
                for (int weapon : pools.get(3)) {
                    int[] start = newIds();
                    start[3] = weapon;
                    for (int slot : SLOTS) if (slot != 3) start[slot] = pools.get(slot).get(0);
                    if (twoHanded(weapon) && !request.locked.contains(5)) start[5] = -1;
                    seeds.add(start);
                    int[] current = start.clone();
                    for (int slot : SLOTS)
                        if (slot != 3
                                && pools.get(slot)
                                        .contains(request.base.player.getEquippedItemIds()[slot]))
                            current[slot] = request.base.player.getEquippedItemIds()[slot];
                    if (twoHanded(weapon) && !request.locked.contains(5)) current[5] = -1;
                    seeds.add(current);
                    for (String set : SETS) {
                        int[] bundle = start.clone();
                        boolean found = false;
                        for (int slot : SLOTS)
                            if (slot != 3 && !request.locked.contains(slot))
                                for (int id : pools.get(slot))
                                    if (id > 0 && facts(id).getName().startsWith(set)) {
                                        bundle[slot] = id;
                                        found = true;
                                        break;
                                    }
                        if (found) {
                            if (twoHanded(weapon) && !request.locked.contains(5)) bundle[5] = -1;
                            seeds.add(bundle);
                        }
                    }
                }
                // Wiki examples supplement the general search; they never restrict its item pool.
                for (int[] wiki : request.base.wikiSeeds) {
                    int[] seed = newIds();
                    for (int slot : SLOTS) {
                        int wanted =
                                request.locked.contains(slot)
                                        ? request.base.player.getEquippedItemIds()[slot]
                                        : wiki[slot];
                        seed[slot] =
                                pools.get(slot).contains(wanted) ? wanted : pools.get(slot).get(0);
                    }
                    if (twoHanded(seed[3]) && !request.locked.contains(5)) seed[5] = -1;
                    seeds.add(seed);
                }
                for (int[] seed : seeds) {
                    if (stop()) break;
                    evaluate(seed);
                }
                // Include ammo with each weapon before selecting refinement starts.
                for (int[] seed : seeds) {
                    if (stop()) break;
                    for (int ammo : pools.get(13)) {
                        seed = seed.clone();
                        seed[13] = ammo;
                        evaluate(seed);
                        if (stop()) break;
                    }
                }
                List<int[]> starts = new ArrayList<>();
                for (Ranked ranked : weaponBest.values()) starts.add(ranked.ids.clone());
                for (Ranked ranked : best) starts.add(ranked.ids.clone());
                for (int[] seed : starts) {
                    if (stop()) break;
                    improve(seed);
                }
            }
            if (Thread.currentThread().isInterrupted()) throw new CancellationException();
            result.exhaustive &= !limited;
            result.evaluated = scores.size();
            if (best.isEmpty())
                throw new IllegalArgumentException(
                        "No usable setup found. Review equipment eligibility, ammunition, Magic"
                                + " level, slot locks and the known formula limitations option.");
            ScenarioCalculator.Result baseline =
                    calculator.score(request.baseline, request.target, request.encounter);
            if (baseline.error == null) {
                result.baselineDps = baseline.normal.getDps();
                result.baselineGroupDps = baseline.groupDps;
            }
            Set<String> identities = new HashSet<>();
            for (Ranked ranked : best) {
                if (Thread.currentThread().isInterrupted()) throw new CancellationException();
                Scenario.Loadout draft = makeDraft(ranked);
                String signature = Arrays.toString(ranked.ids);
                if (!identities.add(signature)) continue;
                ScenarioCalculator.Result full =
                        calculator.calculate(draft, request.target, request.encounter);
                if (full.error != null) continue;
                result.alternatives.add(draft);
                result.calculations.add(full);
                if (result.alternatives.size() == 3) break;
            }
            if (result.alternatives.isEmpty())
                throw new IllegalArgumentException(
                        "Finalist calculation unavailable; review calculation coverage.");
            if (family.equals("Magic"))
                result.exclusions.add(
                        "Magic compares supported autocast spells across spellbooks and powered"
                                + " attacks. Spellbook/quest unlocks and rune supplies require"
                                + " confirmation. Manual casting, Magic Dart and support-spell"
                                + " rotations are not searched.");
            result.exclusions.add(
                    "Equipment eligibility checks skill levels only. Quest, boss-kill and account"
                            + " unlocks must be confirmed separately.");
            result.exclusions.add(
                    request.includeKnownLimitations
                            ? "Known formula limitations were allowed; flagged suggestions need"
                                    + " review."
                            : "Setups with known formula limitations were excluded.");
            return result;
        }

        void buildPools() {
            for (int slot : SLOTS) pools.put(slot, new ArrayList<>());
            for (int id : request.owned.quantities.keySet()) {
                if (Thread.currentThread().isInterrupted()) throw new CancellationException();
                EquipmentCatalogItem item = facts(id);
                if (item == null) continue;
                int slot = slot(item.getSlot());
                if (slot < 0) continue;
                Map<String, Integer> required =
                        VariantRequirements.resolve(
                                id, request.owned.names.get(id), equipment, requirements);
                if (required == null && BLESSINGS_WITHOUT_LEVEL_REQUIREMENTS.contains(id))
                    required = Collections.emptyMap();
                String exclusion = null;
                if (required == null
                        && !request.owned.equipped.containsKey(id)
                        && !request.includeUnverified) exclusion = "requirements unverified";
                if (required != null)
                    for (Map.Entry<String, Integer> level : required.entrySet()) {
                        String skill =
                                level.getKey().equals("runecraft") ? "runecraft" : level.getKey();
                        Integer actual = request.owned.levels.get(skill);
                        if (actual == null || actual < level.getValue())
                            exclusion = "requires " + level.getValue() + " " + skill;
                    }
                String name =
                        (item.getName() + " " + Objects.toString(item.getVersion(), ""))
                                .toLowerCase(Locale.ROOT);
                if (name.contains("blowpipe") && request.base.blowpipeDartId <= 0)
                    exclusion = "set loaded dart ID in Settings";
                if (name.contains("uncharged")
                        || name.contains("(empty)")
                        || name.contains("inactive")) exclusion = "not charged / active";
                if (slot == 3 && item.getSpeed() <= 0) exclusion = "not a supported combat weapon";
                if (slot == 13 && !family.equals("Ranged") && isProjectile(item))
                    exclusion = "ammunition is not used for " + family.toLowerCase(Locale.ROOT);
                if (exclusion != null) {
                    result.exclusions.add(item.getName() + " (#" + id + "): " + exclusion);
                    continue;
                }
                if (slot == 3) {
                    trial.player.getEquippedItemIds()[3] = id;
                    if (styles().isEmpty()) continue;
                }
                pools.get(slot).add(id);
            }
            for (int slot : SLOTS) {
                List<Integer> pool = pools.get(slot);
                pool.sort(
                        Comparator.<Integer>comparingDouble(id -> heuristic(facts(id)))
                                .reversed()
                                .thenComparing(
                                        Comparator.<Integer>comparingInt(
                                                        id -> facts(id).getStats().getPrayerBonus())
                                                .reversed())
                                .thenComparingInt(id -> id));
                if (request.locked.contains(slot)) {
                    int id = request.base.player.getEquippedItemIds()[slot];
                    if (id > 0 && (!request.owned.owns(id) || !pool.contains(id)))
                        throw new IllegalArgumentException(
                                "Locked "
                                        + SLOT_NAMES[index(slot)]
                                        + " is missing or excluded. Review equipment or unlock the"
                                        + " slot.");
                    pool.clear();
                    pool.add(id > 0 ? id : -1);
                } else pool.add(-1);
            }
            if (request.base.blowpipeDartId > 0
                    && !request.owned.owns(request.base.blowpipeDartId)) {
                // Loaded darts are not represented by a separate container entry.
                result.exclusions.add(
                        "Loaded darts use the manually selected ID; confirm the weapon is loaded"
                                + " with these darts.");
            }
        }

        double heuristic(EquipmentCatalogItem item) {
            EquipmentStatTotals s = item.getStats();
            if (family.equals("Magic")) return s.getMagicAttack() + s.getMagicDamage() * 5;
            if (family.equals("Ranged")) return s.getRangedAttack() + s.getRangedStrength() * 3;
            return Math.max(s.getStabAttack(), Math.max(s.getSlashAttack(), s.getCrushAttack()))
                    + s.getMeleeStrength() * 3;
        }

        int[] newIds() {
            int[] ids = new int[14];
            Arrays.fill(ids, -1);
            return ids;
        }

        void enumerate(int at, int[] ids) {
            if (stop()) return;
            if (at == SLOTS.length) {
                evaluate(ids);
                return;
            }
            int slot = SLOTS[at];
            for (int id : pools.get(slot)) {
                ids[slot] = id;
                enumerate(at + 1, ids);
                if (stop()) return;
            }
        }

        void improve(int[] ids) {
            double score = evaluate(ids);
            for (int pass = 0; pass < 3 && !stop(); pass++) {
                boolean changed = false;
                for (int slot : SLOTS) {
                    if (slot == 3 || request.locked.contains(slot)) continue;
                    int winner = ids[slot];
                    for (int id : pools.get(slot)) {
                        ids[slot] = id;
                        double value = evaluate(ids);
                        if (value > score + 1e-12) {
                            score = value;
                            winner = id;
                            changed = true;
                        }
                        if (stop()) break;
                    }
                    ids[slot] = winner;
                    if (stop()) break;
                }
                if (!changed) break;
            }
        }

        double evaluate(int[] ids) {
            if (stop()) return Double.NEGATIVE_INFINITY;
            if (twoHanded(ids[3]) && ids[5] > 0) return Double.NEGATIVE_INFINITY;
            trial.player.setEquippedItemIds(ids.clone());
            trial.player.setEquippedItemNames(new String[14]);
            trial.player.setRawEquipmentLoadout(null);
            double score = Double.NEGATIVE_INFINITY;
            for (CombatStyle style : styles()) {
                List<OptimizerSpell> choices =
                        style.getStance().contains("Autocast")
                                ? spells
                                : Collections.singletonList(null);
                for (OptimizerSpell spell : choices) {
                    if (stop()) break;
                    if (spell != null && !spell.compatible(itemName(ids[3]), ids, this::itemName))
                        continue;
                    String key =
                            Arrays.toString(ids)
                                    + style.getName()
                                    + style.getAttackType()
                                    + "/"
                                    + (spell == null ? "powered" : spell.name);
                    if (scores.containsKey(key)) {
                        score = Math.max(score, scores.get(key));
                        continue;
                    }
                    trial.player.setCombatStyle(style);
                    if (spell == null) OptimizerSpell.clear(trial.player);
                    else spell.apply(trial.player);
                    ScenarioCalculator.Result r =
                            calculator.score(trial, request.target, request.encounter);
                    if (r.error == null
                            && !request.includeKnownLimitations
                            && !r.limitations.isEmpty())
                        r.error =
                                "Known formula limitation excluded; enable Include known formula"
                                        + " limitations to compare these results.";
                    if (r.error == null
                            && ids[13] > 0
                            && isProjectile(facts(ids[13]))
                            && r.ammoApplicability != AmmoApplicability.INCLUDED)
                        r.error = "Ammunition is not used by this weapon";
                    double value =
                            r.error == null && r.normal.getDps() > 0
                                    ? r.rankingDps()
                                    : Double.NEGATIVE_INFINITY;
                    scores.put(key, value);
                    if (Double.isFinite(value)) {
                        score = Math.max(score, value);
                        EquipmentStats stats = r.equipmentStats;
                        int protection =
                                stats.getPrayerBonus() * 5
                                        + stats.getStabDefence()
                                        + stats.getSlashDefence()
                                        + stats.getCrushDefence()
                                        + stats.getMagicDefence()
                                        + stats.getRangedDefence();
                        Ranked ranked =
                                new Ranked(ids.clone(), style, spell, value, protection, key);
                        // Keep spell variants from crowding other gear out of refinement.
                        Ranked existing = null;
                        for (Ranked candidate : best)
                            if (Arrays.equals(candidate.ids, ids)) {
                                existing = candidate;
                                break;
                            }
                        if (existing == null || RANKING.compare(ranked, existing) < 0) {
                            best.remove(existing);
                            best.add(ranked);
                            best.sort(RANKING);
                            if (best.size() > 24) best.remove(best.size() - 1);
                        }
                        Ranked previous = weaponBest.get(ids[3]);
                        if (previous == null || RANKING.compare(ranked, previous) < 0)
                            weaponBest.put(ids[3], ranked);
                    }
                    if (scores.size() % 100 == 0) progress.accept(scores.size());
                }
            }
            return score;
        }

        List<CombatStyle> styles() {
            List<CombatStyle> styles = new ArrayList<>();
            for (CombatStyle style : WeaponStyles.available(trial.player, equipment)) {
                AttackType type = style.getAttackType();
                String typeFamily = type.isMagic() ? "Magic" : type.isRanged() ? "Ranged" : "Melee";
                if (typeFamily.equals(family)
                        && (!style.getStance().contains("Autocast") || !spells.isEmpty()))
                    styles.add(style);
            }
            return styles;
        }

        Scenario.Loadout makeDraft(Ranked ranked) {
            Scenario.Loadout draft = request.base.copy();
            draft.manualEquipmentStats = false;
            draft.name =
                    "Bank " + family.toLowerCase(Locale.ROOT) + " · " + request.target.getName();
            draft.player.setRawEquipmentLoadout(null);
            draft.player.setEquippedItemIds(ranked.ids.clone());
            String[] names = new String[14];
            for (int slot : SLOTS)
                if (ranked.ids[slot] > 0)
                    names[slot] =
                            request.owned.names.getOrDefault(
                                    ranked.ids[slot], facts(ranked.ids[slot]).getName());
            draft.player.setEquippedItemNames(names);
            WeaponStyles.select(draft, ranked.style);
            if (ranked.spell == null) OptimizerSpell.clear(draft.player);
            else ranked.spell.apply(draft.player);
            if (family.equals("Magic"))
                draft.overrides.addAll(
                        Arrays.asList("spellName", "spellbook", "spellElement", "spellMaxHit"));
            for (String path :
                    Scenario.flatten(Scenario.JSON.toJsonTree(draft.player).getAsJsonObject())
                            .keySet())
                if (Scenario.isLive(path)) {
                    draft.overrides.add(path);
                    draft.sources.put(path, "Bank optimizer snapshot");
                }
            draft.description =
                    "Best found using bank scan "
                            + request.owned.bankScannedAt
                            + ". "
                            + request.encounter.summary()
                            + "; "
                            + (request.encounter.grouped ? "estimated group DPS" : "normal DPS")
                            + "; fixed target, prayers and boosts. Confirm charges and unlocks.";
            return draft;
        }

        String itemName(int id) {
            EquipmentCatalogItem item = facts(id);
            return item == null ? "" : item.getName();
        }

        boolean stop() {
            if (Thread.currentThread().isInterrupted()) throw new CancellationException();
            if (scores.size() >= budget || System.nanoTime() >= deadline) limited = true;
            return limited;
        }
    }

    private EquipmentCatalogItem facts(int id) {
        try {
            return equipment.getItemFacts(id);
        } catch (IllegalArgumentException ex) {
            return null;
        }
    }

    private static boolean isProjectile(EquipmentCatalogItem item) {
        if (item == null) return false;
        String name = item.getName().toLowerCase(Locale.ROOT);
        return item.getStats().getRangedStrength() > 0
                || name.contains("arrow")
                || name.contains("bolt") && !name.contains("pouch")
                || name.endsWith(" tar")
                || name.contains("javelin");
    }

    private boolean twoHanded(int id) {
        EquipmentCatalogItem item = facts(id);
        return item != null && item.isTwoHanded();
    }

    private static int slot(String name) {
        for (int i = 0; i < CATALOG_SLOTS.length; i++)
            if (CATALOG_SLOTS[i].equals(name)) return SLOTS[i];
        return -1;
    }

    private static int index(int slot) {
        for (int i = 0; i < SLOTS.length; i++) if (SLOTS[i] == slot) return i;
        return -1;
    }

    private static final Comparator<Ranked> RANKING =
            Comparator.comparingDouble((Ranked rank) -> rank.dps)
                    .reversed()
                    .thenComparing(
                            Comparator.comparingInt((Ranked rank) -> rank.protection).reversed())
                    .thenComparing(rank -> rank.key);

    private static final class Ranked {
        final int[] ids;
        final CombatStyle style;
        final OptimizerSpell spell;
        final double dps;
        final int protection;
        final String key;

        Ranked(
                int[] ids,
                CombatStyle style,
                OptimizerSpell spell,
                double dps,
                int protection,
                String key) {
            this.ids = ids;
            this.style = style;
            this.spell = spell;
            this.dps = dps;
            this.protection = protection;
            this.key = key;
        }
    }
}

