    private boolean binding;

    CalculatorWorkspace(
            Supplier<Scenario> model,
            Runnable changed,
            Consumer<String> message,
            Consumer<MonsterStats> targetChanged,
            DpsLoadoutLabPlugin plugin,
            EquipmentPreparationFacade catalog,
            MonsterDataManager monsters,
            JComponent plot,
            JComboBox<String> graph,
            JTextArea explanation,
            Runnable liveTarget,
            Runnable customTarget,
            Runnable advanced) {
        this.model = model;
        this.changed = changed;
        this.message = message;
        this.targetChanged = targetChanged;
        this.plugin = plugin;
        this.catalog = catalog;
        this.monsters = monsters;
        comparisons =
                new ComparisonTable(
                        index -> {
                            model.get().selected = index;
                            changed.run();
                            tabs.setSelectedIndex(2);
                            loadoutSection.setExpanded(true);
                        });
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(BG);
        JPanel targetCard = column();
        targetCard.setBorder(new EmptyBorder(8, 8, 8, 8));
        targetCard.setBackground(CARD);
        targetTitle.setFont(targetTitle.getFont().deriveFont(Font.BOLD, 14));
        targetCard.add(targetTitle);
        targetCard.add(targetSubtitle);
        targetCard.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        targetCard.addMouseListener(
                new MouseAdapter() {
                    public void mouseClicked(MouseEvent e) {
                        npcSearch.requestFocusInWindow();
                    }
                });

        tabs.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        tabs.setUI(
                new javax.swing.plaf.basic.BasicTabbedPaneUI() {
                    protected int calculateTabWidth(int placement, int index, FontMetrics metrics) {
                        return Math.max(26, (tabs.getWidth() - 12) / 5);
                    }

                    protected int calculateTabHeight(int placement, int index, int height) {
                        return 52;
                    }

                    protected void paintTabBackground(
                            Graphics g,
                            int placement,
                            int index,
                            int x,
                            int y,
                            int w,
                            int h,
                            boolean selected) {
                        g.setColor(selected ? ORANGE : index == getRolloverTab() ? FIELD : HEADER);
                        g.fillRect(x, y, w - 2, h);
                        if (selected) {
                            g.setColor(GOLD);
                            g.fillRect(x, y + h - 3, w - 2, 3);
                        }
                    }

                    protected void layoutLabel(
                            int placement,
                            FontMetrics metrics,
                            int index,
                            String title,
                            Icon icon,
                            Rectangle tab,
                            Rectangle iconBounds,
                            Rectangle textBounds,
                            boolean selected) {
                        iconBounds.setBounds(
                                tab.x + (tab.width - icon.getIconWidth()) / 2,
                                tab.y + 5,
                                icon.getIconWidth(),
                                icon.getIconHeight());
                        textBounds.setBounds(tab.x, tab.y + 35, tab.width, 12);
                    }

                    protected void paintText(
                            Graphics g,
                            int placement,
                            Font font,
                            FontMetrics metrics,
                            int index,
                            String title,
                            Rectangle bounds,
                            boolean selected) {
                        String label = tabs.getTitleAt(index);
                        if (label.equals("Equipment") && bounds.width < 49) label = "Gear";
                        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
                        g.setColor(selected ? TEXT : MUTED);
                        g.drawString(
                                label,
                                bounds.x
                                        + (bounds.width - g.getFontMetrics().stringWidth(label))
                                                / 2,
                                bounds.y + 9);
                    }

                    protected void paintTabBorder(
                            Graphics g,
                            int p,
                            int i,
                            int x,
                            int y,
                            int w,
                            int h,
                            boolean selected) {}

                    protected void paintFocusIndicator(
                            Graphics g,
                            int p,
                            Rectangle[] r,
                            int i,
                            Rectangle icon,
                            Rectangle text,
                            boolean selected) {
                        if (tabs.hasFocus() && selected) {
                            g.setColor(GOLD);
                            g.drawRect(r[i].x + 2, r[i].y + 2, r[i].width - 5, r[i].height - 6);
                        }
                    }

                    protected void paintContentBorder(Graphics g, int placement, int selected) {}
                });
        tabs.getAccessibleContext().setAccessibleName("Loadout editor");
        JPanel[] pages = {combat(), skills(), gear(), prayers(), settings(advanced)};
        String[] names = {"Combat", "Skills", "Equipment", "Prayer", "Settings"};
        String[] icons = {"combat", "skills", "equipment", "prayer", "options"};
        for (int i = 0; i < pages.length; i++) {
            tabs.addTab(names[i], icon("tabs/" + icons[i], 27), pages[i], names[i]);
            // Paint icons directly through the tab UI. Child tooltip labels intercept
            // center clicks instead of letting the native tab handler select the page.
        }
        tabs.setSelectedIndex(2);
        tabs.addChangeListener(
                e -> {
                    // The active editor determines height; invalidate ancestor BoxLayout caches
                    // immediately so a taller prayer book never gets clipped to Gear's height.
                    for (Container parent = tabs; parent != null; parent = parent.getParent())
                        parent.invalidate();
                    editorTitle.setText(tabs.getTitleAt(tabs.getSelectedIndex()));
                    revalidate();
                });
        loadoutBody.add(tabs);
        loadoutSection =
                new WorkspaceSection("Loadout", "Edit comparison drafts", loadoutBody, true);
        JPanel targetSection = column();
        targetSection.add(targetCard);
        targetSection.add(target(liveTarget, customTarget));
        add(new WorkspaceSection("Target", "Shared across comparisons", targetSection, true));
        add(Box.createVerticalStrut(16));
        add(loadoutSection);
        JPanel resultPage = column();
        resultPage.add(encounterResultNote);
        encounterResultNote.setVisible(false);
        confidence.setForeground(GOLD);
        confidence.getAccessibleContext().setAccessibleName("Calculation limitations");
        resultPage.add(confidence);
        confidence.setVisible(false);
        resultPage.add(comparisons);
        resultPage.add(
                action(
                        "Expand comparison",
                        () -> {
                            ComparisonTable wide = new ComparisonTable(null);
                            wide.setColumnWidth(
                                    Math.max(100, 650 / Math.max(1, lastResults.size())));
                            wide.setResults(lastResults, model.get().selected);
                            wide.setPreferredSize(new Dimension(760, 430));
                            JOptionPane.showMessageDialog(
                                    this, wide, "Loadout comparison", JOptionPane.PLAIN_MESSAGE);
                        }));
        JButton details =
                action(
                        "Calculation details ▸",
                        () -> {
                            JScrollPane scroll = new JScrollPane(explanation);
                            scroll.setPreferredSize(new Dimension(540, 480));
                            JOptionPane.showMessageDialog(
                                    this,
                                    scroll,
                                    "Calculation details & coverage",
                                    JOptionPane.PLAIN_MESSAGE);
                        });
        JPanel detailsPage = column();
        detailsPage.add(resultNote);
        detailsPage.add(details);
        resultPage.add(fold("Calculation notes", detailsPage, false));
        add(Box.createVerticalStrut(16));
        add(new WorkspaceSection("Results", "Compare every loadout", resultPage, true));
        JPanel distribution = column();
        distribution.add(fold("Advanced analysis", pair(label("Graph", MUTED), graph), false));
        distribution.add(plot);
        add(Box.createVerticalStrut(16));
        distributionSection =
                new WorkspaceSection(
                        "Hit distribution", "Expand to calculate the chart", distribution, false);
        distributionSection.addPropertyChangeListener(
                "expanded",
                e -> {
                    if (Boolean.TRUE.equals(e.getNewValue())) graphRequest.run();
                });
        add(distributionSection);
        theme(this);
    }

    private JPanel gear() {
        JPanel page = column();
        JPanel grid = new JPanel(new GridLayout(5, 3, 5, 5));
        grid.setBackground(BG);
        String[] layout = {
            "", "head", "", "cape", "neck", "ammo", "weapon", "body", "shield", "", "legs", "",
            "hands", "feet", "ring"
        };
        for (String slot : layout) {
            if (slot.isEmpty()) {
                JPanel blank = new JPanel();
                blank.setOpaque(false);
                grid.add(blank);
                continue;
            }
            JButton b =
                    action(
                            pretty(slot),
                            () -> {
                                slotFilter.setSelectedItem(pretty(slot));
                                itemSearch.requestFocusInWindow();
                            });
            b.setPreferredSize(new Dimension(48, 44));
            b.setHorizontalTextPosition(SwingConstants.CENTER);
            b.setVerticalTextPosition(SwingConstants.BOTTOM);
            b.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            b.addMouseListener(
                    new MouseAdapter() {
                        public void mousePressed(MouseEvent e) {
                            if (SwingUtilities.isRightMouseButton(e)) {
                                equip(slot, -1, null);
                                changed.run();
                            }
                        }
                    });
            slots.put(slot, b);
            grid.add(b);
        }
        grid.setPreferredSize(new Dimension(154, 240));
        JPanel equipmentFigure = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        equipmentFigure.setBackground(BG);
        equipmentFigure.add(grid);
        page.add(equipmentFigure);
        page.add(Box.createVerticalStrut(8));

        itemSearch.setToolTipText("Search equipment by name or item ID");
        itemSearch.getAccessibleContext().setAccessibleName("Search equipment");
        page.add(itemSearch);
        slotFilter.addItem("All slots");
        for (String slot : SLOTS) slotFilter.addItem(pretty(slot));
        itemResults = column();
        itemResults.add(pair(slotFilter, source));
        itemResults.add(itemHint);
        itemList.setCellRenderer(
                new DefaultListCellRenderer() {
                    public Component getListCellRendererComponent(
                            JList<?> list,
                            Object value,
                            int index,
                            boolean selected,
                            boolean focus) {
                        JLabel l =
                                (JLabel)
                                        super.getListCellRendererComponent(
                                                list, value, index, selected, focus);
                        ItemChoice item = (ItemChoice) value;
                        l.setText(
                                "<html>"
                                        + escape(item.facts.getName())
                                        + "<br><font color='#9fa6b1'>"
                                        + escape(
                                                pretty(item.facts.getSlot())
                                                        + " · "
                                                        + Objects.toString(
                                                                item.facts.getVersion(), "")
                                                        + " #"
                                                        + item.id)
                                        + "</font></html>");
                        l.setBorder(new EmptyBorder(6, 5, 6, 5));
                        return l;
