                });
        itemResults.add(scroll(itemList, 155));
        itemResults.add(action("Equip selected item", this::equipSelection));
        page.add(itemResults);
        itemResults.setVisible(false);
        page.add(fold("Equipment bonuses", bonuses(), false));
        page.add(Box.createVerticalStrut(8));
        page.add(optimizerHost);
        page.add(Box.createVerticalStrut(12));
        activate(itemList, this::equipSelection);
        onText(itemSearch, this::filterItems);
        slotFilter.addActionListener(e -> filterItems());
        source.addActionListener(e -> filterItems());
        return page;
