    private JPanel combat() {
        JPanel page = column();
        page.add(label("ATTACK STYLE", MUTED));
        JComboBox<CombatStyle> styles = new JComboBox<>();
        styles.getAccessibleContext().setAccessibleName("Weapon attack style");
        styles.setRenderer(
                new DefaultListCellRenderer() {
                    public Component getListCellRendererComponent(
                            JList<?> list,
                            Object value,
                            int index,
                            boolean selected,
                            boolean focus) {
                        JLabel l =
                                (JLabel)
                                        super.getListCellRendererComponent(
                                                list, value, index, selected, focus);
                        if (value instanceof CombatStyle) {
                            CombatStyle s = (CombatStyle) value;
                            l.setText(s.getName() + " · " + s.getStance());
                            l.setToolTipText(pretty(s.getAttackType().toString()));
                        }
                        return l;
                    }
                });
        styles.addActionListener(
                e -> {
                    if (!binding && styles.getSelectedItem() != null) {
                        WeaponStyles.select(current(), (CombatStyle) styles.getSelectedItem());
                        changed.run();
                    }
                });
        bindings.add(
                () -> {
                    WeaponStyles.normalize(current(), catalog);
                    styles.removeAllItems();
                    for (CombatStyle style : WeaponStyles.available(current().player, catalog))
                        styles.addItem(style);
                    styles.setEnabled(styles.getItemCount() > 0);
                    styles.setToolTipText(
                            styles.getItemCount() == 0
                                    ? "Weapon styles unavailable in the reference catalog"
                                    : "Styles available for this loadout's weapon");
                    styles.setSelectedItem(current().player.getCombatStyle());
                });
        page.add(styles);
        JLabel spellLabel = label("SPELL", MUTED);
        page.add(spellLabel);
        JComboBox<String> spells = new JComboBox<>();
        spells.addItem("Powered weapon / no spell");
        List<JsonObject> spellData = new ArrayList<>();
        try (InputStream stream = getClass().getResourceAsStream("/com/loadoutlab/spells.json");
                Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) {
            for (JsonElement element : new JsonParser().parse(reader).getAsJsonArray()) {
                JsonObject spell = element.getAsJsonObject();
                spellData.add(spell);
                spells.addItem(spell.get("name").getAsString());
            }
        } catch (IOException ex) {
            message.accept("Spell catalog unavailable");
        }
        spells.addActionListener(
                e -> {
                    if (!binding) {
                        int index = spells.getSelectedIndex() - 1;
                        PlayerState p = current().player;
                        if (index < 0) {
                            p.setSpellName(null);
                            p.setSpellElement(null);
                            p.setSpellMaxHit(0);
                        } else {
                            JsonObject spell = spellData.get(index);
                            p.setSpellName(spell.get("name").getAsString());
                            p.setSpellbook(spell.get("spellbook").getAsString());
                            p.setSpellElement(
                                    spell.get("element").isJsonNull()
                                            ? null
                                            : spell.get("element").getAsString());
                            p.setSpellMaxHit(spell.get("max_hit").getAsInt());
                            for (CombatStyle option : WeaponStyles.available(p, catalog))
                                if (option.getStance().equals("Autocast")) {
                                    WeaponStyles.select(current(), option);
                                    break;
                                }
                            for (String path :
                                    Scenario.flatten(Scenario.JSON.toJsonTree(p).getAsJsonObject())
                                            .keySet())
                                if (path.startsWith("combatStyle.")) current().overrides.add(path);
                        }
                        current()
                                .overrides
                                .addAll(
                                        Arrays.asList(
                                                "spellName",
                                                "spellbook",
                                                "spellElement",
                                                "spellMaxHit"));
                        changed.run();
                    }
                });
        bindings.add(
                () -> {
                    spells.setSelectedItem(
                            current().player.getSpellName() == null
                                    ? "Powered weapon / no spell"
                                    : current().player.getSpellName());
                    boolean casting =
                            WeaponStyles.available(current().player, catalog).stream()
                                    .anyMatch(style -> style.getStance().equals("Autocast"));
                    spells.setVisible(casting);
                    spellLabel.setVisible(casting);
                });
        page.add(spells);
        return page;
    }

    private JPanel skills() {
        JPanel page = column();
        JPanel skills = column();
        skills.add(pair(label("Skill", MUTED), label("Base / boost", MUTED)));
        for (String skill :
                new String[] {
                    "attack", "strength", "defence", "ranged", "magic", "prayer", "hitpoints"
                }) {
            String base = skill + "Level", boosted = skill + "Boost";
            Map<String, JsonElement> fields =
                    Scenario.flatten(Scenario.JSON.toJsonTree(current().player).getAsJsonObject());
            JComponent input =
                    fields.containsKey(boosted)
                            ? pair(number(base, false, 1, 126), number(boosted, false, -126, 126))
                            : number(base, false, 1, 126);
            skills.add(
                    pair(
                            statLabel(
                                    pretty(skill),
                                    skill.equals("prayer") ? "tabs/prayer" : "bonuses/" + skill),
                            input));
        }
        page.add(skills);
        page.add(potions());
        return page;
    }

    private JPanel prayers() {
        JPanel page = column();
        JPanel prayers = new JPanel(new GridLayout(0, 4, 5, 5));
        prayers.setBackground(BG);
        for (Prayer prayer : prayerOrder()) {
            JToggleButton toggle = new JToggleButton();
            toggle.setUI(
                    new javax.swing.plaf.basic.BasicToggleButtonUI() {
                        protected void paintButtonPressed(Graphics g, AbstractButton b) {
                            g.setColor(ORANGE);
                            g.fillRect(0, 0, b.getWidth(), b.getHeight());
                        }
                    });
            toggle.getAccessibleContext().setAccessibleName(pretty(prayer.name()));
            toggle.setToolTipText(pretty(prayer.name()));
            toggle.setIcon(com.loadoutlab.UiIcons.icon(prayer.name(), 28));
            if (plugin.getSpriteManager() != null)
                plugin.getSpriteManager()
                        .getSpriteAsync(
                                prayer.getSpriteId(),
                                0,
                                image ->
                                        SwingUtilities.invokeLater(
                                                () -> toggle.setIcon(new ImageIcon(image))));
            toggle.setPreferredSize(new Dimension(42, 42));
            toggle.setMargin(new Insets(4, 4, 4, 4));
            toggle.addActionListener(
                    e -> {
                        if (binding) return;
                        Set<Prayer> active = current().player.getActivePrayers();
                        if (!toggle.isSelected()) active.remove(prayer);
                        else {
                            active.removeIf(p -> conflicts(p, prayer));
                            active.add(prayer);
                        }
                        current().overrides.add("activePrayers");
                        changed.run();
                    });
            bindings.add(
                    () -> {
                        toggle.setSelected(current().player.getActivePrayers().contains(prayer));
                        toggle.setBackground(toggle.isSelected() ? ORANGE : CARD);
                    });
            prayers.add(toggle);
        }
        page.add(prayers);
        page.add(note("Click to toggle prayers. Incompatible prayers are replaced automatically."));
        return page;
    }

    private JPanel potions() {
        JPanel page = column();
        JPanel boosts = column();
        boosts.add(note("Select any combination. The strongest boost per stat applies."));
        for (String potion : PotionSelection.OPTIONS) {
            JCheckBox box = new JCheckBox(potion);
            box.getAccessibleContext().setAccessibleName("Potion: " + potion);
            box.addActionListener(
                    e -> {
                        if (!binding) {
                            PotionSelection.toggle(current(), potion);
                            changed.run();
                        }
                    });
            bindings.add(
                    () -> box.setSelected(PotionSelection.selected(current()).contains(potion)));
            boosts.add(box);
        }
        boosts.add(pair(label("Elapsed seconds", TEXT), number("elapsedSeconds", true, 0, 36000)));
        boosts.add(check("Divine boost", "divine", true));
        page.add(fold("Potions & boosts", boosts, true));
        return page;
    }

