    private static List<Prayer> prayerOrder() {
        List<Prayer> order = new ArrayList<>(Arrays.asList(Prayer.values()));
        order.sort(Comparator.comparingInt(p -> p.getRunelitePrayer().ordinal()));
        return order;
    }

    private JPanel target(Runnable liveTarget, Runnable customTarget) {
        JPanel page = column();
        npcSearch.getAccessibleContext().setAccessibleName("Search monsters");
        npcSearch.setToolTipText("Search monsters by name or NPC ID");
        page.add(npcSearch);
        npcList.setCellRenderer(
                new DefaultListCellRenderer() {
                    public Component getListCellRendererComponent(
                            JList<?> list,
                            Object value,
                            int index,
                            boolean selected,
                            boolean focus) {
                        JLabel l =
                                (JLabel)
                                        super.getListCellRendererComponent(
                                                list, value, index, selected, focus);
                        MonsterStats m = ((MonsterChoice) value).monster;
                        l.setText(
                                "<html>"
                                        + escape(m.getName())
                                        + "<br><font color='#9fa6b1'>"
                                        + escape(
                                                Objects.toString(m.getVersion(), "Standard")
                                                        + " · #"
                                                        + m.getId())
                                        + "</font></html>");
                        l.setBorder(new EmptyBorder(6, 5, 6, 5));
                        return l;
                    }
                });
        monsterResults = column();
        monsterResults.add(scroll(npcList, 160));
        page.add(monsterResults);
        monsterResults.setVisible(false);
        Runnable select =
                () -> {
                    MonsterChoice c = npcList.getSelectedValue();
                    if (c != null) {
                        targetChanged.accept(c.monster);
                        npcSearch.setText("");
                    }
                };
        monsterResults.add(action("Use selected monster", select));
        activate(npcList, select);
        onText(npcSearch, this::filterMonsters);
        page.add(pair(action("Current target", liveTarget), action("Custom…", customTarget)));
        EncounterPanel encounter = new EncounterPanel(model, changed);
        page.add(Box.createVerticalStrut(8));
        page.add(encounter);
        bindings.add(encounter::refresh);
        page.add(Box.createVerticalStrut(8));
        buildTargetStats();
        page.add(fold("Monster stats", targetStats, false));
        return page;
    }

    void refresh() {
        binding = true;
        try {
            for (Runnable bind : bindings) bind.run();
            for (Map.Entry<String, JButton> entry : slots.entrySet()) {
                String slot = entry.getKey();
                JButton b = entry.getValue();
                int id = current().player.getEquippedItemIds()[slotIndex(slot)];
                String name = current().player.getEquippedItemNames()[slotIndex(slot)];
                EquipmentCatalogItem facts = itemFacts(id);
                if (facts != null && (name == null || name.isEmpty())) name = facts.getName();
                b.setIcon(id < 0 ? icon("slots/" + slot, 30) : null);
                b.setText(
                        id < 0
                                ? ""
                                : "<html><center>"
                                        + escape(shortName(Objects.toString(name, "Item " + id)))
                                        + "</center></html>");
                b.setToolTipText(
                        pretty(slot)
                                + ": "
                                + (id < 0
                                        ? "Empty — click to choose"
                                        : name + " — right-click to clear"));
                OwnedEquipment owned = plugin.getOwnedEquipment();
                String ownership =
                        !owned.ready(owned.profile)
                                ? "Unknown — open your bank"
                                : owned.owns(id)
                                        ? "Owned (" + owned.quantities.getOrDefault(id, 0) + ")"
                                        : "Missing";
                if (id > 0) b.setToolTipText(b.getToolTipText() + " · " + ownership);
                b.setBorder(
                        BorderFactory.createLineBorder(
                                id < 0 || !owned.ready(owned.profile)
                                        ? EDGE
                                        : owned.owns(id) ? BEST : new Color(218, 126, 106)));
                if (id >= 0 && plugin.getItemManager() != null) {
                    net.runelite.client.util.AsyncBufferedImage icon =
                            plugin.getItemManager().getImage(id);
                    b.setIcon(new ImageIcon(icon));
                    icon.onLoaded(b::repaint);
                    b.setText("");
                }
            }
            MonsterStats target = model.get().target;
            targetTitle.setText(target == null ? "Choose a monster" : target.getName());
            targetTitle.setToolTipText(targetTitle.getText());
            targetSubtitle.setText(
                    target == null
                            ? "Search in the Target section"
                            : Objects.toString(target.getVersion(), "Standard")
                                    + " · "
                                    + target.getHitpoints()
                                    + " HP");
            theme(targetStats);
        } finally {
            binding = false;
        }
        revalidate();
        repaint();
    }

    private List<ScenarioCalculator.Result> lastResults = Collections.emptyList();

    void showPending() {
        comparisons.setResults(Collections.emptyList(), 0);
        confidence.setText("Calculating updated inputs…");
        confidence.setRows(1);
        confidence.setVisible(true);
    }

    void showResults(List<ScenarioCalculator.Result> results) {
        List<String> limits = new ArrayList<>();
        for (ScenarioCalculator.Result result : results) {
            if (result.error != null) limits.add(result.name + ": " + result.error);
            else if (!result.limitations.isEmpty())
                limits.add(
                        result.name
                                + ": Known formula limitation — "
                                + result.limitations.stream()
                                        .map(
                                                note ->
                                                        note.contains(":")
                                                                ? note.substring(
                                                                        0, note.indexOf(":"))
                                                                : note)
                                        .collect(java.util.stream.Collectors.joining("; ")));
        }
        confidence.setText(String.join("\n", limits));
        confidence.setRows(
                Math.max(1, limits.stream().mapToInt(line -> (line.length() + 28) / 29).sum()));
        confidence.setVisible(!limits.isEmpty());
        lastResults = new ArrayList<>(results);
        comparisons.setResults(results, model.get().selected);
        Encounter encounter = model.get().encounter;
        encounterResultNote.setVisible(encounter.grouped);
        if (encounter.grouped) {
            encounterResultNote.setText(
                    "Group DPS estimate · "
                            + encounter.targets
                            + " identical targets. Other metrics and graphs are per monster."
                            + " Burst/barrage hits the group; other attacks count once.");
            encounterResultNote.setRows(6);
        }
        if (model.get().selected < results.size()) {
            ScenarioCalculator.Result r = results.get(model.get().selected);
            String notice = r.error == null ? String.join("\n\n", r.warnings) : r.error;
            resultNote.setText(notice);
            resultNote.setRows(Math.min(8, Math.max(1, (notice.length() + 29) / 30)));
        }
        if (model.get().selected < results.size()) {
            com.loadoutlab.model.EquipmentStats stats =
                    results.get(model.get().selected).equipmentStats;
            JsonObject values =
                    stats == null
                            ? new JsonObject()
                            : Scenario.JSON.toJsonTree(stats).getAsJsonObject();
            bonusValues.forEach(
                    (key, label) ->
                            label.setText(
                                    !values.has(key)
                                            ? "—"
                                            : key.equals("magicDamage")
                                                    ? String.format(
                                                            Locale.ROOT,
                                                            "%.1f%%",
                                                            values.get(key).getAsInt() / 10.0)
                                                    : values.get(key).getAsString()));
        }
        theme(comparisons);
        revalidate();
        repaint();
    }

    private void filterItems() {
        itemModel.clear();
        String query = itemSearch.getText().trim().toLowerCase(Locale.ROOT);
        itemResults.setVisible(!query.isEmpty());
        resizeEditors();
        if (query.isEmpty()) {
            itemHint.setText("Type a name to find equipment");
            return;
        }
        String slot =
                slotFilter.getSelectedIndex() <= 0
                        ? null
                        : SLOTS[slotFilter.getSelectedIndex() - 1];
        Set<Integer> owned = new HashSet<>();
        int src = source.getSelectedIndex();
        if (src == 1) for (int id : plugin.getInventoryIds()) owned.add(id);
        if (src == 2 && plugin.getCachedPlayerState() != null)
            for (int id : plugin.getCachedPlayerState().getEquippedItemIds()) owned.add(id);
        if (src == 3) for (int id : plugin.getBankIds()) owned.add(id);
        if (src == 4)
            for (Scenario.Loadout loadout : model.get().loadouts)
                for (int id : loadout.player.getEquippedItemIds()) owned.add(id);
        catalog.getItems().entrySet().stream()
                .filter(e -> src == 0 || owned.contains(e.getKey()))
                .filter(e -> slot == null || slot.equals(e.getValue().getSlot()))
                .filter(
                        e ->
                                (e.getValue().getName() + " " + e.getKey())
                                        .toLowerCase(Locale.ROOT)
                                        .contains(query))
                .sorted(Comparator.comparing(e -> e.getValue().getName()))
                .limit(100)
                .forEach(e -> itemModel.addElement(new ItemChoice(e.getKey(), e.getValue())));
        itemHint.setText(
                itemModel.isEmpty()
                        ? "No matches — try another name"
                        : itemModel.size()
                                + (itemModel.size() == 100
                                        ? "+ matches · refine search"
                                        : " matches · double-click to equip"));
        if (!itemModel.isEmpty()) itemList.setSelectedIndex(0);
    }

    private void filterMonsters() {
        npcModel.clear();
        String q = npcSearch.getText().trim().toLowerCase(Locale.ROOT);
        monsterResults.setVisible(!q.isEmpty());
        resizeEditors();
        if (q.isEmpty()) return;
        monsters.getAllMonsters().stream()
                .filter(m -> (m.getName() + " " + m.getId()).toLowerCase(Locale.ROOT).contains(q))
                .sorted(
                        Comparator.comparing(MonsterStats::getName)
                                .thenComparing(m -> Objects.toString(m.getVersion(), "")))
                .limit(100)
                .forEach(m -> npcModel.addElement(new MonsterChoice(m)));
        if (!npcModel.isEmpty()) npcList.setSelectedIndex(0);
    }

