    private void equipSelection() {
        ItemChoice item = itemList.getSelectedValue();
        if (item == null) return;
        if (item.facts.isTwoHanded()) equip("shield", -1, null);
        EquipmentCatalogItem weapon = itemFacts(current().player.getEquippedItemIds()[3]);
        if ("shield".equals(item.facts.getSlot()) && weapon != null && weapon.isTwoHanded())
            equip("weapon", -1, null);
        equip(item.facts.getSlot(), item.id, item.facts.getName());
        changed.run();
        itemSearch.setText("");
        message.accept("Equipped " + item.facts.getName() + " in this loadout");
    }

    private void equip(String slot, int id, String name) {
        int index = slotIndex(slot);
        if (index < 0) return;
        current().player.getEquippedItemIds()[index] = id;
        current().player.getEquippedItemNames()[index] = name;
        current().overrides.add("equippedItemIds." + index);
        current().overrides.add("equippedItemNames." + index);
        current().player.setRawEquipmentLoadout(null);
        current().manualEquipmentStats = false;
    }

    private JSpinner number(String path, boolean condition, int min, int max) {
        JSpinner spin = spinner(min, min, max);
        bindings.add(
                () -> {
                    JsonElement value =
                            Scenario.flatten(
                                            Scenario.JSON
                                                    .toJsonTree(
                                                            condition
                                                                    ? current()
                                                                    : current().player)
                                                    .getAsJsonObject())
                                    .get(path);
                    if (value != null) spin.setValue(value.getAsInt());
                    spin.setToolTipText(
                            current().overrides.contains(path)
                                    ? "Manual override"
                                    : "Loaded / default value");
                });
        spin.addChangeListener(
                e -> {
                    if (!binding)
                        edit(path, new JsonPrimitive((Number) spin.getValue()), condition);
                });
        return spin;
    }

    private JCheckBox check(String text, String path, boolean condition) {
        JCheckBox box = new JCheckBox(text);
        bindings.add(
                () -> {
                    JsonElement value =
                            Scenario.flatten(
                                            Scenario.JSON
                                                    .toJsonTree(
                                                            condition
                                                                    ? current()
                                                                    : current().player)
                                                    .getAsJsonObject())
                                    .get(path);
                    box.setSelected(value != null && value.getAsBoolean());
                });
        box.addActionListener(
                e -> {
                    if (!binding) edit(path, new JsonPrimitive(box.isSelected()), condition);
                });
        return box;
    }

    private void edit(String path, JsonElement value, boolean condition) {
        Scenario.Loadout candidate = current().copy();
        JsonObject obj =
                Scenario.JSON
                        .toJsonTree(condition ? candidate : candidate.player)
                        .getAsJsonObject();
        Scenario.put(obj, path, value);
        if (condition) candidate = Scenario.JSON.fromJson(obj, Scenario.Loadout.class);
        else {
            candidate.player = Scenario.JSON.fromJson(obj, PlayerState.class);
            candidate.overrides.add(path);
        }
        try {
            Scenario.validate(candidate);
            model.get().loadouts.set(model.get().selected, candidate);
            changed.run();
        } catch (RuntimeException ex) {
            message.accept(ex.getMessage());
            refresh();
        }
    }

