    private static boolean conflicts(Prayer a, Prayer b) {
        return a.getAttackBonus() > 0 && b.getAttackBonus() > 0
                || a.getStrengthBonus() > 0 && b.getStrengthBonus() > 0
                || a.getDefenceBonus() > 0 && b.getDefenceBonus() > 0
                || a.getRangedBonus() > 0 && b.getRangedBonus() > 0
                || a.getMagicBonus() > 0 && b.getMagicBonus() > 0;
    }

