    static void theme(Component component) {
        theme(component, BG);
    }

    private static void theme(Component component, Color surface) {
        if (component instanceof JComponent) {
            JComponent c = (JComponent) component;
            c.setAlignmentX(LEFT_ALIGNMENT);
            if (c.getClientProperty("wikiDpsSurface") instanceof Color)
                surface = (Color) c.getClientProperty("wikiDpsSurface");
            if (c instanceof JPanel || c instanceof JTextArea) c.setBackground(surface);
            if (c instanceof javax.swing.text.JTextComponent)
                SidebarScrolling.quietCaret((javax.swing.text.JTextComponent) c);
            if (!(c instanceof JLabel) && !(c instanceof JTextArea)) {
                c.setForeground(TEXT);
                if (!(c instanceof JPanel)) c.setBackground(CARD);
            }
            if (c instanceof AbstractButton) {
                ((AbstractButton) c).setFocusPainted(false);
                c.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
                if (c instanceof JButton || c instanceof JToggleButton && !(c instanceof JCheckBox))
                    c.setBorder(
                            BorderFactory.createCompoundBorder(
                                    BorderFactory.createLineBorder(EDGE),
                                    new EmptyBorder(6, 3, 6, 3)));
            }
            if (c instanceof JTextField) {
                c.setBorder(
                        BorderFactory.createCompoundBorder(
                                BorderFactory.createLineBorder(EDGE), new EmptyBorder(6, 5, 6, 5)));
                ((JTextField) c).setCaretColor(TEXT);
                c.setBackground(FIELD);
            }
            if (c instanceof JList) {
                ((JList<?>) c).setSelectionBackground(ORANGE);
                ((JList<?>) c).setSelectionForeground(TEXT);
            }
            if (c instanceof JTextField || c instanceof JComboBox || c instanceof AbstractButton)
                c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
        }
        if (component instanceof Container)
            for (Component child : ((Container) component).getComponents()) theme(child, surface);
        if (component instanceof JButton
                && Boolean.TRUE.equals(((JButton) component).getClientProperty("wikiDpsSection"))) {
            component.setBackground(HEADER);
            component.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        }
        if (component instanceof JSpinner) {
            JFormattedTextField field =
                    ((JSpinner.DefaultEditor) ((JSpinner) component).getEditor()).getTextField();
            field.setBorder(new EmptyBorder(2, 1, 2, 1));
            field.setHorizontalAlignment(JTextField.CENTER);
        }
    }

