                    {"Size", "size", "1", "10"},
                    {"Speed (ticks)", "speed", "1", "100"},
                    {"Flat armour", "flatArmour", "0", "100000"},
                    {"ToA invocation", "inputs.toaInvocationLevel", "0", "600"},
                    {"ToA path level", "inputs.toaPathLevel", "0", "6"},
