        HintField(String hint) {
            this.hint = hint;
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            if (getText().isEmpty()) {
                g.setColor(MUTED);
                g.setFont(getFont());
                g.drawString(
                        hint,
                        getInsets().left,
                        (getHeight()
                                        + g.getFontMetrics().getAscent()
                                        - g.getFontMetrics().getDescent())
                                / 2);
            }
        }
    }

    private static final class ItemChoice {
        final int id;
        final EquipmentCatalogItem facts;

        ItemChoice(int id, EquipmentCatalogItem facts) {
            this.id = id;
            this.facts = facts;
        }

        public String toString() {
            return facts.getName();
        }
    }

    private static final class MonsterChoice {
        final MonsterStats monster;

        MonsterChoice(MonsterStats monster) {
            this.monster = monster;
        }

        public String toString() {
            return monster.getName();
        }
    }
}

package com.dpscalc.scenario;

import java.util.*;

/**
 * Planned inventory is independent of the legacy observed inventory and never changes combat stats.
 */
public final class CarryPlan {
    public Entry[] slots = new Entry[28];
    public Entry[] runes = new Entry[4];
    public List<Entry> switches = new ArrayList<>();

    public static final class Entry {
        public int id, quantity;
        public boolean noted;
        public String name = "", note = "";

        public Entry() {}

        public Entry(int id, String name, int quantity) {
            this.id = id;
            this.name = name;
            this.quantity = quantity;
        }

        public Entry copy() {
            return Scenario.JSON.fromJson(Scenario.JSON.toJson(this), Entry.class);
        }
    }

    public void validate() {
        if (slots == null
                || slots.length != 28
                || runes == null
                || runes.length != 4
                || switches == null
                || switches.size() > 28)
            throw new IllegalArgumentException(
                    "Use 28 inventory slots, four pouch slots and at most 28 switches");
        List<Entry> all = new ArrayList<>();
        Collections.addAll(all, slots);
        Collections.addAll(all, runes);
        all.addAll(switches);
        for (Entry e : all)
            if (e != null
                    && (e.id < 0
                            || e.quantity < 0
                            || e.name == null
                            || e.name.length() > 200
                            || e.note == null
                            || e.note.length() > 2000))
                throw new IllegalArgumentException("Invalid planned item or quantity");
    }

    public List<String> audit(Scenario.Loadout loadout, OwnedEquipment owned, String profile) {
        validate();
        List<String> notes = new ArrayList<>();
        if (!owned.ready(profile)) {
            notes.add("Ownership unknown: open this character's bank to refresh.");
            return notes;
        }
        Map<Integer, Long> required = new LinkedHashMap<>();
        Map<Integer, String> names = new HashMap<>();
        for (int slot : BankOptimizer.SLOTS) {
            int id = loadout.player.getEquippedItemIds()[slot];
            if (id > 0) {
                required.merge(id, 1L, Long::sum);
                names.put(
                        id,
                        Objects.toString(
                                loadout.player.getEquippedItemNames()[slot], "Item " + id));
            }
        }
        List<Entry> packed = new ArrayList<>();
        Collections.addAll(packed, slots);
        Collections.addAll(packed, runes);
        for (Entry e : packed)
            if (e != null) {
                if (e.id <= 0) {
                    notes.add("Unrecognized: " + e.name);
                    continue;
                }
                if (e.noted)
                    notes.add(e.name + ": noted restock stack; unnote before using it in combat.");
                if (e.quantity == 0)
                    notes.add(
                            e.name + ": set the required quantity; supply sufficiency is unknown.");
                required.merge(e.id, (long) Math.max(1, e.quantity), Long::sum);
                names.put(e.id, e.name);
            }
        required.forEach(
                (id, count) -> {
                    long available = owned.quantities.getOrDefault(id, 0);
                    if (available < count)
                        notes.add(
                                names.get(id)
                                        + ": need "
                                        + count
                                        + ", own "
                                        + available
                                        + " (missing "
                                        + (count - available)
                                        + ")");
                });
        for (Entry e : switches)
            if (e != null && (e.id <= 0 || !owned.owns(e.id)))
                notes.add(
                        "Optional switch "
                                + e.name
                                + ": "
                                + (e.id <= 0 ? "unrecognized" : "not owned"));
        int pouchCapacity = 0;
        for (Entry e : slots)
            if (e != null && e.name != null) {
                String n = e.name.toLowerCase(Locale.ROOT);
                if (n.contains("rune pouch"))
                    pouchCapacity = Math.max(pouchCapacity, n.contains("divine") ? 4 : 3);
            }
        int runeCount = 0;
        Set<Integer> uniqueRunes = new HashSet<>();
        for (Entry e : runes)
            if (e != null) {
                runeCount++;
                if (e.id > 0 && !uniqueRunes.add(e.id))
                    notes.add("Rune pouch contains duplicate " + e.name);
            }
        if (runeCount > pouchCapacity)
            notes.add(
                    pouchCapacity == 0
                            ? "Add a rune pouch to the inventory, or move its runes to inventory"
                                    + " slots."
                            : "This pouch holds only " + pouchCapacity + " rune types.");
        if (notes.isEmpty())
            notes.add(
                    "Listed quantities are owned. Charges, spell costs and trip duration still need"
                            + " checking.");
        return notes;
    }
}

package com.dpscalc.scenario;

import com.loadoutlab.DpsLoadoutLabPlugin;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;

import javax.swing.*;

/** Visual packing plan; edits apply to the selected draft only. */
final class CarryPlanPanel extends JPanel {
    private final Supplier<Scenario> model;
    private final Supplier<String> profile;
    private final Runnable changed;
    private final DpsLoadoutLabPlugin plugin;
    private final JButton[] slots = new JButton[28], runes = new JButton[4];
    private final JPanel switches = CalculatorWorkspace.column();
    private final JTextArea audit = CalculatorWorkspace.note("");
    private final JPanel body = CalculatorWorkspace.column();
    private final JButton toggle;

    CarryPlanPanel(
            Supplier<Scenario> model,
            Supplier<String> profile,
            Runnable changed,
            DpsLoadoutLabPlugin plugin) {
        this.model = model;
        this.profile = profile;
        this.changed = changed;
        this.plugin = plugin;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(CalculatorWorkspace.BG);
        toggle = CalculatorWorkspace.action("Prepare loadout ▸", () -> {});
        body.setVisible(false);
        toggle.addActionListener(
                e -> {
                    body.setVisible(!body.isVisible());
                    toggle.setText(body.isVisible() ? "Prepare loadout ▾" : "Prepare loadout ▸");
                    refresh();
                    resizeContent();
                });
        add(toggle);
        add(body);
        body.add(
                CalculatorWorkspace.note(
                        "Plan supplies for this draft. Click a slot to choose an item and quantity."
                                + " ? means the quantity needs setting."));
        body.add(
                CalculatorWorkspace.action(
                        "Wiki source & notes",
                        () -> {
                            Scenario.Loadout draft = current();
                            JTextArea text =
                                    CalculatorWorkspace.note(
                                            draft.wikiSource.isEmpty()
                                                    ? "This draft has no Wiki template source."
                                                    : draft.wikiSource
                                                            + "\nRevision "
                                                            + draft.wikiRevision
                                                            + "\n\n"
                                                            + String.join("\n\n", draft.wikiNotes));
                            JScrollPane scroll = new JScrollPane(text);
                            scroll.setPreferredSize(new Dimension(420, 350));
                            SidebarScrolling.nested(scroll);
                            JOptionPane.showMessageDialog(
                                    this, scroll, "Template provenance", JOptionPane.PLAIN_MESSAGE);
                        }));
        JPanel inventory = new JPanel(new GridLayout(7, 4, 3, 3));
        inventory.setBackground(CalculatorWorkspace.BG);
        for (int i = 0; i < 28; i++) {
            final int slot = i;
            slots[i] = cell("Inventory " + (i + 1), () -> edit(current().carry.slots, slot, false));
            inventory.add(slots[i]);
        }
        body.add(inventory);
        body.add(CalculatorWorkspace.label("Rune pouch", CalculatorWorkspace.GOLD));
        JPanel pouch = new JPanel(new GridLayout(1, 4, 3, 3));
        for (int i = 0; i < 4; i++) {
            final int slot = i;
            runes[i] = cell("Pouch rune " + (i + 1), () -> edit(current().carry.runes, slot, true));
            pouch.add(runes[i]);
        }
        body.add(pouch);
        body.add(CalculatorWorkspace.label("Optional switches", CalculatorWorkspace.GOLD));
        body.add(
                CalculatorWorkspace.note(
                        "Switches are suggestions until you pack them into an empty inventory"
                                + " slot."));
        body.add(switches);
        body.add(
                CalculatorWorkspace.action(
                        "Add switch",
                        () -> {
                            if (current().carry.switches.size() >= 28) return;
                            CarryPlan.Entry selected = choose(null, false);
                            if (selected != null) {
                                current().carry.switches.add(selected);
                                changed.run();
                            }
                        }));
        body.add(CalculatorWorkspace.action("Check supplies", this::refresh));
        body.add(audit);
        CalculatorWorkspace.theme(this);
    }

    void open() {
        body.setVisible(true);
        toggle.setText("Prepare loadout ▾");
        refresh();
        resizeContent();
    }

    void installBankAction(JButton action) {
        body.add(action);
    }

    private Scenario.Loadout current() {
        Scenario scenario = model.get();
        return scenario.loadouts.get(scenario.selected);
    }

    private JButton cell(String name, Runnable action) {
        JButton b = CalculatorWorkspace.action("+", action);
        b.setPreferredSize(new Dimension(45, 48));
        b.setMargin(new Insets(1, 1, 1, 1));
        b.setFont(b.getFont().deriveFont(9f));
        b.setVerticalTextPosition(SwingConstants.BOTTOM);
        b.setHorizontalTextPosition(SwingConstants.CENTER);
        b.getAccessibleContext().setAccessibleName(name);
        return b;
    }

    private void edit(CarryPlan.Entry[] entries, int slot, boolean rune) {
        CarryPlan.Entry selected = choose(entries[slot], rune);
        if (selected != null) {
            entries[slot] = selected.id == -1 ? null : selected;
            changed.run();
        }
    }

    private CarryPlan.Entry choose(CarryPlan.Entry old, boolean rune) {
        SetupItemIndex index = plugin.getSetupItemIndex();
        if (index == null || !index.isReady()) {
            JOptionPane.showMessageDialog(this, "Item names are still loading. Try again shortly.");
            return null;
        }
        JPanel form = CalculatorWorkspace.column();
        JTextField search = new JTextField(old == null ? "" : old.name);
        JComboBox<Item> results = new JComboBox<>();
        JSpinner quantity =
                new JSpinner(
                        new SpinnerNumberModel(
                                old == null ? 1 : old.quantity, 0, Integer.MAX_VALUE, 1));
        Runnable find =
                () -> {
                    results.removeAllItems();
                    for (int id : index.search(search.getText(), 30)) {
                        String name = index.nameById(id);
                        if (!rune || name.toLowerCase(Locale.ROOT).endsWith(" rune"))
                            results.addItem(new Item(id, name));
                    }
                };
        search.addActionListener(e -> find.run());
        form.add(
                CalculatorWorkspace.label("Item name · Enter to search", CalculatorWorkspace.GOLD));
        form.add(search);
        form.add(CalculatorWorkspace.action("Search items", find));
        form.add(results);
        form.add(CalculatorWorkspace.label("Quantity (0 = unknown)", CalculatorWorkspace.MUTED));
        form.add(quantity);
        find.run();
        if (old != null)
            for (int i = 0; i < results.getItemCount(); i++)
                if (results.getItemAt(i).id == old.id) results.setSelectedIndex(i);
        int answer =
                JOptionPane.showOptionDialog(
                        this,
                        form,
                        rune ? "Plan pouch rune" : "Plan inventory item",
                        JOptionPane.DEFAULT_OPTION,
                        JOptionPane.PLAIN_MESSAGE,
                        null,
                        new String[] {"Save", "Clear slot", "Cancel"},
                        "Save");
        if (answer == 1) return new CarryPlan.Entry(-1, "", 0);
        if (answer != 0 || results.getSelectedItem() == null) return null;
        try {
            quantity.commitEdit();
        } catch (java.text.ParseException e) {
            return null;
        }
        Item item = (Item) results.getSelectedItem();
        int count = ((Number) quantity.getValue()).intValue();
        if (!index.stackable(item.id) && count > 1) {
            JOptionPane.showMessageDialog(
                    this, "This item is not stackable. Put each copy in its own inventory slot.");
            return null;
        }
        return new CarryPlan.Entry(item.id, item.name, count);
    }

    void refresh() {
        Scenario.Loadout draft = current();
        OwnedEquipment owned = plugin.getOwnedEquipment();
        String expected = profile.get();
        for (int i = 0; i < 28; i++) paint(slots[i], draft.carry.slots[i], owned, expected);
        for (int i = 0; i < 4; i++) paint(runes[i], draft.carry.runes[i], owned, expected);
        switches.removeAll();
        for (int i = 0; i < draft.carry.switches.size(); i++) {
            final int pos = i;
            CarryPlan.Entry entry = draft.carry.switches.get(i);
            if (entry == null) continue;
            JButton pack =
                    CalculatorWorkspace.action(
                            "Pack",
                            () -> {
                                for (int slot = 0; slot < 28; slot++)
                                    if (current().carry.slots[slot] == null) {
                                        current().carry.slots[slot] = entry.copy();
                                        changed.run();
                                        return;
                                    }
                                JOptionPane.showMessageDialog(
                                        this, "Inventory is full. Clear a slot first.");
                            });
            pack.setToolTipText("Copy this switch into an empty inventory slot");
            JButton remove =
                    CalculatorWorkspace.action(
                            "×",
                            () -> {
                                current().carry.switches.remove(pos);
                                changed.run();
                            });
            JLabel name = CalculatorWorkspace.label(entry.name, CalculatorWorkspace.TEXT);
            name.setToolTipText(entry.note);
            switches.add(name);
            switches.add(CalculatorWorkspace.pair(pack, remove));
        }
        List<String> notes = new ArrayList<>(draft.carry.audit(draft, owned, expected));
        SetupItemIndex index = plugin.getSetupItemIndex();
        for (CarryPlan.Entry entry : draft.carry.slots)
            if (entry != null) {
                if (!entry.note.isEmpty()) notes.add(entry.name + ": " + entry.note);
                if (index != null
                        && index.isReady()
                        && entry.id > 0
                        && entry.quantity > 1
                        && !entry.noted
                        && !index.stackable(entry.id))
                    notes.add(
                            entry.name
                                    + ": does not stack; use separate slots (or verify a noted"
                                    + " restock stack).");
            }
        CalculatorWorkspace.theme(switches);
        audit.setText(String.join("\n", notes));
        audit.setRows(Math.min(12, Math.max(3, notes.size() * 2)));
        resizeContent();
        repaint();
    }

    private void resizeContent() {
        for (Container parent = this; parent != null; parent = parent.getParent())
            parent.invalidate();
        super.revalidate();
    }

    private void paint(
            JButton button, CarryPlan.Entry entry, OwnedEquipment owned, String expected) {
        button.setIcon(null);
        button.setText(
                entry == null
                        ? "+"
                        : (entry.quantity == 0 ? "?" : Integer.toString(entry.quantity)));
        button.setToolTipText(
                entry == null
                        ? "Empty slot — click to choose"
                        : entry.name
                                + " · "
                                + (entry.id <= 0
                                        ? "unrecognized"
                                        : !owned.ready(expected)
                                                ? "ownership unknown"
                                                : "own "
                                                        + owned.quantities.getOrDefault(
                                                                entry.id, 0))
                                + " · "
                                + entry.note);
        button.setBorder(
                BorderFactory.createLineBorder(
                        entry == null
                                ? CalculatorWorkspace.EDGE
                                : !owned.ready(expected)
                                        ? CalculatorWorkspace.MUTED
                                        : entry.id > 0 && owned.owns(entry.id)
                                                ? CalculatorWorkspace.BEST
                                                : new Color(218, 126, 106)));
        if (entry != null && entry.id > 0 && plugin.getItemManager() != null) {
            net.runelite.client.util.AsyncBufferedImage image =
                    plugin.getItemManager().getImage(entry.id);
            button.setIcon(new ImageIcon(image));
            image.onLoaded(button::repaint);
        } else if (entry != null)
            button.setText(
                    "<html><center>"
                            + CalculatorWorkspace.escape(
                                    entry.name.substring(0, Math.min(8, entry.name.length())))
                            + "<br>"
                            + button.getText()
                            + "</center></html>");
    }

    private static final class Item {
        final int id;
        final String name;

        Item(int id, String name) {
            this.id = id;
            this.name = name;
        }

        public String toString() {
            return name + " (" + id + ")";
        }
    }
}

package com.dpscalc.scenario;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.IntConsumer;

import javax.swing.*;
import javax.swing.table.*;

/** Wiki-style metrics down the left, loadouts across the top. */
public final class ComparisonTable extends JPanel {
    private static final String[] METRICS = {
        "Max hit",
        "DPS",
        "Avg. TTK (s)",
        "Accuracy %",
        "Spec damage",
        "Avg. damage",
        "Interval (t)",
        "Rotation DPS",
        "Taken / s",
        "Taken / kill",
        "Prayer (s)",
        "Kill var (s²)",
        "Status"
    };
    private List<ScenarioCalculator.Result> results = Collections.emptyList();
    private boolean expanded, grouped;
    private int selected;
    private int columnWidth = 62;
    private final AbstractTableModel model =
            new AbstractTableModel() {
                public int getRowCount() {
                    return visibleMetrics().size();
                }

                public int getColumnCount() {
                    return results.size();
                }

                public String getColumnName(int c) {
                    return (results.get(c).limitations.isEmpty() ? "" : "! ")
                            + (c + 1)
                            + " · "
                            + results.get(c).name;
                }

                public Object getValueAt(int r, int c) {
                    return value(metric(r), results.get(c));
                }
            };
    private final JTable table =
            new JTable(model) {
                public String getToolTipText(MouseEvent e) {
                    int row = rowAtPoint(e.getPoint()), col = columnAtPoint(e.getPoint());
                    if (row < 0 || col < 0) return null;
                    ScenarioCalculator.Result result = results.get(col);
                    return result.error != null
                            ? result.error
                            : result.name
                                    + " · "
                                    + metricName(row)
                                    + ": "
                                    + format(metric(row), value(metric(row), result))
                                    + (metric(row) == 13
                                            ? " (hits "
                                                    + result.targetsHit
                                                    + " of "
                                                    + result.encounterTargets
                                                    + " targets)"
                                            : "")
                                    + (best(row, col) ? " (best)" : "");
                }
            };
    private final JList<String> labels = new JList<>();
    private final JScrollPane scroll = new JScrollPane(table);
    private final IntConsumer select;

    public ComparisonTable(IntConsumer select) {
        this.select = select;
        setLayout(new BorderLayout());
        setBackground(CalculatorWorkspace.BG);
        table.getAccessibleContext().setAccessibleName("Loadout comparison");
        table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
        table.setRowHeight(27);
        table.setCellSelectionEnabled(false);
        table.setFocusable(true);
        table.setShowGrid(true);
        table.setGridColor(CalculatorWorkspace.EDGE);
        table.getTableHeader().setReorderingAllowed(false);
        table.setTableHeader(
                new JTableHeader(table.getColumnModel()) {
                    public String getToolTipText(MouseEvent e) {
                        int c = columnAtPoint(e.getPoint());
                        return c < 0
                                ? null
                                : results.get(c).name
                                        + (select == null ? "" : " — click to edit this loadout");
                    }
                });
        table.getTableHeader().setReorderingAllowed(false);
        table.getTableHeader()
                .setDefaultRenderer(
                        new DefaultTableCellRenderer() {
                            public Component getTableCellRendererComponent(
                                    JTable t, Object v, boolean s, boolean f, int row, int col) {
                                super.getTableCellRendererComponent(t, v, s, f, row, col);
                                setHorizontalAlignment(CENTER);
                                setForeground(CalculatorWorkspace.TEXT);
                                setBackground(
                                        col == selected
                                                ? CalculatorWorkspace.ORANGE
                                                : CalculatorWorkspace.BG);
                                setBorder(
                                        BorderFactory.createMatteBorder(
                                                0, 0, 1, 1, CalculatorWorkspace.EDGE));
                                return this;
                            }
                        });
        scroll.setColumnHeaderView(table.getTableHeader());
        MouseAdapter choose =
                new MouseAdapter() {
                    public void mouseClicked(MouseEvent e) {
                        int col = table.columnAtPoint(e.getPoint());
                        if (select != null && col >= 0 && col < results.size()) select.accept(col);
                    }
                };
        table.addMouseListener(choose);
        table.getTableHeader().addMouseListener(choose);
        table.setDefaultRenderer(
                Object.class,
                new DefaultTableCellRenderer() {
                    public Component getTableCellRendererComponent(
                            JTable t, Object value, boolean s, boolean focus, int row, int col) {
                        super.getTableCellRendererComponent(t, value, s, focus, row, col);
                        setText(format(metric(row), value));
                        setHorizontalAlignment(CENTER);
                        boolean winner = best(row, col);
                        setForeground(winner ? CalculatorWorkspace.BEST : CalculatorWorkspace.TEXT);
                        setBackground(
                                winner
                                        ? CalculatorWorkspace.CARD
                                        : col == selected
                                                ? CalculatorWorkspace.CARD
                                                : CalculatorWorkspace.BG);
                        setFont(new Font(Font.SANS_SERIF, winner ? Font.BOLD : Font.PLAIN, 11));
                        return this;
                    }
                });
        labels.setFixedCellHeight(27);
        labels.setFixedCellWidth(83);
        labels.setBackground(CalculatorWorkspace.CARD);
        labels.setForeground(CalculatorWorkspace.TEXT);
        labels.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
        labels.setEnabled(false);
        labels.setCellRenderer(
                new DefaultListCellRenderer() {
                    public Component getListCellRendererComponent(
                            JList<?> list, Object v, int index, boolean s, boolean f) {
                        super.getListCellRendererComponent(list, v, index, false, false);
                        setForeground(CalculatorWorkspace.TEXT);
                        setBackground(CalculatorWorkspace.CARD);
                        return this;
                    }
                });
        scroll.setRowHeaderView(labels);
        scroll.setCorner(
                ScrollPaneConstants.UPPER_LEFT_CORNER,
                CalculatorWorkspace.label("Metric", CalculatorWorkspace.MUTED));
        scroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_NEVER);
        scroll.getViewport().setBackground(CalculatorWorkspace.BG);
        add(scroll, BorderLayout.CENTER);
        JCheckBox more = new JCheckBox("Show more");
        more.setOpaque(false);
        more.setForeground(CalculatorWorkspace.TEXT);
        more.addActionListener(
                e -> {
                    expanded = more.isSelected();
                    refresh();
                });
        add(more, BorderLayout.SOUTH);
        refresh();
        CalculatorWorkspace.theme(this);
        SidebarScrolling.nested(scroll);
    }

    public void setColumnWidth(int width) {
        columnWidth = width;
        refresh();
    }

    public void setResults(List<ScenarioCalculator.Result> results, int selected) {
        this.results = new ArrayList<>(results);
        this.selected = selected;
        grouped = results.stream().anyMatch(r -> r.groupDps != null);
        refresh();
    }

    private void refresh() {
        int position = scroll.getHorizontalScrollBar().getValue();
        model.fireTableStructureChanged();
        for (int i = 0; i < table.getColumnCount(); i++) {
            table.getColumnModel().getColumn(i).setPreferredWidth(columnWidth);
            table.getColumnModel().getColumn(i).setMinWidth(60);
        }
        String[] names = new String[model.getRowCount()];
        for (int row = 0; row < names.length; row++) names[row] = metricName(row);
        labels.setListData(names);
        scroll.setPreferredSize(new Dimension(210, model.getRowCount() * 27 + 47));
        scroll.getHorizontalScrollBar().setValue(position);
        revalidate();
        repaint();
    }

    private List<Integer> visibleMetrics() {
        List<Integer> metrics = new ArrayList<>(Arrays.asList(1, 0, 3, 2));
        if (grouped) metrics.add(1, 13);
        if (results.stream().anyMatch(r -> r.special != null)) metrics.add(4);
        if (expanded)
            for (int i = 4; i < METRICS.length; i++) if (!metrics.contains(i)) metrics.add(i);
        return metrics;
    }

    private int metric(int row) {
        return visibleMetrics().get(row);
    }

    private String metricName(int row) {
        int metric = metric(row);
        return metric == 13
                ? "Group DPS (est.)"
                : grouped && metric == 1
                        ? "DPS / monster"
                        : grouped && metric == 2 ? "TTK / monster" : METRICS[metric];
    }

    public boolean best(int row, int column) {
        row = metric(row);
        if (row != 13 && (row > 9 || row == 6 || row == 8 || row == 9)) return false;
        Object raw = value(row, results.get(column));
        if (!(raw instanceof Number)) return false;
        double candidate = ((Number) raw).doubleValue();
        if (!Double.isFinite(candidate)) return false;
        boolean lower = row == 2;
        for (ScenarioCalculator.Result result : results) {
            Object other = value(row, result);
            if (other instanceof Number) {
                double n = ((Number) other).doubleValue();
                if (Double.isFinite(n) && (lower ? n < candidate : n > candidate)) return false;
            }
        }
        return true;
    }

    private static Object value(int row, ScenarioCalculator.Result r) {
        if (row == 12)
            return r.error != null
                    ? "Unavailable"
                    : !r.limitations.isEmpty()
                            ? "Known formula limitation"
                            : r.groupDps != null ? "Group estimate" : "Model result";
        if (r.error != null || r.normal == null) return null;
        switch (row) {
            case 13:
                return r.groupDps;
            case 0:
                return r.normal.getMaxHit();
            case 1:
                return r.normal.getDps();
            case 2:
                return r.ttk;
            case 3:
                return r.normal.getAccuracy() * 100;
            case 4:
                return r.special == null ? null : r.special.getExpectedDamage();
            case 5:
                return r.normal.getExpectedDamage();
            case 6:
                return r.normal.getExpectedAttackSpeed();
            case 7:
                return r.rotationDps;
            case 8:
                return r.damageTaken;
            case 9:
                return r.damageTaken == null || r.ttk == null ? null : r.damageTaken * r.ttk;
            case 10:
                return r.prayerSeconds;
            case 11:
                return r.ttkVariance;
            default:
                return null;
        }
    }

    private static String format(int row, Object value) {
        if (value == null) return "—";
        if (!(value instanceof Number)) return value.toString();
        double n = ((Number) value).doubleValue();
        if (!Double.isFinite(n)) return "—";
        return String.format(
                Locale.ROOT,
                row == 0 ? "%.0f" : row == 1 || row == 7 || row == 13 ? "%.3f" : "%.1f",
                n);
    }
}

