package com.dpscalc.scenario;

import com.loadoutlab.engine.DamagePmf;
import com.loadoutlab.engine.StationaryKill;

/** Adapter from the standalone probability API to the existing graphs. */
public final class DistributionAnalysis {
    private DistributionAnalysis() {}

    public static double[] histogram(DamagePmf attack) {
        return attack.probabilities();
    }

    public static double[] moments(double[] probabilities, int hp) {
        StationaryKill.Moments m = StationaryKill.moments(new DamagePmf(probabilities), hp);
        if (!Double.isFinite(m.expectedAttacks()))
            throw new IllegalArgumentException("Target cannot be killed by this distribution");
        return new double[] {m.expectedAttacks(), m.attackVariance()};
    }

    public static double[] killDistribution(double[] probabilities, int hp, int attacks) {
        return StationaryKill.horizon(new DamagePmf(probabilities), hp, attacks);
    }
}

package com.dpscalc.scenario;

import com.loadoutlab.model.PlayerState;

import java.util.Set;

/** Shared comparison assumptions, separate from an individual monster's combat stats. */
public final class Encounter {
    private static final Set<String> AREA_SPELLS =
            Set.of(
                    "Smoke Burst",
                    "Shadow Burst",
                    "Blood Burst",
                    "Ice Burst",
                    "Smoke Barrage",
                    "Shadow Barrage",
                    "Blood Barrage",
                    "Ice Barrage");
    public boolean grouped;
    public int targets = 5;

    public void validate() {
        if (targets < 2 || targets > 9)
            throw new IllegalArgumentException("Grouped encounters require 2–9 targets");
    }

    public Encounter copy() {
        Encounter copy = new Encounter();
        copy.grouped = grouped;
        copy.targets = targets;
        return copy;
    }

    public int targetsHit(PlayerState player) {
        return grouped
                        && player.getCombatStyle().getAttackType().isMagic()
                        && "ancient".equals(player.getSpellbook())
                        && AREA_SPELLS.contains(
                                player.getSpellName() == null ? "" : player.getSpellName())
                ? targets
                : 1;
    }

    public String summary() {
        return grouped ? "Grouped · " + targets + " targets" : "Single target";
    }

    public String assumption() {
        return "Estimated group DPS assumes "
                + targets
                + " identical monsters kept in burst/barrage range. Gathering and looting time are"
                + " excluded. Other attacks count once; kill time and hit distribution remain per"
                + " monster.";
    }
}

package com.dpscalc.scenario;

import java.util.function.Supplier;

import javax.swing.*;

/** Encounter intent belongs with the target and applies to every comparison loadout. */
public final class EncounterPanel extends JPanel {
    private final Supplier<Scenario> model;
    private final Runnable changed;
    private final JComboBox<String> mode =
            new JComboBox<>(new String[] {"Single target", "Grouped targets"});
    private final JSpinner count = new JSpinner(new SpinnerNumberModel(5, 2, 9, 1));
    private final JPanel group = CalculatorWorkspace.column();
    private final JButton suggest;
    private boolean binding;

    public EncounterPanel(Supplier<Scenario> model, Runnable changed) {
        this.model = model;
        this.changed = changed;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(CalculatorWorkspace.BG);
        add(CalculatorWorkspace.label("Encounter", CalculatorWorkspace.GOLD));
        add(mode);
        mode.getAccessibleContext().setAccessibleName("Encounter mode");
        count.getAccessibleContext().setAccessibleName("Grouped target count");
        count.setToolTipText("Number of monsters kept together within burst/barrage range");
        group.add(
                CalculatorWorkspace.pair(
                        CalculatorWorkspace.label("Targets", CalculatorWorkspace.TEXT), count));
        JTextArea note =
                CalculatorWorkspace.note(
                        "Assumes identical monsters grouped in burst/barrage range in multicombat."
                                + " Group DPS excludes gathering and looting time.");
        note.setRows(5);
        group.add(note);
        add(group);
        suggest =
                CalculatorWorkspace.action(
                        "Use grouped encounter",
                        () -> edit(() -> model.get().encounter.grouped = true));
        suggest.setToolTipText(
                "Bursting these monsters together in multicombat? Use a grouped encounter and set"
                        + " the target count.");
        add(suggest);
        mode.addActionListener(
                e -> edit(() -> model.get().encounter.grouped = mode.getSelectedIndex() == 1));
        count.addChangeListener(
                e -> edit(() -> model.get().encounter.targets = (Integer) count.getValue()));
        CalculatorWorkspace.theme(this);
        refresh();
    }

    private void edit(Runnable edit) {
        if (binding) return;
        edit.run();
        model.get().encounter.validate();
        refresh();
        changed.run();
    }

    public void refresh() {
        binding = true;
        try {
            Encounter encounter = model.get().encounter;
            mode.setSelectedIndex(encounter.grouped ? 1 : 0);
            count.setValue(encounter.targets);
            group.setVisible(encounter.grouped);
            String name = model.get().target == null ? "" : model.get().target.getName();
            suggest.setVisible(
                    !encounter.grouped
                            && (name.equalsIgnoreCase("Nechryael")
                                    || name.equalsIgnoreCase("Greater Nechryael")));
        } finally {
            binding = false;
        }
        for (java.awt.Container parent = this; parent != null; parent = parent.getParent())
            parent.invalidate();
        revalidate();
        repaint();
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;

import javax.swing.*;
import javax.swing.table.AbstractTableModel;

/** Explicit JSON property paths allow a common editor without Java reflection. */
public final class FieldEditor extends JPanel {
    private final JLabel validation = new JLabel();
    private final Model model = new Model();
    private JsonObject object;
    private List<String> paths = new ArrayList<>();
    private Function<String, String> source;
    private BiConsumer<String, JsonObject> change;
    private Consumer<String> error;
    private Consumer<String> reset;
    private final JTable table =
            new JTable(model) {
                @Override
                public String getToolTipText(java.awt.event.MouseEvent event) {
                    int row = rowAtPoint(event.getPoint());
                    return row < 0 ? null : paths.get(row) + " · " + source.apply(paths.get(row));
                }
            };

    public FieldEditor() {
        super(new BorderLayout());
        table.setRowHeight(24);
        table.setAutoResizeMode(JTable.AUTO_RESIZE_ALL_COLUMNS);
        table.getColumnModel().getColumn(0).setPreferredWidth(94);
        table.getColumnModel().getColumn(1).setPreferredWidth(58);
        table.getColumnModel().getColumn(2).setPreferredWidth(58);
        JScrollPane scroll = new JScrollPane(table);
        scroll.setPreferredSize(new Dimension(220, 320));
        add(scroll);
        JButton restore = new JButton("Clear selected override");
        restore.addActionListener(
                e -> {
                    int row = table.getSelectedRow();
                    if (row >= 0 && reset != null) reset.accept(paths.get(row));
                });
        JPanel footer = new JPanel(new BorderLayout());
        footer.add(validation, BorderLayout.NORTH);
        footer.add(restore, BorderLayout.SOUTH);
        add(footer, BorderLayout.SOUTH);
    }

    public void bind(
            JsonObject data,
            Function<String, String> provenance,
            BiConsumer<String, JsonObject> edited,
            Consumer<String> failed,
            Consumer<String> cleared) {
        if (table.isEditing()) return;
        object = data;
        paths = new ArrayList<>(Scenario.flatten(data).keySet());
        paths.removeIf(
                p ->
                        p.startsWith("rawEquipmentLoadout")
                                || p.startsWith("equippedItemVersions")
                                || p.startsWith("equippedItemCategories")
                                || p.equals("ammoApplicability"));
        source = provenance;
        change = edited;
        error = failed;
        reset = cleared;
        model.fireTableDataChanged();
    }

    private final class Model extends AbstractTableModel {
        public int getRowCount() {
            return paths.size();
        }

        public int getColumnCount() {
            return 3;
        }

        public String getColumnName(int c) {
            return new String[] {"Field", "Value", "Source"}[c];
        }

        public Object getValueAt(int r, int c) {
            String path = paths.get(r);
            String shortName =
                    path.substring(path.lastIndexOf('.') + 1).replaceAll("([a-z])([A-Z])", "$1 $2");
            return c == 0
                    ? shortName
                    : c == 2 ? source.apply(path) : Scenario.flatten(object).get(path).toString();
        }

        public boolean isCellEditable(int r, int c) {
            return c == 1;
        }

        public void setValueAt(Object value, int row, int column) {
            String path = paths.get(row);
            try {
                JsonElement old = Scenario.flatten(object).get(path);
                String input = value.toString().trim();
                JsonElement parsed;
                if (old.isJsonNull()
                        || old.isJsonPrimitive() && old.getAsJsonPrimitive().isString())
                    parsed =
                            input.equals("null")
                                    ? JsonNull.INSTANCE
                                    : new JsonPrimitive(
                                            input.startsWith("\"")
                                                    ? new JsonParser().parse(input).getAsString()
                                                    : input);
                else parsed = new JsonParser().parse(input);
                if (old.isJsonPrimitive() && old.getAsJsonPrimitive().isNumber()) {
                    double n = parsed.getAsDouble();
                    if (!Double.isFinite(n) || Math.abs(n) > 1_000_000)
                        throw new IllegalArgumentException("Number out of range");
                }
                JsonObject candidate = new JsonParser().parse(object.toString()).getAsJsonObject();
                Scenario.put(candidate, path, parsed);
                change.accept(path, candidate);
                validation.setText("");
            } catch (RuntimeException ex) {
                String message = "Cannot edit " + path + ": " + ex.getMessage();
                validation.setText(message);
                validation.setToolTipText(message);
                error.accept(message);
            }
        }
    }
}

