            String description = BankOptimizer.SLOT_NAMES[i] + ": " + name;
            label.setToolTipText(description);
            label.getAccessibleContext().setAccessibleName("Suggested " + description);
            label.putClientProperty("itemId", id);
            label.setText("");
            label.setIcon(CalculatorWorkspace.icon("slots/" + ICONS[i], 30));
            if (id > 0) {
                String ownership =
                        !owned.ready(profile) ? "Unknown" : owned.owns(id) ? "Owned" : "Missing";
                label.setText(ownership);
                label.setBorder(
                        BorderFactory.createLineBorder(
                                !owned.ready(profile)
                                        ? CalculatorWorkspace.EDGE
                                        : owned.owns(id)
                                                ? CalculatorWorkspace.BEST
                                                : new Color(218, 126, 106)));
                label.setToolTipText(
                        description
                                + " — "
                                + ownership.toLowerCase(Locale.ROOT)
                                + (owned.ready(profile)
                                        ? " (" + owned.quantities.getOrDefault(id, 0) + ")"
                                        : "; open this character's bank"));
                ItemManager manager = items.get();
                if (manager != null) {
                    AsyncBufferedImage sprite = manager.getImage(id);
                    label.setIcon(new ImageIcon(sprite));
                    sprite.onLoaded(label::repaint);
                } else {
                    label.setIcon(CalculatorWorkspace.icon("slots/" + ICONS[i], 16));
                    label.setText(
                            "<html><center>"
                                    + CalculatorWorkspace.escape(
                                            name.substring(0, Math.min(8, name.length())))
                                    + "<br>"
                                    + ownership
                                    + "</center></html>");
                }
            }
        }
        repaint();
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }
}

package com.dpscalc.scenario;

import java.awt.*;
import java.util.List;
import java.util.function.IntConsumer;

import javax.swing.*;
import javax.swing.plaf.basic.BasicTabbedPaneUI;

/** Compact numbered tabs, with native keyboard navigation and overflow scrolling. */
final class LoadoutTabs extends JTabbedPane {
    private final IntConsumer remove;

    LoadoutTabs(IntConsumer remove) {
        super(TOP, SCROLL_TAB_LAYOUT);
        this.remove = remove;
        getAccessibleContext().setAccessibleName("Comparison loadouts");
        setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        setBackground(CalculatorWorkspace.BG);
        setForeground(CalculatorWorkspace.TEXT);
        setUI(
                new BasicTabbedPaneUI() {
                    protected int calculateTabWidth(int placement, int index, FontMetrics metrics) {
                        return 60;
                    }

                    protected int calculateTabHeight(int placement, int index, int height) {
                        return 30;
                    }

                    protected void paintTabBackground(
                            Graphics g,
                            int placement,
                            int index,
                            int x,
                            int y,
                            int w,
                            int h,
                            boolean selected) {
                        g.setColor(
                                selected ? CalculatorWorkspace.ORANGE : CalculatorWorkspace.CARD);
                        g.fillRect(x, y, w, h);
                        if (selected) {
                            g.setColor(CalculatorWorkspace.ORANGE);
                            g.fillRect(x, y + h - 3, w, 3);
                        }
                    }

                    protected void paintTabBorder(
                            Graphics g,
                            int p,
                            int i,
                            int x,
                            int y,
                            int w,
                            int h,
                            boolean selected) {}

                    protected void paintContentBorder(Graphics g, int placement, int selected) {}

                    protected void paintFocusIndicator(
                            Graphics g,
                            int p,
                            Rectangle[] r,
                            int i,
                            Rectangle icon,
                            Rectangle text,
                            boolean selected) {
                        if (hasFocus() && selected) {
                            g.setColor(CalculatorWorkspace.GOLD);
                            g.drawRect(r[i].x + 2, r[i].y + 2, r[i].width - 5, r[i].height - 6);
                        }
                    }
                });
    }

    void bind(List<Scenario.Loadout> loadouts, int selected) {
        // Retain tab components on ordinary edits so focus and scrolling remain stable.
        while (getTabCount() > loadouts.size()) removeTabAt(getTabCount() - 1);
        while (getTabCount() < loadouts.size()) {
            int index = getTabCount();
            addTab(String.valueOf(index + 1), new JPanel());
            JPanel header = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
            header.setOpaque(false);
            JButton select = tabButton("", 28), close = tabButton("×", 24);
            select.addActionListener(
                    e -> {
                        int tab = indexOfTabComponent(header);
                        if (tab >= 0) setSelectedIndex(tab);
                    });
            close.addActionListener(
                    e -> {
                        int tab = indexOfTabComponent(header);
                        if (tab >= 0 && getTabCount() > 1) remove.accept(tab);
                    });
            header.add(select);
            header.add(close);
            setTabComponentAt(index, header);
        }
        for (int i = 0; i < loadouts.size(); i++) {
            String name = loadouts.get(i).name;
            JPanel header = (JPanel) getTabComponentAt(i);
            JButton select = (JButton) header.getComponent(0),
                    close = (JButton) header.getComponent(1);
            select.setText(String.valueOf(i + 1));
            select.setToolTipText(name);
            select.getAccessibleContext()
                    .setAccessibleName("Select comparison loadout " + (i + 1) + ": " + name);
            close.setEnabled(loadouts.size() > 1);
            close.setToolTipText(
                    loadouts.size() > 1
                            ? "Remove " + name + " from comparison"
                            : "Keep at least one comparison loadout");
            close.getAccessibleContext()
                    .setAccessibleName("Remove comparison loadout " + (i + 1) + ": " + name);
            setToolTipTextAt(i, name);
            getComponentAt(i).getAccessibleContext().setAccessibleName(loadouts.get(i).name);
        }
        setSelectedIndex(selected);
    }

    private static JButton tabButton(String text, int width) {
        JButton button = new JButton(text);
        button.setPreferredSize(new Dimension(width, 26));
        button.setMargin(new Insets(0, 0, 0, 0));
        button.setBorder(BorderFactory.createEmptyBorder());
        button.setContentAreaFilled(false);
        button.setOpaque(false);
        button.setFocusable(false);
        button.setForeground(CalculatorWorkspace.TEXT);
        button.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
        return button;
    }

    @Override
    public Dimension getPreferredSize() {
        return new Dimension(170, 36);
    }

    @Override
    public Dimension getMinimumSize() {
        return new Dimension(50, 36);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, 36);
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;
import com.loadoutlab.data.*;
import com.loadoutlab.model.*;
import com.loadoutlab.model.PlayerState;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.IntFunction;

/** Supported autocast spells, with factual casting requirements attributed in NOTICE.md. */
final class OptimizerSpell {
    final String name, book, element;
    final int maxHit, level;

    private OptimizerSpell(JsonObject data, int level) {
        name = data.get("name").getAsString();
        book = data.get("spellbook").getAsString();
        element = data.get("element").isJsonNull() ? null : data.get("element").getAsString();
        maxHit = data.get("max_hit").getAsInt();
        this.level = level;
    }

    static List<OptimizerSpell> load() {
        List<OptimizerSpell> spells = new ArrayList<>();
        try (Reader spellsReader = reader("spells.json")) {
            for (JsonElement entry : new JsonParser().parse(spellsReader).getAsJsonArray()) {
                JsonObject data = entry.getAsJsonObject();
                String name = data.get("name").getAsString();
                if (data.get("max_hit").getAsInt() > 0)
                    spells.add(new OptimizerSpell(data, data.get("level").getAsInt()));
            }
        } catch (IOException ex) {
            throw new IllegalStateException("Optimizer spell catalog unavailable", ex);
        }
        // Start with high damage spells when a large search reaches its time/score cap.
        spells.sort(
                Comparator.comparingInt((OptimizerSpell spell) -> spell.maxHit)
                        .reversed()
                        .thenComparing(spell -> spell.name));
        return Collections.unmodifiableList(spells);
    }

    private static Reader reader(String file) {
        return new InputStreamReader(
                OptimizerSpell.class.getResourceAsStream("/com/loadoutlab/" + file),
                StandardCharsets.UTF_8);
    }

    boolean eligible(int magic, MonsterStats target) {
        if (level > magic) return false;
        if (name.endsWith("Demonbane"))
            return target.getAttributes().contains(MonsterAttribute.DEMON);
        return !name.equals("Crumble Undead")
                || target.getAttributes().contains(MonsterAttribute.UNDEAD);
    }

    boolean compatible(String weapon, int[] ids, IntFunction<String> names) {
        weapon = weapon.toLowerCase(Locale.ROOT);
        IntFunction<String> originalNames = names;
        names = id -> Objects.toString(originalNames.apply(id), "").toLowerCase(Locale.ROOT);
        if (book.equals("ancient"))
            return weapon.equals("ancient staff")
                    || weapon.contains("ancient sceptre")
                    || weapon.equals("ancient sceptre")
                    || weapon.equals("master wand")
                    || weapon.equals("kodai wand")
                    || weapon.equals("dragon hunter wand")
                    || weapon.equals("blue moon spear")
                    || weapon.contains("nightmare staff") && !weapon.startsWith("harmonised")
                    || weapon.equals("nightmare staff")
                    || alternateSceptre(weapon)
                    || weapon.startsWith("ahrim's staff")
                            && names.apply(ids[0]).startsWith("ahrim's hood")
                            && names.apply(ids[4]).startsWith("ahrim's robetop")
                            && names.apply(ids[7]).startsWith("ahrim's robeskirt")
                            && names.apply(ids[2]).startsWith("amulet of the damned");
        if (book.equals("arceuus"))
            return weapon.startsWith("skull sceptre")
                    || weapon.startsWith("slayer's staff")
                    || weapon.startsWith("ahrim's staff")
                    || weapon.equals("blue moon spear")
                    || weapon.equals("staff of the dead")
                    || weapon.equals("toxic staff of the dead")
                    || weapon.equals("purging staff")
                    || weapon.equals("master wand")
                    || weapon.equals("kodai wand");
        switch (name.toLowerCase(Locale.ROOT)) {
            case "magic dart":
                return weapon.startsWith("slayer's staff")
                        || weapon.equals("staff of the dead")
                        || weapon.equals("toxic staff of the dead")
                        || weapon.equals("staff of light")
                        || weapon.equals("staff of balance");
            case "iban blast":
                return weapon.startsWith("iban's staff");
            case "claws of guthix":
                return weapon.equals("staff of balance") || weapon.equals("void knight mace");
            case "saradomin strike":
                return weapon.equals("staff of light");
            case "flames of zamorak":
                return weapon.equals("staff of the dead")
                        || weapon.equals("toxic staff of the dead")
                        || alternateSceptre(weapon);
            case "crumble undead":
                return weapon.equals("skull sceptre (i)")
                        || weapon.startsWith("slayer's staff")
                        || weapon.equals("void knight mace")
                        || weapon.equals("staff of the dead")
                        || weapon.equals("toxic staff of the dead")
                        || weapon.equals("staff of light")
                        || weapon.equals("staff of balance");
            default:
                if (element == null || weapon.startsWith("skull sceptre")) return false;
                return !(weapon.startsWith("slayer's staff") || weapon.equals("void knight mace"))
                        || name.toLowerCase(Locale.ROOT).endsWith(" wave")
                        || name.toLowerCase(Locale.ROOT).endsWith(" surge");
        }
    }

    private static boolean alternateSceptre(String weapon) {
        return (weapon.startsWith("thammaron's sceptre") || weapon.startsWith("accursed sceptre"))
                && weapon.endsWith("(a)");
    }

    void apply(PlayerState player) {
        player.setSpellName(name);
        player.setSpellbook(book);
        player.setSpellElement(element);
        player.setSpellMaxHit(maxHit);
    }

    static void clear(PlayerState player) {
        player.setSpellName(null);
        player.setSpellbook(null);
        player.setSpellElement(null);
        player.setSpellMaxHit(0);
    }
}

package com.dpscalc.scenario;

import java.util.*;

/** One immutable view of the player's observed containers. No client objects cross threads. */
public final class OwnedEquipment {
    public final String profile;
    public final long revision, bankScannedAt;
    public final Map<Integer, Integer> bank, inventory, equipped, quantities;
    public final Map<String, Integer> levels;
    public final Map<Integer, String> names;

    public OwnedEquipment(
            String profile,
            long revision,
            long scanned,
            Map<Integer, Integer> bank,
            Map<Integer, Integer> inventory,
            Map<Integer, Integer> equipped,
            Map<String, Integer> levels) {
        this(profile, revision, scanned, bank, inventory, equipped, levels, Map.of());
    }

    public OwnedEquipment(
            String profile,
            long revision,
            long scanned,
            Map<Integer, Integer> bank,
            Map<Integer, Integer> inventory,
            Map<Integer, Integer> equipped,
            Map<String, Integer> levels,
            Map<Integer, String> names) {
        this.profile = profile;
        this.revision = revision;
        this.bankScannedAt = scanned;
        this.bank = immutable(bank);
        this.inventory = immutable(inventory);
        this.equipped = immutable(equipped);
        this.levels = Collections.unmodifiableMap(new TreeMap<>(levels));
        this.names = Collections.unmodifiableMap(new TreeMap<>(names));
        Map<Integer, Integer> total = new TreeMap<>();
        for (Map<Integer, Integer> source : Arrays.asList(bank, inventory, equipped))
            source.forEach(
                    (id, quantity) -> {
                        if (id > 0 && quantity > 0)
                            total.merge(
                                    id,
                                    quantity,
                                    (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
                    });
        quantities = immutable(total);
    }

    private static Map<Integer, Integer> immutable(Map<Integer, Integer> source) {
        return Collections.unmodifiableMap(new TreeMap<>(source));
    }

    public static OwnedEquipment empty(long revision) {
        return new OwnedEquipment(null, revision, 0, Map.of(), Map.of(), Map.of(), Map.of());
    }

    public boolean ready(String expectedProfile) {
        return bankScannedAt > 0 && profile != null && profile.equals(expectedProfile);
    }

    public boolean owns(int id) {
        return id <= 0 || quantities.getOrDefault(id, 0) > 0;
    }
}

package com.dpscalc.scenario;

import java.awt.*;
import java.util.*;
import java.util.List;

import javax.swing.*;

public final class PlotPanel extends JPanel {
    private String title = "No graph data";
    private List<double[]> series = Collections.emptyList();
    private List<String> labels = Collections.emptyList();

    public PlotPanel() {
        setPreferredSize(new Dimension(220, 260));
        setBackground(CalculatorWorkspace.BG);
    }

    public void setSeries(String title, List<double[]> series, List<String> labels) {
        this.title = title;
        this.series = series;
        this.labels = labels;
        getAccessibleContext().setAccessibleName(title);
        getAccessibleContext()
                .setAccessibleDescription(
                        series.isEmpty() ? "No graph data" : String.join(", ", labels));
        repaint();
    }

    @Override
    protected void paintComponent(Graphics graphics) {
        super.paintComponent(graphics);
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            g.setColor(CalculatorWorkspace.MUTED);
            boolean probability =
                    title.startsWith("Hit distribution")
                            || title.startsWith("Kill-time distribution");
            int left = 40,
                    top = 24,
                    width = Math.max(1, getWidth() - 52),
                    height = Math.max(1, getHeight() - 110);
            double max =
                    series.stream()
                            .flatMapToDouble(Arrays::stream)
                            .filter(Double::isFinite)
                            .max()
                            .orElse(1);
            if (max <= 0) max = 1;
            int samples = series.stream().mapToInt(data -> data.length).max().orElse(1);
            for (int tick = 1; tick <= 4; tick++) {
                int y = top + height - tick * height / 4;
                g.setColor(CalculatorWorkspace.EDGE);
                g.drawLine(left, y, left + width, y);
            }
            g.setColor(CalculatorWorkspace.MUTED);
            g.drawLine(left, top, left, top + height);
            g.drawLine(left, top + height, left + width, top + height);
            g.drawString(
                    String.format(
                            java.util.Locale.ROOT,
                            probability ? "%.0f%%" : "%.2f",
                            probability ? max * 100 : max),
                    2,
                    top + 8);
            g.drawString("0", 24, top + height);
            if (probability) {
                g.drawString("0", left, top + height + 14);
                String end = String.valueOf(Math.max(0, samples - 1));
                g.drawString(
                        end, left + width - g.getFontMetrics().stringWidth(end), top + height + 14);
                g.drawString(
                        title.startsWith("Hit distribution") ? "Damage" : "Attacks to kill",
                        left + width / 2 - 20,
                        top + height + 28);
            }
            for (int s = 0; s < series.size(); s++) {
                g.setColor(
                        s == 0
                                ? CalculatorWorkspace.GOLD
                                : s == 1
                                        ? CalculatorWorkspace.BEST
                                        : Color.getHSBColor((s * .21f) % 1, .6f, .95f));
                double[] data = series.get(s);
                for (int i = 1; i < data.length; i++) {
                    if (!Double.isFinite(data[i - 1]) || !Double.isFinite(data[i])) continue;
                    g.drawLine(
                            left + (i - 1) * width / Math.max(1, samples - 1),
                            top + height - (int) (data[i - 1] / max * height),
                            left + i * width / Math.max(1, samples - 1),
                            top + height - (int) (data[i] / max * height));
                }
                if (s < 4) {
                    String label = labels.get(s);
                    while (label.length() > 1 && g.getFontMetrics().stringWidth(label) > width)
                        label = label.substring(0, label.length() - 2) + "…";
                    g.drawString(label, left, top + height + 43 + s * 12);
                }
            }
        } finally {
            g.dispose();
        }
    }
}

package com.dpscalc.scenario;

import com.loadoutlab.model.PlayerState;

import java.util.*;

public final class PotionSelection {
    public static final List<String> OPTIONS =
            Collections.unmodifiableList(
                    Arrays.asList(
                            "Super combat",
                            "Ranging",
                            "Imbued heart",
                            "Saturated heart",
                            "Forgotten brew",
                            "Overload",
                            "Overload (+)",
                            "Smelling salts",
                            "Attack",
                            "Strength",
                            "Defence",
                            "Magic",
                            "Super attack",
                            "Super strength",
                            "Super defence",
                            "Super ranging",
                            "Super magic"));

    public static Set<String> selected(Scenario.Loadout loadout) {
        Set<String> values = new LinkedHashSet<>(loadout.potions);
        if (values.isEmpty() && loadout.boost != null && !loadout.boost.equals("None"))
            values.add(loadout.boost);
        return values;
    }

    public static void toggle(Scenario.Loadout loadout, String potion) {
        Set<String> values = selected(loadout);
        if (!values.remove(potion)) values.add(potion);
        loadout.potions = values;
        loadout.boost = "None";
    }

    public static void apply(PlayerState player, Scenario.Loadout loadout) {
        // Keep legacy single-preset scenarios numerically unchanged until edited.
        if (loadout.potions.isEmpty()) {
            ScenarioCalculator.applyBoost(
                    player, loadout.boost, loadout.elapsedSeconds, loadout.divine);
            return;
        }
        int attack = 0, strength = 0, defence = 0, ranged = 0, magic = 0;
        for (String potion : loadout.potions) {
            PlayerState candidate = Scenario.copy(player);
            candidate.setAttackBoost(0);
            candidate.setStrengthBoost(0);
            candidate.setDefenceBoost(0);
            candidate.setRangedBoost(0);
            candidate.setMagicBoost(0);
            ScenarioCalculator.applyBoost(
                    candidate, potion, loadout.elapsedSeconds, loadout.divine);
            attack = Math.max(attack, candidate.getAttackBoost());
            strength = Math.max(strength, candidate.getStrengthBoost());
            defence = Math.max(defence, candidate.getDefenceBoost());
            ranged = Math.max(ranged, candidate.getRangedBoost());
            magic = Math.max(magic, candidate.getMagicBoost());
        }
        player.setAttackBoost(attack);
        player.setStrengthBoost(strength);
        player.setDefenceBoost(defence);
        player.setRangedBoost(ranged);
        player.setMagicBoost(magic);
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;
import com.loadoutlab.model.*;
import com.loadoutlab.model.MonsterStats;

import java.util.*;

/** Versioned, portable scenario. Overrides are explicit leaf paths, never live-state mutations. */
public final class Scenario {
    // RuneLiteModule binds this shared instance as the client Gson; retain portable static model
    // helpers.
    public static final Gson JSON =
            net.runelite.http.api.RuneLiteAPI.GSON
                    .newBuilder()
                    .serializeNulls()
                    .setPrettyPrinting()
                    .create();
    public int schemaVersion = 1;
    public String name = "Comparison";
    public List<Loadout> loadouts = new ArrayList<>();
    public MonsterStats target;
    public Encounter encounter = new Encounter();
    public Map<String, MonsterStats> targets = new LinkedHashMap<>();
    public Map<String, String> targetSources = new LinkedHashMap<>();
    public int selected;

    public Scenario() {
        loadouts.add(new Loadout());
    }

    public static final class Loadout {
        public String name = "Loadout 1";
        public String description = "";
        public PlayerState player = defaults();
        public Set<String> overrides = new LinkedHashSet<>();
        public Map<String, String> sources = new LinkedHashMap<>();
        public int[] inventory = new int[0];
        public CarryPlan carry = new CarryPlan();
        public String wikiSource = "";
        public String wikiRevision = "";
        public List<String> wikiNotes = new ArrayList<>();
        public List<int[]> wikiSeeds = new ArrayList<>();
        public boolean manualEquipmentStats;
        public int blowpipeDartId;
        public boolean specialAttack;
        public int specials = 1;
        public int specialEnergy = 100;
        public int specialCost = 50;
        public int rotationTicks = 100;
        public String boost = "None";
        public Set<String> potions = new LinkedHashSet<>();
        public int elapsedSeconds;
        public boolean divine;
        public boolean protectionPrayer;
        public String incomingStyle = "Unavailable";
        public int incomingMaxHit;
        public int incomingAttackRoll;
        public int incomingSpeed = 4;
        public double prayerDrainPerMinute;

        public Loadout copy() {
            return JSON.fromJson(JSON.toJson(this), Loadout.class);
        }

        @Override
        public String toString() {
            return name;
        }
    }

    public static PlayerState defaults() {
        PlayerState p = new PlayerState();
        p.setAttackLevel(99);
        p.setStrengthLevel(99);
        p.setDefenceLevel(99);
        p.setRangedLevel(99);
        p.setMagicLevel(99);
        p.setPrayerLevel(99);
        p.setHitpointsLevel(99);
        p.setCurrentHitpoints(99);
        p.setCombatStyle(CombatStyle.UNARMED_PUNCH);
        p.setEquipmentStats(new EquipmentStats());
        p.setWeaponSpeed(4);
        p.setKandarinDiary(false);
        p.setOnSlayerTask(true);
        Arrays.fill(p.getEquippedItemIds(), -1);
        return p;
    }

    public static PlayerState copy(PlayerState p) {
        return JSON.fromJson(JSON.toJson(p), PlayerState.class);
    }

    public static void mergeLive(Loadout l, PlayerState live) {
        JsonObject current = JSON.toJsonTree(l.player).getAsJsonObject();
        JsonObject next = JSON.toJsonTree(live).getAsJsonObject();
        Map<String, JsonElement> leaves = flatten(next);
        for (Map.Entry<String, JsonElement> field : leaves.entrySet()) {
            String path = field.getKey();
            if (!l.overrides.contains(path) && isLive(path)) {
                put(current, path, field.getValue());
                l.sources.put(path, "Live client");
            }
        }
        l.player = JSON.fromJson(current, PlayerState.class);
    }

    public static boolean isLive(String path) {
        return path.matches("(attack|strength|defence|ranged|magic|prayer|hitpoints)Level")
                || path.matches("(attack|strength|defence|ranged|magic)Boost")
                || path.equals("currentHitpoints")
                || path.startsWith("equippedItemIds.")
                || path.startsWith("equippedItemNames.")
                || path.equals("activePrayers")
                || path.startsWith("combatStyle.")
                || path.equals("inWilderness")
                || path.equals("soulreaperStacks")
                || path.equals("spellbook")
                || path.equals("kandarinDiary");
    }

    public static Map<String, JsonElement> flatten(JsonObject object) {
        Map<String, JsonElement> leaves = new LinkedHashMap<>();
        flatten("", object, leaves);
        return leaves;
    }

    private static void flatten(String path, JsonElement value, Map<String, JsonElement> out) {
        if (value.isJsonObject()) {
            for (Map.Entry<String, JsonElement> e : value.getAsJsonObject().entrySet())
                flatten(path.isEmpty() ? e.getKey() : path + "." + e.getKey(), e.getValue(), out);
        } else if (value.isJsonArray()
                && !path.equals("activePrayers")
                && !path.equals("attributes")) {
            for (int i = 0; i < value.getAsJsonArray().size(); i++)
                flatten(path + "." + i, value.getAsJsonArray().get(i), out);
        } else out.put(path, value);
    }

    public static void put(JsonObject root, String path, JsonElement value) {
        String[] parts = path.split("\\.");
        JsonElement parent = root;
        for (int i = 0; i < parts.length - 1; i++)
            parent =
                    parent.isJsonArray()
                            ? parent.getAsJsonArray().get(Integer.parseInt(parts[i]))
                            : parent.getAsJsonObject().get(parts[i]);
        if (parent.isJsonArray())
            parent.getAsJsonArray().set(Integer.parseInt(parts[parts.length - 1]), value);
        else parent.getAsJsonObject().add(parts[parts.length - 1], value);
    }

    public static Scenario parse(String text) {
        if (text == null || text.length() > 1_000_000)
            throw new IllegalArgumentException("Scenario exceeds 1 MB");
        int depth = 0;
        boolean quoted = false, escape = false;
        for (char c : text.toCharArray()) {
            if (escape) {
                escape = false;
                continue;
            }
            if (quoted && c == '\\') {
                escape = true;
                continue;
            }
            if (c == '"') {
                quoted = !quoted;
                continue;
            }
            if (quoted) continue;
            if (c == '{' || c == '[') {
                if (++depth > 32)
                    throw new IllegalArgumentException("Scenario nesting exceeds 32 levels");
            }
            if (c == '}' || c == ']') depth--;
        }
        Scenario s;
        try {
            s = JSON.fromJson(text, Scenario.class);
        } catch (RuntimeException ex) {
            throw new IllegalArgumentException("Invalid scenario JSON", ex);
        }
        if (s == null || s.schemaVersion != 1)
            throw new IllegalArgumentException("Unsupported scenario version");
        if (s.loadouts == null || s.loadouts.isEmpty() || s.loadouts.size() > 32)
            throw new IllegalArgumentException("Use 1–32 loadouts");
        if (s.targets == null || s.targets.size() > 200 || s.targetSources == null)
            throw new IllegalArgumentException("Invalid target presets");
        if (s.selected < 0 || s.selected >= s.loadouts.size())
            throw new IllegalArgumentException("Invalid selected loadout");
        for (Loadout l : s.loadouts) validate(l);
        if (s.encounter == null) throw new IllegalArgumentException("Missing encounter settings");
        s.encounter.validate();
        if (s.target != null) validate(s.target);
        for (MonsterStats m : s.targets.values()) validate(m);
        return s;
    }

    public static void validate(Loadout l) {
        if (l == null
                || l.player == null
                || l.overrides == null
                || l.sources == null
                || l.name == null
                || l.name.length() > 200) throw new IllegalArgumentException("Invalid loadout");
        if (l.carry == null
                || l.wikiSource == null
                || l.wikiSource.length() > 1000
                || l.wikiRevision == null
                || l.wikiRevision.length() > 100
                || l.wikiNotes == null
                || l.wikiNotes.size() > 200
                || l.wikiSeeds == null
                || l.wikiSeeds.size() > 16)
            throw new IllegalArgumentException("Invalid Wiki source or inventory plan");
        l.carry.validate();
        for (String note : l.wikiNotes)
            if (note == null || note.length() > 4000)
                throw new IllegalArgumentException("Invalid Wiki note");
        for (int[] seed : l.wikiSeeds)
            if (seed == null || seed.length != 14)
                throw new IllegalArgumentException("Invalid Wiki seed");
        if (l.potions == null || !PotionSelection.OPTIONS.containsAll(l.potions))
            throw new IllegalArgumentException("Unknown potion selection");
        PlayerState p = l.player;
        if (p.getCombatStyle() == null
                || p.getCombatStyle().getAttackType() == null
                || p.getEquipmentStats() == null
                || p.getActivePrayers() == null
                || p.getActivePrayers().contains(null))
            throw new IllegalArgumentException("Invalid style, prayer or equipment");
        for (java.util.function.ToIntFunction<Prayer> bonus :
                java.util.Arrays.<java.util.function.ToIntFunction<Prayer>>asList(
                        Prayer::getAttackBonus,
                        Prayer::getStrengthBonus,
                        Prayer::getRangedBonus,
                        Prayer::getMagicBonus,
                        Prayer::getDefenceBonus))
            if (p.getActivePrayers().stream().filter(prayer -> bonus.applyAsInt(prayer) > 0).count()
                    > 1)
                throw new IllegalArgumentException(
                        "Conflicting combat prayers; select compatible prayers");
        if (p.getEquippedItemIds() == null
                || p.getEquippedItemIds().length != 14
                || p.getEquippedItemNames() == null
                || p.getEquippedItemNames().length != 14)
            throw new IllegalArgumentException("Equipment requires 14 slots");
        if (p.getEquippedItemVersions() == null
                || p.getEquippedItemVersions().length != 14
                || p.getEquippedItemCategories() == null
                || p.getEquippedItemCategories().length != 14)
            throw new IllegalArgumentException("Equipment metadata requires 14 slots");
        if (l.inventory == null || l.inventory.length > 1000)
            throw new IllegalArgumentException("Invalid inventory");
        if (p.getSpellMaxHit() < 0 || p.getSpellMaxHit() > 1000)
            throw new IllegalArgumentException("Spell max hit must be 0–1000");
        for (Map.Entry<String, JsonElement> e :
                flatten(JSON.toJsonTree(p.getEquipmentStats()).getAsJsonObject()).entrySet()) {
            double n = e.getValue().getAsDouble();
            if (!Double.isFinite(n) || n < -1000 || n > 10000)
                throw new IllegalArgumentException("Equipment bonus out of range: " + e.getKey());
        }
        Map<String, JsonElement> paths = flatten(JSON.toJsonTree(p).getAsJsonObject());
        for (String path : l.overrides)
            if (!paths.containsKey(path))
                throw new IllegalArgumentException("Unknown override: " + path);
        for (int v :
                new int[] {
                    p.getAttackLevel(),
                    p.getStrengthLevel(),
                    p.getDefenceLevel(),
                    p.getRangedLevel(),
                    p.getMagicLevel(),
                    p.getHitpointsLevel(),
                    p.getPrayerLevel()
                })
            if (v < 1 || v > 126) throw new IllegalArgumentException("Base levels must be 1–126");
        for (int v :
                new int[] {
                    p.getBoostedAttack(),
                    p.getBoostedStrength(),
                    p.getBoostedDefence(),
                    p.getBoostedRanged(),
                    p.getBoostedMagic()
                })
            if (v < 0 || v > 255)
                throw new IllegalArgumentException("Boosted levels must be 0–255");
        if (l.rotationTicks < 1
                || l.rotationTicks > 10000
                || l.specials < 0
                || l.specials > 100
                || l.specialCost < 1
                || l.specialCost > 100
                || l.specialEnergy < 0
                || l.specialEnergy > 100
                || l.elapsedSeconds < 0
                || l.elapsedSeconds > 86400)
            throw new IllegalArgumentException("Invalid rotation, energy or elapsed time");
        if (p.getCurrentHitpoints() < 0
                || p.getCurrentHitpoints() > 255
                || p.getWeaponSpeed() < 1
                || p.getWeaponSpeed() > 20)
            throw new IllegalArgumentException("Invalid HP or weapon speed");
        if (l.incomingSpeed < 1
                || l.incomingSpeed > 20
                || l.incomingMaxHit < 0
                || l.incomingMaxHit > 1000
                || l.incomingAttackRoll < 0
                || !Double.isFinite(l.prayerDrainPerMinute)
                || l.prayerDrainPerMinute < 0)
            throw new IllegalArgumentException("Invalid incoming attack or prayer drain");
    }

    public static void validate(MonsterStats m) {
        if (m == null
                || m.getName() == null
                || m.getInputs() == null
                || m.getAttributes() == null
                || m.getAttributes().contains(null)
                || m.getInputs().getDefenceReductions() == null)
            throw new IllegalArgumentException("Invalid target");
        if (m.getHitpoints() < 1
                || m.getHitpoints() > 100000
                || m.getSize() < 1
                || m.getSize() > 10)
            throw new IllegalArgumentException("Target HP must be 1–100000 and size 1–10");
        for (int v :
                new int[] {
                    m.getAttackLevel(),
                    m.getStrengthLevel(),
                    m.getDefenceLevel(),
                    m.getMagicLevel(),
                    m.getRangedLevel()
                })
            if (v < 0 || v > 10000)
                throw new IllegalArgumentException("Target levels must be 0–10000");
    }
}

package com.dpscalc.scenario;

import com.loadoutlab.calculation.*;
import com.loadoutlab.data.*;
import com.loadoutlab.equipment.EquipmentPreparationFacade;
import com.loadoutlab.model.*;

import java.util.*;

public final class ScenarioCalculator {
    private final EquipmentPreparationFacade equipment;

    public ScenarioCalculator(EquipmentPreparationFacade equipment) {
        this.equipment = equipment;
    }

    public static final class Result {
        public String name, error, breakdown;
        public DpsResult normal, special;
        public EquipmentStats equipmentStats;
        public com.loadoutlab.equipment.AmmoApplicability ammoApplicability;
        public double[] histogram;
        public Double ttk, ttkVariance, rotationDps, damageTaken, prayerSeconds;
        public Double groupDps;
        public int encounterTargets = 1, targetsHit = 1;

        public double rankingDps() {
            return groupDps == null ? normal.getDps() : groupDps;
        }

        public final List<String> warnings = new ArrayList<>();
        public final List<String> limitations = new ArrayList<>();

        public Result named(String name) {
            Result copy = new Result();
            copy.name = name;
            copy.error = error;
            copy.breakdown = breakdown;
            copy.normal = normal;
            copy.special = special;
            copy.equipmentStats = equipmentStats;
            copy.ammoApplicability = ammoApplicability;
            copy.histogram = histogram;
            copy.ttk = ttk;
            copy.ttkVariance = ttkVariance;
            copy.rotationDps = rotationDps;
            copy.damageTaken = damageTaken;
            copy.prayerSeconds = prayerSeconds;
            copy.groupDps = groupDps;
            copy.encounterTargets = encounterTargets;
            copy.targetsHit = targetsHit;
            copy.warnings.addAll(warnings);
            copy.limitations.addAll(limitations);
            return copy;
        }
    }

    public Result calculate(Scenario.Loadout loadout, MonsterStats target) {
        return calculate(loadout, target, new Encounter(), false);
    }

    public Result calculate(Scenario.Loadout loadout, MonsterStats target, Encounter encounter) {
        return calculate(loadout, target, encounter, false);
    }

    public Result score(Scenario.Loadout loadout, MonsterStats target) {
        return calculate(loadout, target, new Encounter(), true);
    }

    public Result score(Scenario.Loadout loadout, MonsterStats target, Encounter encounter) {
        return calculate(loadout, target, encounter, true);
    }

    private Result calculate(
            Scenario.Loadout loadout, MonsterStats target, Encounter encounter, boolean scoreOnly) {
        Result out = new Result();
        out.name = loadout.name;
        try {
            encounter.validate();
            Scenario.validate(loadout);
            if (target != null) Scenario.validate(target);
            PlayerState p = Scenario.copy(loadout.player);
            PotionSelection.apply(p, loadout);
            MonsterStats m = target == null ? null : MonsterScaling.scale(target);
            if (!loadout.manualEquipmentStats) {
                com.loadoutlab.equipment.EquipmentLoadout raw =
                        equipment.loadoutFromIds(p.getEquippedItemIds());
                java.util.Map<
                                com.loadoutlab.equipment.EquipmentSlot,
                                com.loadoutlab.equipment.EquipmentItem>
                        slots =
                                new java.util.EnumMap<>(
                                        com.loadoutlab.equipment.EquipmentSlot.class);
                slots.putAll(raw.asMap());
                if (loadout.blowpipeDartId > 0 && p.getWeaponId() > 0)
                    slots.put(
                            com.loadoutlab.equipment.EquipmentSlot.WEAPON,
                            com.loadoutlab.equipment.EquipmentItem.raw(
                                    p.getWeaponId(),
                                    Map.of(
                                            "blowpipeDartId",
                                            com.loadoutlab.equipment.ItemVariable.ofNumber(
                                                    loadout.blowpipeDartId))));
                equipment.prepare(
                        p,
                        com.loadoutlab.equipment.EquipmentLoadout.of(slots),
                        null,
                        EquipmentPreparationFacade.context(p, m == null ? 0 : m.getId()));
                com.loadoutlab.equipment.EquipmentCatalogItem weapon =
                        equipment.getItemFacts(p.getWeaponId());
                if (weapon != null && weapon.isTwoHanded() && p.getEquippedItemIds()[5] > 0)
                    throw new IllegalArgumentException(
                            "Two-handed weapon cannot be combined with a shield");
                if (p.isWearingAny("Toxic blowpipe", "Rosewood blowpipe")
                        && loadout.blowpipeDartId <= 0)
                    throw new IllegalArgumentException(
                            "Select a blowpipe dart ID in Conditions; loaded darts are unavailable"
                                    + " from live state");
            } else
                out.warnings.add(
                        "Manual equipment totals: item names and charge/version values must match"
                                + " the equipment being modelled.");
            out.equipmentStats = p.getEquipmentStats();
            out.ammoApplicability = p.getAmmoApplicability();
            if (m == null) throw new IllegalArgumentException("Select or create a target");
            out.normal = new DpsCalculator(p, m).calculate();
            if (encounter.grouped) {
                out.encounterTargets = encounter.targets;
                out.targetsHit = encounter.targetsHit(p);
                out.groupDps = out.normal.getDps() * out.targetsHit;
            }
            out.limitations.addAll(CoverageWarnings.forState(p, m));
            if (scoreOnly) {
                if (p.getAmmoApplicability() == com.loadoutlab.equipment.AmmoApplicability.INVALID)
                    throw new IllegalArgumentException("Incompatible ammunition");
                if (!Double.isFinite(out.normal.getDps()))
                    throw new IllegalArgumentException("Invalid DPS");
                return out;
            }
            out.warnings.addAll(out.limitations);
            if (encounter.grouped) out.warnings.add(encounter.assumption());
            if (!Double.isFinite(out.normal.getDps()))
                throw new IllegalArgumentException("Invalid attack interval or result");
            out.normal.setMonsterHp(
                    m.getInputs().getMonsterCurrentHp() > 0
                            ? m.getInputs().getMonsterCurrentHp()
                            : m.getHitpoints());
            out.histogram = DistributionAnalysis.histogram(out.normal.getAttackDistribution());
            if (out.normal.getExpectedDotDamage() == 0) {
                try {
                    double[] moments =
                            DistributionAnalysis.moments(out.histogram, out.normal.getMonsterHp());
                    double seconds = out.normal.getExpectedAttackSpeed() * 0.6;
                    out.ttk = moments[0] * seconds;
                    out.ttkVariance = moments[1] * seconds * seconds;
                } catch (IllegalArgumentException ex) {
                    out.warnings.add(ex.getMessage());
                }
            } else out.warnings.add("Kill-time distribution unavailable for delayed damage.");
            out.warnings.add(
                    "Kill times assume a fixed damage distribution and attack interval;"
                            + " HP-dependent procs, phase changes and variable attack delays need a"
                            + " dynamic model.");
            if (loadout.specialAttack) {
                try {
                    out.special = new DpsCalculator(p, m, true).calculate();
                    int maxEnergy =
                            loadout.specialEnergy
                                    + (loadout.rotationTicks
                                                    / (p.isWearing("Lightbearer") ? 25 : 50))
                                            * 10;
                    if (loadout.specials * loadout.specialCost > maxEnergy)
                        out.warnings.add("Rotation requests more special energy than available.");
                    else {
                        double ticks = loadout.specials * out.special.getExpectedAttackSpeed();
                        if (ticks > loadout.rotationTicks)
                            out.warnings.add("Special attacks exceed the rotation duration.");
                        else
                            out.rotationDps =
                                    (loadout.specials * out.special.getExpectedDamage()
                                                    + Math.floor(
                                                                    (loadout.rotationTicks - ticks)
                                                                            / out.normal
                                                                                    .getExpectedAttackSpeed())
                                                            * out.normal.getExpectedDamage())
                                            / (loadout.rotationTicks * 0.6);
                    }
                    out.warnings.add(
                            "Special model: verify weapon coverage and energy cost. Rotation uses"
                                    + " fixed target stats and average damage; it does not apply"
                                    + " sequential defence drains or enforce energy availability at"
                                    + " each attack.");
                } catch (IllegalArgumentException unavailable) {
                    out.special = null;
                    out.rotationDps = null;
                    out.warnings.add("Special result unavailable: " + unavailable.getMessage());
                }
            }
            if (!"Unavailable".equals(loadout.incomingStyle)) {
                out.damageTaken = incoming(p, loadout);
                out.warnings.add(
                        "Incoming damage uses the manually configured single attack; boss patterns,"
                                + " healing and prayer penetration are not inferred.");
            }
            if (loadout.prayerDrainPerMinute > 0)
                out.prayerSeconds =
                        p.getPrayerLevel()
                                * 60.0
                                * (1 + p.getEquipmentStats().getPrayerBonus() / 30.0)
                                / loadout.prayerDrainPerMinute;
            out.warnings.add(
                    "Independent engine; factual data snapshot 2026-09-09. See calculation limits"
                            + " for unsupported mechanics.");
            if (p.getCombatStyle().getAttackType().isMagic() && p.getSpellName() == null)
                out.warnings.add(
                        "Live spell detection unavailable: select a spell or confirm powered-staff"
                                + " behavior.");
            out.breakdown = explain(p, m, out);
            if (encounter.grouped)
                out.breakdown +=
                        "\n\n"
                                + encounter.assumption()
                                + "\nEstimated group DPS: "
                                + out.normal.getDps()
                                + " × "
                                + out.targetsHit
                                + " = "
                                + out.groupDps;
        } catch (RuntimeException ex) {
            out.error = ex.getMessage() == null ? ex.getClass().getSimpleName() : ex.getMessage();
        }
        return out;
    }

    public static void applyBoost(PlayerState p, String boost, int seconds, boolean divine) {
        int decay = divine ? 0 : seconds / 60;
        if (boost == null || boost.equals("None")) return;
        switch (boost) {
            case "Super combat":
                p.setAttackBoost(Math.max(0, 5 + p.getAttackLevel() * 15 / 100 - decay));
                p.setStrengthBoost(Math.max(0, 5 + p.getStrengthLevel() * 15 / 100 - decay));
                p.setDefenceBoost(Math.max(0, 5 + p.getDefenceLevel() * 15 / 100 - decay));
                break;
            case "Ranging":
                p.setRangedBoost(Math.max(0, 4 + p.getRangedLevel() / 10 - decay));
                break;
            case "Imbued heart":
                p.setMagicBoost(Math.max(0, 1 + p.getMagicLevel() / 10 - decay));
                break;
            case "Saturated heart":
                p.setMagicBoost(4 + p.getMagicLevel() / 10);
                break;
            case "Forgotten brew":
                p.setMagicBoost(Math.max(0, 3 + p.getMagicLevel() * 8 / 100 - decay));
                p.setAttackBoost(-Math.max(0, 2 + (p.getAttackLevel() + 9) / 10 - decay));
                p.setStrengthBoost(-Math.max(0, 2 + (p.getStrengthLevel() + 9) / 10 - decay));
                p.setDefenceBoost(-Math.max(0, 2 + (p.getDefenceLevel() + 9) / 10 - decay));
                break;
            case "Overload":
                p.setAttackBoost(5 + p.getAttackLevel() * 13 / 100);
                p.setStrengthBoost(5 + p.getStrengthLevel() * 13 / 100);
                p.setDefenceBoost(5 + p.getDefenceLevel() * 13 / 100);
                p.setRangedBoost(5 + p.getRangedLevel() * 13 / 100);
                p.setMagicBoost(5 + p.getMagicLevel() * 13 / 100);
                break;
            case "Overload (+)":
            case "Smelling salts":
                int flat = boost.equals("Overload (+)") ? 6 : 11;
                p.setAttackBoost(flat + p.getAttackLevel() * 16 / 100);
                p.setStrengthBoost(flat + p.getStrengthLevel() * 16 / 100);
                p.setDefenceBoost(flat + p.getDefenceLevel() * 16 / 100);
                p.setRangedBoost(flat + p.getRangedLevel() * 16 / 100);
                p.setMagicBoost(flat + p.getMagicLevel() * 16 / 100);
                break;
            case "Attack":
                p.setAttackBoost(Math.max(0, 3 + p.getAttackLevel() / 10 - decay));
                break;
            case "Strength":
                p.setStrengthBoost(Math.max(0, 3 + p.getStrengthLevel() / 10 - decay));
                break;
            case "Defence":
                p.setDefenceBoost(Math.max(0, 3 + p.getDefenceLevel() / 10 - decay));
                break;
            case "Magic":
                p.setMagicBoost(Math.max(0, 4 - decay));
                break;
            case "Super attack":
                p.setAttackBoost(Math.max(0, 5 + p.getAttackLevel() * 15 / 100 - decay));
                break;
            case "Super strength":
                p.setStrengthBoost(Math.max(0, 5 + p.getStrengthLevel() * 15 / 100 - decay));
                break;
            case "Super defence":
                p.setDefenceBoost(Math.max(0, 5 + p.getDefenceLevel() * 15 / 100 - decay));
                break;
            case "Super ranging":
                p.setRangedBoost(Math.max(0, 5 + p.getRangedLevel() * 15 / 100 - decay));
                break;
            case "Super magic":
                p.setMagicBoost(Math.max(0, 5 + p.getMagicLevel() * 15 / 100 - decay));
                break;
            default:
                throw new IllegalArgumentException("Unknown boost preset; use manual boosts");
        }
    }

    private static double incoming(PlayerState p, Scenario.Loadout l) {
        EquipmentStats e = p.getEquipmentStats();
        int bonus;
        switch (l.incomingStyle) {
            case "Stab":
                bonus = e.getStabDefence();
                break;
            case "Slash":
                bonus = e.getSlashDefence();
                break;
            case "Crush":
                bonus = e.getCrushDefence();
                break;
            case "Ranged":
                bonus = e.getRangedDefence();
                break;
            case "Magic":
                bonus = e.getMagicDefence();
                break;
            default:
                throw new IllegalArgumentException("Unknown incoming style");
        }
        int prayer =
                p.getActivePrayers().stream().mapToInt(Prayer::getDefenceBonus).max().orElse(0);
        int level = p.getBoostedDefence() * (100 + prayer) / 100;
        if (l.incomingStyle.equals("Magic")) level = p.getBoostedMagic() * 7 / 10 + level * 3 / 10;
        String stance = p.getCombatStyle().getStance();
        level +=
                "Defensive".equals(stance) || "Longrange".equals(stance)
                        ? 3
                        : "Controlled".equals(stance) ? 1 : 0;
        double accuracy =
                com.loadoutlab.engine.RollContest.successProbability(
                        l.incomingAttackRoll, (level + 8) * (bonus + 64));
        double expected = 0;
        for (int hit = 0; hit <= l.incomingMaxHit; hit++) {
            double damage = hit;
            if (p.isWearing("Elysian spirit shield"))
                damage = 0.3 * hit + 0.7 * Math.max(0, hit - Math.max(1, hit / 4));
            expected += damage / (l.incomingMaxHit + 1);
        }
        return l.protectionPrayer ? 0 : expected * accuracy / (l.incomingSpeed * 0.6);
    }

    private static String explain(PlayerState p, MonsterStats m, Result r) {
        DpsResult d = r.normal;
        return "Levels (base + boost)\nAttack "
                + p.getAttackLevel()
                + " + "
                + p.getAttackBoost()
                + "\nStrength "
                + p.getStrengthLevel()
                + " + "
                + p.getStrengthBoost()
                + "\nRanged "
                + p.getRangedLevel()
                + " + "
                + p.getRangedBoost()
                + "\nMagic "
                + p.getMagicLevel()
                + " + "
                + p.getMagicBoost()
                + "\nStyle: "
                + p.getCombatStyle()
                + "\nPrayers: "
                + p.getActivePrayers()
                + "\nEquipment: "
                + Arrays.toString(p.getEquippedItemNames())
                + "\nTarget attributes: "
                + m.getAttributes()
                + "\nSlayer task: "
                + p.isOnSlayerTask()
                + "\nAttack roll: "
                + d.getAttackRoll()
                + "\nDefence roll: "
                + d.getDefenceRoll()
                + "\nHit chance after weapon mechanics: "
                + d.getAccuracy()
                + "\nDirect damage: sum(damage × probability) = "
                + d.getExpectedDirectDamage()
                + "\nDelayed damage: "
                + d.getExpectedDotDamage()
                + "\nExpected interval: "
                + d.getExpectedAttackSpeed()
                + " ticks\nDPS = (direct + delayed) / (ticks × 0.6) = "
                + d.getDps()
                + "\n"
                + "TTK uses E[0]=0; E[h]=(1+sum(p[d]×E[max(0,h-d)]))/(1-p[0]). Includes overkill"
                + " and misses.\n\n"
                + String.join("\n", d.getDetails())
                + "\n\nLimits\n"
                + String.join("\n", r.warnings);
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;
import com.loadoutlab.DpsLoadoutLabPlugin;
import com.loadoutlab.data.*;
import com.loadoutlab.equipment.EquipmentPreparationFacade;
import com.loadoutlab.model.*;

import net.runelite.client.config.ConfigManager;
