package com.dpscalc.scenario;

import static com.loadoutlab.model.AttackType.*;

import com.loadoutlab.equipment.*;
import com.loadoutlab.model.*;

import java.util.*;

/** Independently specified weapon-interface facts from Wiki Combat options documentation. */
public final class WeaponStyles {
    private WeaponStyles() {}

    private static final Map<String, List<CombatStyle>> OPTIONS = load();

    private static Map<String, List<CombatStyle>> load() {
        Map<String, List<CombatStyle>> map = new HashMap<>();
        try (java.io.Reader reader =
                new java.io.InputStreamReader(
                        Objects.requireNonNull(
                                WeaponStyles.class.getResourceAsStream(
                                        "/com/loadoutlab/weapon-options.json")),
                        java.nio.charset.StandardCharsets.UTF_8)) {
            com.google.gson.JsonObject root =
                    new com.google.gson.JsonParser().parse(reader).getAsJsonObject();
            for (Map.Entry<String, com.google.gson.JsonElement> entry : root.entrySet()) {
                List<CombatStyle> styles = new ArrayList<>();
                for (com.google.gson.JsonElement value : entry.getValue().getAsJsonArray()) {
                    com.google.gson.JsonObject row = value.getAsJsonObject(),
                            bonuses = row.getAsJsonObject("bonuses");
                    String kind = row.get("type").getAsString().toUpperCase(Locale.ROOT);
                    if (kind.equals("LIGHT") || kind.equals("STANDARD") || kind.equals("HEAVY"))
                        kind = "RANGED_" + kind;
                    if (kind.equals("RANGED")) kind = "RANGED_STANDARD";
                    styles.add(
                            new CombatStyle(
                                    row.get("name").getAsString(),
                                    AttackType.valueOf(kind),
                                    row.get("stance").getAsString(),
                                    bonus(bonuses, "attack"),
                                    bonus(bonuses, "strength"),
                                    bonus(bonuses, "defence"),
                                    bonus(bonuses, "ranged"),
                                    bonus(bonuses, "magic")));
                }
                map.put(entry.getKey(), Collections.unmodifiableList(styles));
            }
        } catch (java.io.IOException e) {
            throw new IllegalStateException("Weapon option facts are unavailable", e);
        }
        return Collections.unmodifiableMap(map);
    }

    private static int bonus(com.google.gson.JsonObject row, String key) {
        return row.has(key) ? row.get(key).getAsInt() : 0;
    }

    public static List<CombatStyle> available(
            PlayerState player, EquipmentPreparationFacade equipment) {
        if (player.getWeaponId() <= 0) return OPTIONS.get("unarmed");
        EquipmentCatalogItem weapon = equipment.getItemFacts(player.getWeaponId());
        return weapon == null || weapon.getSpeed() <= 0
                ? List.of()
                : OPTIONS.getOrDefault(weapon.getCategory().toLowerCase(Locale.ROOT), List.of());
    }

    public static void select(Scenario.Loadout loadout, CombatStyle style) {
        loadout.player.setCombatStyle(style);
        for (String path :
                Scenario.flatten(Scenario.JSON.toJsonTree(loadout.player).getAsJsonObject())
                        .keySet()) if (path.startsWith("combatStyle.")) loadout.overrides.add(path);
    }

    public static void normalize(Scenario.Loadout loadout, EquipmentPreparationFacade equipment) {
        List<CombatStyle> choices = available(loadout.player, equipment);
        if (choices.isEmpty()) return;
        CombatStyle current = loadout.player.getCombatStyle();
        for (CombatStyle option : choices)
            if (current != null
                    && option.getAttackType() == current.getAttackType()
                    && option.getStance().equals(current.getStance())) {
                loadout.player.setCombatStyle(option);
                return;
            }
        select(loadout, choices.get(0));
    }
}

package com.dpscalc.scenario;

import com.dpscalc.wikisetups.WikiSetupOptions.MissingGearBehavior;
import com.dpscalc.wikisetups.bank.*;
import com.dpscalc.wikisetups.items.*;
import com.dpscalc.wikisetups.wiki.*;
import com.loadoutlab.equipment.*;

import java.util.*;
import java.util.function.IntPredicate;

/**
 * Adapts Wiki recommendations to independent calculator drafts; rankings never replace DPS scoring.
 */
public final class WikiLoadouts {
    public static final class Choice {
        public final String label;
        public final GearSetup gear;
        public final InventorySetup inventory;
        public final List<GearSetup> switches;

        public Choice(
                String label, GearSetup gear, InventorySetup inventory, List<GearSetup> switches) {
            this.label = label;
            this.gear = gear;
            this.inventory = inventory;
            this.switches = switches;
        }

        public String toString() {
            return label.replace('<', '‹').replace('>', '›');
        }
    }

    public static List<Choice> parse(String text) {
        if (text.length() > WikiSetupService.MAX_BYTES)
            throw new IllegalArgumentException("Wiki page too large");
        int depth = 0;
        for (int p = 0; p + 1 < text.length(); p++) {
            if (text.startsWith("{{", p)) {
                if (++depth > 64)
                    throw new IllegalArgumentException("Wiki template nesting exceeds 64 levels");
                p++;
            } else if (text.startsWith("}}", p)) {
                depth = Math.max(0, depth - 1);
                p++;
            }
        }
        List<Choice> choices = new ArrayList<>();
        List<GearSetup> gear = new GearSetupParser().parse(text);
        List<InventorySetup> inventories = new InventoryParser().parse(text);
        List<ExampleSetup> examples = new ExampleSetupParser().parse(text);
        GearSetups.Partition partition = GearSetups.partition(gear);
        int[] pairing =
                examples.isEmpty()
                        ? partition.remapPairing(
                                SetupPairing.pair(text, gear.size(), inventories.size()))
                        : SetupPairing.NONE;
        if (pairing.length == 0 && examples.isEmpty())
            pairing =
                    SetupPairing.pairLoadouts(
                            text, gear.size(), inventories.size(), partition.getLoadoutIndices());
        int[] named = SetupPairing.pairUniqueLabels(partition.getLoadouts(), inventories);
        if (pairing.length == 0) pairing = named;
        else for (int i = 0; i < pairing.length; i++) if (pairing[i] < 0) pairing[i] = named[i];
        for (int i = 0; i < partition.getLoadouts().size() && choices.size() < 100; i++) {
            GearSetup setup = partition.getLoadouts().get(i);
            String label =
                    Objects.toString(setup.getPaneLabel(), "")
                            + " · "
                            + Objects.toString(setup.getStyleLabel(), "Setup " + (i + 1));
            choices.add(
                    new Choice(
                            label,
                            setup,
                            pairing.length > i && pairing[i] >= 0
                                    ? inventories.get(pairing[i])
                                    : null,
                            partition.getSwitches()));
        }
        for (ExampleSetup example : examples) {
            if (choices.size() >= 100) break;
            choices.add(
                    new Choice(
                            (example.getPath().isEmpty()
                                            ? ""
                                            : String.join(" / ", example.getPath()) + " · ")
                                    + example.getLabel(),
                            example.getGear(),
                            example.getInventory(),
                            partition.getSwitches()));
        }
        return choices;
    }

    public static Scenario.Loadout draft(
            Choice choice,
            WikiSetupService.Page page,
            Scenario.Loadout base,
            OwnedEquipment owned,
            String profile,
            boolean preferOwned,
            ItemNameIndex index,
            IntPredicate stackable,
            EquipmentPreparationFacade equipment) {
        if (!index.isReady())
            throw new IllegalArgumentException("Item names are still loading. Try again shortly.");
        if (preferOwned && !owned.ready(profile))
            throw new IllegalArgumentException(
                    "Open this character's bank before choosing owned alternatives.");
        Set<Integer> ownedIds =
                owned.ready(profile) ? owned.quantities.keySet() : Collections.emptySet();
        ItemResolver resolver = new ItemResolver(index);
        OwnershipResolver ownership =
                new OwnershipResolver(
                        resolver,
                        (requested, id) -> {
                            try {
                                EquipmentCatalogItem facts = equipment.getItemFacts(id);
                                return facts != null
                                        && facts.getSlot()
                                                .equals(
                                                        requested == EquipSlot.SPECIAL
                                                                ? "weapon"
                                                                : slotName(slot(requested)));
                            } catch (IllegalArgumentException unavailable) {
                                return false;
                            }
                        });
        PickStrategy strategy =
                preferOwned ? PickStrategy.BEST_OWNED : PickStrategy.TOP_RECOMMENDATION;
        SetupResolution resolved =
                ownership.resolve(
                        choice.gear,
                        ownedIds,
                        MissingGearBehavior.SHOW_BEST_UNOWNED,
                        base.player.isOnSlayerTask(),
                        strategy);
        Scenario.Loadout draft = base.copy();
        draft.name = shortText(page.title + " · " + choice.label, 180);
        draft.manualEquipmentStats = false;
        draft.player.setRawEquipmentLoadout(null);
        draft.carry = new CarryPlan();
        draft.wikiSource = page.url();
        draft.wikiRevision = page.revision;
        draft.wikiNotes = new ArrayList<>();
        draft.wikiSeeds = new ArrayList<>();
        int[] ids = new int[14];
        Arrays.fill(ids, -1);
        String[] names = new String[14];
        for (SlotPick pick : resolved.getPicks()) {
            int slot = slot(pick.getSlot());
            int id = pick.getItemId();
            String name = Objects.toString(index.nameById(id), pick.getItem().getName());
            if (slot < 0) {
                draft.carry.switches.add(new CarryPlan.Entry(id, name, 1));
                continue;
            }
            try {
                EquipmentCatalogItem facts = equipment.getItemFacts(id);
                if (!facts.getSlot().equals(slotName(slot)))
                    throw new IllegalArgumentException("slot mismatch");
                ids[slot] = id;
                names[slot] = name;
            } catch (IllegalArgumentException error) {
                draft.wikiNotes.add("No compatible DPS data for " + name + "; slot left empty.");
                continue;
            }
            draft.wikiNotes.add(
                    BankOptimizer.SLOT_NAMES[indexOfSlot(slot)]
                            + ": "
                            + name
                            + " — "
                            + (owned.ready(profile)
                                    ? pick.isOwned()
                                            ? (pick.isTopRecommendation()
                                                    ? "owned"
                                                    : "owned alternative")
                                            : "missing"
                                    : "ownership unknown")
                            + ". "
                            + Objects.toString(pick.getItem().getNote(), ""));
        }
        resolved.getUnresolvedNames()
                .forEach(
                        (slot, unknown) ->
                                draft.wikiNotes.add(
                                        "Unrecognized or unsupported "
                                                + slot
                                                + ": "
                                                + String.join(", ", unknown)));
        if (ids[3] > 0 && equipment.getItemFacts(ids[3]).isTwoHanded() && ids[5] > 0) {
            draft.wikiNotes.add("Off-hand removed for a two-handed weapon.");
            ids[5] = -1;
            names[5] = null;
        }
        draft.player.setEquippedItemIds(ids);
        draft.player.setEquippedItemNames(names);
        WeaponStyles.normalize(draft, equipment);
        String label = choice.label.toLowerCase(Locale.ROOT);
        String family =
                label.contains("magic") || label.contains("burst") || label.contains("barrage")
                        ? "Magic"
                        : label.contains("ranged")
                                ? "Ranged"
                                : label.contains("melee") ? "Melee" : "";
        for (com.loadoutlab.model.CombatStyle style :
                WeaponStyles.available(draft.player, equipment)) {
            String type =
                    style.getAttackType().isMagic()
                            ? "Magic"
                            : style.getAttackType().isRanged() ? "Ranged" : "Melee";
            if (type.equals(family)) {
                WeaponStyles.select(draft, style);
                break;
            }
        }
        if (choice.inventory != null) {
            InventoryResolution inventory =
                    new InventoryResolver(resolver)
                            .resolve(
                                    choice.inventory,
                                    ownedIds,
                                    MissingGearBehavior.SHOW_BEST_UNOWNED,
                                    Collections.singletonList(choice.gear),
                                    strategy);
            fill(
                    draft.carry.slots,
                    choice.inventory.getSlots(),
                    inventory.getPicks(),
                    choice.inventory,
                    false,
                    index,
                    stackable);
            fill(
                    draft.carry.runes,
                    choice.inventory.getRunes(),
                    inventory.getRunePicks(),
                    choice.inventory,
                    true,
                    index,
                    stackable);
        } else
            draft.wikiNotes.add(
                    "No unambiguous inventory pairing found; add supplies in Equipment.");
        for (GearSetup extra : choice.switches) {
            SetupResolution switches =
                    ownership.resolve(
                            extra,
                            ownedIds,
                            MissingGearBehavior.SHOW_BEST_UNOWNED,
                            base.player.isOnSlayerTask(),
                            strategy);
            for (SlotPick pick : switches.getPicks()) {
                if (draft.carry.switches.size() >= 28) break;
                CarryPlan.Entry entry =
                        new CarryPlan.Entry(
                                pick.getItemId(),
                                Objects.toString(
                                        index.nameById(pick.getItemId()), pick.getItem().getName()),
                                1);
                entry.note =
                        shortText(
                                Objects.toString(extra.getStyleLabel(), "Situational switch")
                                        + ": "
                                        + Objects.toString(pick.getItem().getNote(), ""),
                                2000);
                draft.carry.switches.add(entry);
            }
        }
        draft.wikiSeeds.add(ids.clone());
        for (String path :
                Scenario.flatten(Scenario.JSON.toJsonTree(draft.player).getAsJsonObject()).keySet())
            if (path.startsWith("equippedItem")) {
                draft.overrides.add(path);
                draft.sources.put(path, "Wiki template draft");
            }
        draft.description =
                "Wiki recommendation from revision "
                        + page.revision
                        + ". Calculated against the selected target. Check Combat, Prayer and"
                        + " Settings for this method.";
        draft.wikiNotes.add(
                "Wiki ranks are starting points. The bank optimizer scores full combinations"
                        + " against your selected target.");
        draft.wikiNotes.replaceAll(n -> shortText(n, 4000));
        if (draft.wikiNotes.size() > 200)
            draft.wikiNotes = new ArrayList<>(draft.wikiNotes.subList(0, 200));
        Scenario.validate(draft);
        return draft;
    }

    private static void fill(
            CarryPlan.Entry[] into,
            List<String> source,
            List<InventoryPick> picks,
            InventorySetup setup,
            boolean rune,
            ItemNameIndex index,
            IntPredicate stackable) {
        for (int i = 0; i < source.size() && i < into.length; i++)
            if (!source.get(i).isEmpty())
                into[i] =
                        new CarryPlan.Entry(
                                0, shortText(source.get(i), 200), setup.quantity(i, rune));
        for (InventoryPick pick : picks) {
            int slot = pick.getSlot();
            if (slot >= into.length) continue;
            int quantity = setup.quantity(slot, rune);
            if (quantity == 0 && !stackable.test(pick.getItemId())) quantity = 1;
            CarryPlan.Entry entry =
                    new CarryPlan.Entry(
                            pick.getItemId(),
                            Objects.toString(index.nameById(pick.getItemId()), source.get(slot)),
                            quantity);
            entry.noted = !rune && setup.noted(slot);
            if (entry.noted)
                entry.note =
                        "Wiki requests a noted stack. Check the packing arrangement; bank tags"
                                + " store item IDs only.";
            into[slot] = entry;
        }
    }

    static int slot(EquipSlot slot) {
        switch (slot) {
            case HEAD:
                return 0;
            case CAPE:
                return 1;
            case NECK:
                return 2;
            case WEAPON:
                return 3;
            case BODY:
                return 4;
            case SHIELD:
                return 5;
            case LEGS:
                return 7;
            case HANDS:
                return 9;
            case FEET:
                return 10;
            case RING:
                return 12;
            case AMMO:
                return 13;
            default:
                return -1;
        }
    }

    static String slotName(int slot) {
        return new String[] {
                    "head", "cape", "neck", "weapon", "body", "shield", "", "legs", "", "hands",
                    "feet", "", "ring", "ammo"
                }
                [slot];
    }

    private static int indexOfSlot(int slot) {
        for (int i = 0; i < BankOptimizer.SLOTS.length; i++)
            if (BankOptimizer.SLOTS[i] == slot) return i;
        return 0;
    }

    private static String shortText(String s, int max) {
        return s.length() > max ? s.substring(0, max) : s;
    }
}

package com.dpscalc.scenario;

import com.google.gson.*;

import okhttp3.*;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.TimeUnit;

import javax.inject.*;

/** Explicit, read-only Wiki requests. No character or container data enters a request. */
@Singleton
public final class WikiSetupService {
    static final int MAX_BYTES = 2_000_000, MAX_CACHE = 16;
    private final OkHttpClient http;
    private final java.util.function.LongSupplier clock;
    private final Map<String, Page> cache =
            new LinkedHashMap<String, Page>(16, .75f, true) {
                protected boolean removeEldestEntry(Map.Entry<String, Page> e) {
                    return size() > MAX_CACHE;
                }
            };

    @Inject
    public WikiSetupService(OkHttpClient http) {
        this(http, System::currentTimeMillis);
    }

    WikiSetupService(OkHttpClient http, java.util.function.LongSupplier clock) {
        this.http = http.newBuilder().callTimeout(15, TimeUnit.SECONDS).build();
        this.clock = clock;
    }

    public static final class Page {
        public final String title, revision, text;
        public final long fetchedAt;
        public final boolean stale;

        Page(String title, String revision, String text, long fetchedAt, boolean stale) {
            this.title = title;
            this.revision = revision;
            this.text = text;
            this.fetchedAt = fetchedAt;
            this.stale = stale;
        }

        public String url() {
            return new HttpUrl.Builder()
                    .scheme("https")
                    .host("oldschool.runescape.wiki")
                    .addPathSegment("w")
                    .addPathSegment(title.replace(" ", "_"))
                    .addQueryParameter("oldid", revision)
                    .build()
                    .toString();
        }
    }

    public static final class RequestScope {
        private volatile boolean cancelled;
        private Call call;

        public synchronized void cancel() {
            cancelled = true;
            if (call != null) call.cancel();
        }

        synchronized void attach(Call next) throws IOException {
            if (cancelled) throw new IOException("Cancelled");
            call = next;
        }

        public boolean cancelled() {
            return cancelled;
        }
    }

    public List<String> search(String query, RequestScope scope) throws IOException {
        if (query.trim().isEmpty() || query.length() > 200)
            throw new IOException("Enter an activity or monster name (up to 200 characters)");
        Set<String> titles = new LinkedHashSet<>();
        for (String template : List.of("Recommended equipment", "Equipment")) {
            JsonObject root =
                    get(
                            new HttpUrl.Builder()
                                    .scheme("https")
                                    .host("oldschool.runescape.wiki")
                                    .addPathSegment("api.php")
                                    .addQueryParameter("action", "query")
                                    .addQueryParameter("format", "json")
                                    .addQueryParameter("list", "search")
                                    .addQueryParameter(
                                            "srsearch", query + " hastemplate:\"" + template + "\"")
                                    .addQueryParameter("srnamespace", "0")
                                    .addQueryParameter("srlimit", "15")
                                    .build(),
                            scope);
            for (JsonElement e : root.getAsJsonObject("query").getAsJsonArray("search"))
                titles.add(e.getAsJsonObject().get("title").getAsString());
        }
        return rankSearch(query, new ArrayList<>(titles));
    }

    static List<String> rankSearch(String query, List<String> titles) {
        String target = searchName(query);
        List<String> result = new ArrayList<>(titles);
        result.sort(
                Comparator.comparingInt(
                        title -> {
                            String name = searchName(title);
                            return name.equals(target + "/strategies")
                                    ? 0
                                    : name.equals(target)
                                            ? 1
                                            : name.startsWith(target + "/") ? 2 : 3;
                        }));
        return result;
    }

    private static String searchName(String title) {
        return title.trim().replace('_', ' ').toLowerCase(Locale.ROOT).replaceFirst("^the ", "");
    }

    public Page page(String title, RequestScope scope) throws IOException {
        if (scope.cancelled()) throw new IOException("Cancelled");
        if (title == null || title.isBlank() || title.length() > 300)
            throw new IOException("Invalid Wiki page title");
        Page cached;
        synchronized (cache) {
            cached = cache.get(title);
        }
        if (cached != null && clock.getAsLong() - cached.fetchedAt < 15 * 60_000L) return cached;
        try {
            JsonObject root =
                    get(
                            new HttpUrl.Builder()
                                    .scheme("https")
                                    .host("oldschool.runescape.wiki")
                                    .addPathSegment("api.php")
                                    .addQueryParameter("action", "parse")
                                    .addQueryParameter("format", "json")
                                    .addQueryParameter("page", title)
                                    .addQueryParameter("prop", "wikitext|revid")
                                    .addQueryParameter("redirects", "1")
                                    .build(),
                            scope);
            JsonObject p = root.getAsJsonObject("parse");
            Page page =
                    new Page(
                            p.get("title").getAsString(),
                            p.get("revid").getAsString(),
                            p.getAsJsonObject("wikitext").get("*").getAsString(),
                            clock.getAsLong(),
                            false);
            synchronized (cache) {
                cache.put(title, page);
            }
            return page;
        } catch (IOException | RuntimeException e) {
            if (cached != null && !scope.cancelled())
                return new Page(cached.title, cached.revision, cached.text, cached.fetchedAt, true);
            throw new IOException("Wiki page unavailable: " + e.getMessage(), e);
        }
    }

    private JsonObject get(HttpUrl url, RequestScope scope) throws IOException {
        Call call =
                http.newCall(
                        new Request.Builder()
                                .url(url)
                                .header(
                                        "User-Agent",
                                        "DPS-Loadout-Lab/1.0 (RuneLite;"
                                                + " https://github.com/lynchtm/dps-loadout-lab)")
                                .build());
        scope.attach(call);
        try (Response response = call.execute()) {
            if (!response.isSuccessful() || response.body() == null)
                throw new IOException("Wiki returned HTTP " + response.code());
            String text = bounded(response.body().byteStream());
            JsonObject root = new JsonParser().parse(text).getAsJsonObject();
            if (root.has("error")) throw new IOException("Wiki could not find or parse that page");
            return root;
        }
    }

    static String bounded(InputStream input) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int n;
        while ((n = input.read(buffer)) != -1) {
            if (out.size() + n > MAX_BYTES) throw new IOException("Wiki response too large");
            out.write(buffer, 0, n);
        }
        return new String(out.toByteArray(), StandardCharsets.UTF_8);
    }
}

package com.dpscalc.scenario;

import com.dpscalc.wikisetups.wiki.InventoryParser;
import com.dpscalc.wikisetups.wiki.InventorySetup;
import com.loadoutlab.DpsLoadoutLabPlugin;
import com.loadoutlab.equipment.EquipmentPreparationFacade;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;

import javax.swing.*;

/** User-initiated Wiki browser. Every import starts a new, independent comparison tab. */
final class WikiTemplatePanel extends JPanel {
    private final JPanel body = CalculatorWorkspace.column();

    private final Supplier<Scenario> model;
    private final Supplier<String> profile;
    private final DpsLoadoutLabPlugin plugin;
    private final EquipmentPreparationFacade equipment;
    private final Consumer<Scenario.Loadout> add;
    private final ThreadPoolExecutor worker =
            new ThreadPoolExecutor(
                    1,
                    1,
                    0,
                    TimeUnit.MILLISECONDS,
                    new LinkedBlockingQueue<>(),
                    r -> {
                        Thread t = new Thread(r, "dps-wiki-templates");
                        t.setDaemon(true);
                        return t;
                    });
    private WikiSetupService.RequestScope scope;
    private long generation;
    private boolean disposed, binding;
    private final JTextField query = new JTextField(), filter = new JTextField();
    private final JComboBox<String> pages = new JComboBox<>();
    private final JComboBox<WikiLoadouts.Choice> choices = new JComboBox<>();
    private final JCheckBox owned = new JCheckBox("Prefer owned alternatives", true);
    private final JTextArea
            status =
                    CalculatorWorkspace.note(
                            "Search an activity, then choose a method, tier or role. Your selected"
                                    + " target stays in use."),
            details = CalculatorWorkspace.note("");
    private final LoadoutPreview preview;
    private final InventoryPreview inventoryPreview;
    private final JComboBox<InventoryOption> inventories = new JComboBox<>();
    private List<InventorySetup> pageInventories = Collections.emptyList();
    private final JButton importButton;
    private List<WikiLoadouts.Choice> all = Collections.emptyList();
    private WikiSetupService.Page page;
    private Scenario.Loadout draft;
    private String fingerprint;
    private long bankRevision;

    WikiTemplatePanel(
            Supplier<Scenario> model,
            Supplier<String> profile,
            DpsLoadoutLabPlugin plugin,
            EquipmentPreparationFacade equipment,
            Consumer<Scenario.Loadout> add) {
        this.model = model;
        this.profile = profile;
        this.plugin = plugin;
        this.equipment = equipment;
        this.add = add;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(CalculatorWorkspace.BG);
        setVisible(false);
        JPanel heading = new JPanel(new BorderLayout());
        heading.setOpaque(false);
        heading.add(
                CalculatorWorkspace.label("Add Wiki loadout", CalculatorWorkspace.GOLD),
                BorderLayout.CENTER);
        heading.add(CalculatorWorkspace.action("Cancel", this::close), BorderLayout.EAST);
        add(heading);
        add(body);
        query.addActionListener(e -> search());
        query.getAccessibleContext().setAccessibleName("Wiki activity search");
        body.add(query);
        body.add(CalculatorWorkspace.action("Search Wiki", this::search));
        pages.setEditable(true);
        body.add(pages);
        body.add(CalculatorWorkspace.action("Load page / strategies", this::load));
        body.add(CalculatorWorkspace.label("Method, tier or role", CalculatorWorkspace.GOLD));
        filter.setToolTipText("Filter setups by method, tier or role; press Enter");
        filter.getAccessibleContext().setAccessibleName("Filter Wiki methods tiers or roles");
        filter.addActionListener(e -> filter());
        body.add(filter);
        choices.getAccessibleContext().setAccessibleName("Wiki gear setup");
        body.add(choices);
        body.add(CalculatorWorkspace.label("Inventory from guide", CalculatorWorkspace.GOLD));
        inventories.getAccessibleContext().setAccessibleName("Wiki inventory selection");
        body.add(inventories);
        inventories.addActionListener(
                e -> {
                    if (!binding) invalidatePreview();
                });
        body.add(owned);
        body.add(CalculatorWorkspace.action("Preview template", this::preview));
        preview = new LoadoutPreview(plugin::getItemManager);
        preview.setVisible(false);
        body.add(preview);
        inventoryPreview = new InventoryPreview(plugin::getItemManager);
        inventoryPreview.setVisible(false);
        body.add(inventoryPreview);
        details.setVisible(false);
        body.add(details);
        importButton =
                CalculatorWorkspace.action(
                        "Add as comparison draft",
                        () -> {
                            if (!valid()) {
                                clearPreview();
                                status.setText(
                                        "Loadout or bank changed. Preview the template again.");
                                return;
                            }
                            try {
                                add.accept(draft.copy());
                                close();
                                status.setText(
                                        "Added an independent draft. Review Combat and supplies for"
                                                + " this method.");
                            } catch (RuntimeException error) {
                                clearPreview();
                                status.setText(error.getMessage());
                            }
                        });
        importButton.setEnabled(false);
        body.add(importButton);
        body.add(status);
        choices.addActionListener(
                e -> {
                    if (!binding) {
                        selectInventory();
                        invalidatePreview();
                    }
                });
        owned.addActionListener(e -> invalidatePreview());
        CalculatorWorkspace.theme(this);
    }

    private void search() {
        String q = query.getText().trim();
        run(
                request -> plugin.getWikiSetupService().search(q, request),
                titles -> {
                    pages.removeAllItems();
                    for (String title : titles) pages.addItem(title);
                    status.setText(
                            titles.isEmpty()
                                    ? "No pages found. Enter an exact Wiki title above."
                                    : "Choose a page, then load its setups.");
                });
    }

    private void load() {
        Object value = pages.getEditor().getItem();
        String title = value == null ? query.getText() : value.toString();
        run(
                request -> {
                    WikiSetupService.Page result =
                            plugin.getWikiSetupService().page(title, request);
                    List<WikiLoadouts.Choice> parsed = WikiLoadouts.parse(result.text);
                    if (parsed.isEmpty() && !title.contains("/")) {
                        try {
                            WikiSetupService.Page strategy =
                                    plugin.getWikiSetupService()
                                            .page(title + "/Strategies", request);
                            List<WikiLoadouts.Choice> other = WikiLoadouts.parse(strategy.text);
                            if (!other.isEmpty()) {
                                result = strategy;
                                parsed = other;
                            }
                        } catch (java.io.IOException ignored) {
                        }
                    }
                    return new Loaded(result, parsed);
                },
                loaded -> {
                    page = loaded.page;
                    all = loaded.choices;
                    pageInventories = new InventoryParser().parse(page.text);
                    filter();
                    status.setText(
                            (page.stale ? "Cached copy — refresh unavailable. " : "")
                                    + page.title
                                    + " · revision "
                                    + page.revision
                                    + " · "
                                    + all.size()
                                    + " setups. "
                                    + (all.isEmpty()
                                            ? "No importable loadouts on this page. Its guide may"
                                                    + " describe gear in prose."
                                            : "Choose a setup to preview."));
                    status.setToolTipText(page.url());
                });
    }

    private void filter() {
        binding = true;
        try {
            choices.removeAllItems();
            String q = filter.getText().trim().toLowerCase(Locale.ROOT);
            for (WikiLoadouts.Choice choice : all)
                if (choice.label.toLowerCase(Locale.ROOT).contains(q)) choices.addItem(choice);
        } finally {
            binding = false;
        }
        selectInventory();
        invalidatePreview();
    }

    private void selectInventory() {
        binding = true;
        try {
            inventories.removeAllItems();
            WikiLoadouts.Choice choice = (WikiLoadouts.Choice) choices.getSelectedItem();
            InventorySetup matched = choice == null ? null : choice.inventory;
            inventories.addItem(
                    new InventoryOption(
                            matched,
                            matched == null
                                    ? "No matched inventory — choose below"
                                    : "Matched: " + matched.getLabel()));
            for (int i = 0; i < pageInventories.size() && i < 100; i++)
                inventories.addItem(
                        new InventoryOption(
                                pageInventories.get(i),
                                (i + 1) + " · " + pageInventories.get(i).getLabel()));
            inventories.setSelectedIndex(0);
        } finally {
            binding = false;
        }
    }

    private void invalidatePreview() {
        generation++;
        if (scope != null) scope.cancel();
        clearPreview();
    }

    private static final class InventoryOption {
        final InventorySetup inventory;
        final String label;

        InventoryOption(InventorySetup inventory, String label) {
            this.inventory = inventory;
            this.label = label;
        }

        public String toString() {
            return label.replace('<', '‹').replace('>', '›');
        }
    }

    private void preview() {
        WikiLoadouts.Choice choice = (WikiLoadouts.Choice) choices.getSelectedItem();
        if (choice == null || page == null) {
            status.setText("Load a Wiki page and choose a setup first.");
            return;
        }
        InventoryOption inventory = (InventoryOption) inventories.getSelectedItem();
        WikiLoadouts.Choice selected =
                new WikiLoadouts.Choice(
                        choice.label,
                        choice.gear,
                        inventory == null ? choice.inventory : inventory.inventory,
                        choice.switches);
        String expected = profile.get();
        Scenario.Loadout base = model.get().loadouts.get(model.get().selected).copy();
        OwnedEquipment snapshot = plugin.getOwnedEquipment();
        String state = state();
        WikiSetupService.Page source = page;
        boolean prefer = owned.isSelected();
        run(
                request ->
                        WikiLoadouts.draft(
                                selected,
                                source,
                                base,
                                snapshot,
                                expected,
                                prefer,
                                plugin.getSetupItemIndex(),
                                plugin.getSetupItemIndex()::stackable,
                                equipment),
                result -> {
                    if (!state.equals(state())
                            || snapshot.revision != plugin.getOwnedEquipment().revision) {
                        status.setText("Loadout or bank changed. Preview again.");
                        return;
                    }
                    draft = result;
                    fingerprint = state;
                    bankRevision = snapshot.revision;
                    preview.showLoadout(draft, snapshot, expected);
                    preview.setVisible(true);
                    inventoryPreview.showPlan(draft.carry);
                    inventoryPreview.setVisible(true);
                    details.setText(String.join("\n", draft.wikiNotes));
                    details.setRows(Math.min(12, Math.max(3, draft.wikiNotes.size() * 2)));
                    details.setToolTipText(source.url());
                    details.setVisible(true);
                    importButton.setEnabled(true);
                    status.setText(
                            "Preview only · "
                                    + source.title
                                    + " revision "
                                    + source.revision
                                    + (selected.inventory == null
                                            ? ". No inventory matched; choose an inventory above if"
                                                    + " the page lists one."
                                            : ". Gear, inventory and pouch runes will be added"
                                                    + " together."));
                    resizeContent();
                });
    }

    private String state() {
        return profile.get() + "\n" + Scenario.JSON.toJson(model.get());
    }

    private boolean valid() {
        return draft != null
                && Objects.equals(fingerprint, state())
                && bankRevision == plugin.getOwnedEquipment().revision;
    }

    private String lastProfile;

    void refresh() {
        String now = profile.get();
        if (!Objects.equals(now, lastProfile)) {
            lastProfile = now;
            generation++;
            if (scope != null) scope.cancel();
            worker.getQueue().clear();
            clearPreview();
        } else if (draft != null && !valid()) clearPreview();
    }

    private void clearPreview() {
        draft = null;
        importButton.setEnabled(false);
        preview.setVisible(false);
        inventoryPreview.setVisible(false);
        details.setVisible(false);
        resizeContent();
    }

    private interface Work<T> {
        T run(WikiSetupService.RequestScope request) throws Exception;
    }

    private <T> void run(Work<T> work, Consumer<T> accept) {
        if (plugin.getWikiSetupService() == null) {
            status.setText("Wiki service unavailable in this preview client.");
            return;
        }
        clearPreview();
        long token = ++generation;
        if (scope != null) scope.cancel();
        scope = new WikiSetupService.RequestScope();
        WikiSetupService.RequestScope request = scope;
        worker.getQueue().clear();
        status.setText("Loading…");
        String expected = profile.get();
        worker.submit(
                () -> {
                    try {
                        T value = work.run(request);
                        SwingUtilities.invokeLater(
                                () -> {
                                    if (!disposed
                                            && token == generation
                                            && Objects.equals(expected, profile.get())) {
                                        accept.accept(value);
                                        resizeContent();
                                    }
                                });
                    } catch (Exception error) {
                        SwingUtilities.invokeLater(
                                () -> {
                                    if (!disposed
                                            && token == generation
                                            && Objects.equals(expected, profile.get()))
                                        status.setText(
                                                "Could not load: "
                                                        + Objects.toString(
                                                                error.getMessage(),
                                                                "invalid Wiki data"));
                                });
                    }
                });
    }

    private void resizeContent() {
        for (Container parent = this; parent != null; parent = parent.getParent())
            parent.invalidate();
        super.revalidate();
    }

    void open() {
        setVisible(true);
        String target =
                model.get().target == null
                        ? ""
                        : Objects.toString(model.get().target.getName(), "");
        query.setText(target);
        filter.setText("");
        page = null;
        all = Collections.emptyList();
        pageInventories = Collections.emptyList();
        pages.removeAllItems();
        choices.removeAllItems();
        selectInventory();
        clearPreview();
        query.requestFocusInWindow();
        resizeContent();
        if (!target.isEmpty()) search();
        else status.setText("Search an activity or enter a Wiki page title.");
    }

    void close() {
        generation++;
        if (scope != null) scope.cancel();
        worker.getQueue().clear();
        clearPreview();
        setVisible(false);
        resizeContent();
    }

    void dispose() {
        disposed = true;
        generation++;
        if (scope != null) scope.cancel();
        worker.shutdownNow();
    }

    private static final class Loaded {
        final WikiSetupService.Page page;
        final List<WikiLoadouts.Choice> choices;

        Loaded(WikiSetupService.Page p, List<WikiLoadouts.Choice> c) {
            page = p;
            choices = c;
        }
    }
}

package com.dpscalc.scenario;

import java.util.Objects;

/** Immediate, deduplicated writes: no pending draft can be lost at a profile switch. */
final class WorkspacePersistence {
    private final ScenarioStorage storage;
    private String lastKey, lastJson;

    WorkspacePersistence(ScenarioStorage storage) {
        this.storage = storage;
    }

    void save(Scenario scenario, String profile, long configProfile) {
        if (configProfile != storage.profileId()
                || !Objects.equals(profile, storage.getRSProfileKey())) return;
        String key = configProfile + "/" + profile;
        String json = Scenario.JSON.toJson(scenario);
        if (key.equals(lastKey) && json.equals(lastJson)) return;
        storage.setConfiguration("wikiDpsScenarios", profile, "workspaceV1", json);
        lastKey = key;
        lastJson = json;
    }

    void reset() {
        lastKey = null;
        lastJson = null;
    }
}

package com.dpscalc.scenario;

import java.awt.*;

import javax.swing.*;

/** A major sidebar section. The entire header is one native button hit target. */
final class WorkspaceSection extends JPanel {
    private final JPanel body;
    private final Heading heading;
    private final String title;

    WorkspaceSection(String title, String subtitle, JPanel body, boolean expanded) {
        this.title = title;
        this.body = body;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createLineBorder(CalculatorWorkspace.EDGE));
        putClientProperty("wikiDpsSurface", CalculatorWorkspace.CARD);
        getAccessibleContext().setAccessibleName(title + " section");
        heading = new Heading(title, subtitle);
        heading.addActionListener(e -> setExpanded(!body.isVisible()));
        body.setBorder(
                BorderFactory.createCompoundBorder(
                        body.getBorder(), BorderFactory.createEmptyBorder(10, 8, 10, 8)));
        body.putClientProperty("wikiDpsSurface", CalculatorWorkspace.CARD);
        add(heading);
        add(body);
        setExpanded(expanded);
    }

    void setExpanded(boolean expanded) {
        boolean previous = body.isVisible();
        body.setVisible(expanded);
        heading.setText((expanded ? "▾ " : "▸ ") + title);
        heading.getAccessibleContext()
                .setAccessibleDescription(
                        (expanded ? "Expanded. " : "Collapsed. ") + heading.subtitle);
        for (Container parent = this; parent != null; parent = parent.getParent())
            parent.invalidate();
        revalidate();
        repaint();
        firePropertyChange("expanded", previous, expanded);
    }

    boolean isExpanded() {
        return body.isVisible();
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    static final class Heading extends JButton {
        private final String title, subtitle;

        Heading(String title, String subtitle) {
            this.title = title;
            this.subtitle = subtitle;
            getAccessibleContext().setAccessibleName(title);
            setToolTipText(subtitle);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        }

        @Override
        public Dimension getPreferredSize() {
            return new Dimension(170, 52);
        }

        @Override
        public Dimension getMinimumSize() {
            return new Dimension(0, 52);
        }

        @Override
        protected void paintComponent(Graphics graphics) {
            Graphics2D g = (Graphics2D) graphics.create();
            g.setColor(
                    getModel().isRollover()
                            ? CalculatorWorkspace.FIELD
                            : CalculatorWorkspace.HEADER);
            g.fillRect(0, 0, getWidth(), getHeight());
            g.setColor(CalculatorWorkspace.TEXT);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
            g.drawString(title, 10, 21);
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            g.setColor(CalculatorWorkspace.MUTED);
            Shape clip = g.getClip();
            g.clipRect(10, 25, Math.max(0, getWidth() - 30), 20);
            g.drawString(subtitle, 10, 38);
            g.setClip(clip);
            g.drawString(getText().startsWith("▾") ? "▾" : "▸", getWidth() - 17, 23);
            g.setColor(CalculatorWorkspace.EDGE);
            g.drawLine(0, getHeight() - 1, getWidth(), getHeight() - 1);
            if (hasFocus()) {
                g.setColor(CalculatorWorkspace.GOLD);
                g.drawRect(2, 2, getWidth() - 5, getHeight() - 5);
            }
            g.dispose();
        }

        @Override
        protected void paintBorder(Graphics g) {}
    }
}

