/** One inventory slot resolved to a concrete item id. slot is 0-based (0-27). */
public class InventoryPick
{
	private final int slot;
	private final int itemId;
	private final boolean owned;

	public InventoryPick(int slot, int itemId, boolean owned) { this.slot = slot; this.itemId = itemId; this.owned = owned; }
	public int getSlot() { return slot; }
	public int getItemId() { return itemId; }
	public boolean isOwned() { return owned; }
}

