                type.isMelee() && accurate ? 3 : shared,
                type.isMelee() && "Aggressive".equals(stance) ? 3 : shared,
                defensive ? 3 : longrange ? (type.isMagic() ? 1 : 3) : shared,
                type.isRanged() && accurate ? 3 : 0,
