        base.player.getEquippedItemIds()[4] = 29022;
        base.player.getEquippedItemIds()[7] = 29025;
        BankOptimizer.Result result =
                new BankOptimizer(equipment)
                        .search(
                                new BankOptimizer.Request(
                                        base,
