    public void iconTabsRespondAtTheirCentersAndEdges() throws Exception {
        SwingUtilities.invokeAndWait(
                () -> {
                    ScenarioPanel panel =
                            new ScenarioPanel(
                                    new DpsLoadoutLabPlugin(),
                                    new MonsterDataManager(),
                                    new MemoryStorage(),
                                    new EquipmentPreparationFacade());
                    try {
                        JTabbedPane tabs =
