		InventoryResolver r = new InventoryResolver(new ItemResolver(
			FakeItemNameIndex.of(SHARK, "Shark", fireRune, "Fire rune")));
		InventorySetup s = new InventorySetup("Test",
			Collections.nCopies(28, ""), Arrays.asList("Fire rune"));

